def _child_btn_flags_all() -> dict:
    try:
        if not os.path.exists(_CHILD_BTN_FLAGS_PATH):
            return {}
        with open(_CHILD_BTN_FLAGS_PATH, "r", encoding="utf-8") as _f:
            return _json_btnflags.load(_f) or {}
    except Exception:
        return {}

def _child_btn_flags_save(d: dict) -> bool:
    try:
        tmp = _CHILD_BTN_FLAGS_PATH + ".tmp"
        with open(tmp, "w", encoding="utf-8") as _f:
            _json_btnflags.dump(d, _f, ensure_ascii=False)
        os.replace(tmp, _CHILD_BTN_FLAGS_PATH)
        return True
    except Exception:
        return False

def get_child_btn_flag(bid, key: str, default: bool = True) -> bool:
    """Bola-botning bir tugmasi yoqilganmi?"""
    try:
        d = _child_btn_flags_all()
        row = d.get(str(bid)) or {}
        if key in row:
            return bool(row[key])
        return bool(default)
    except Exception:
        return bool(default)

def set_child_btn_flag(bid, key: str, value: bool) -> bool:
    d = _child_btn_flags_all()
    row = d.setdefault(str(bid), {})
    row[key] = bool(value)
    d[str(bid)] = row
    return _child_btn_flags_save(d)

def _btn_flag_default(key: str) -> bool:
    for k, _lbl, dflt in VIP_CHILD_BUTTONS:
        if k == key:
            return bool(dflt)
    return True

