def _simple_bar_chart(labels, values, title="Statistika", bar_color=(88, 101, 242)):
    """Oddiy chiroyli bar-chart (PNG bytes) yasaydi — obunachi/foydalanuvchi
    o'sishini davrlar bo'yicha ko'rsatish uchun. PIL bo'lmasa None qaytaradi."""
    if not PIL_AVAILABLE:
        return None
    try:
        SCALE   = 2
        W       = 900 * SCALE
        PAD     = 50 * SCALE
        BAR_AREA_H = 380 * SCALE
        TITLE_H = 80 * SCALE
        LABEL_H = 60 * SCALE
        H       = TITLE_H + BAR_AREA_H + LABEL_H + PAD

        BG      = (255, 255, 255)
        GRID    = (232, 234, 240)
        TEXT    = (30, 32, 40)
        SUBTEXT = (120, 124, 140)

        img  = Image.new("RGB", (W, H), BG)
        d    = ImageDraw.Draw(img)

        font_paths_bold = [
            "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
            "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
        ]
        font_paths_reg = [
            "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
            "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
        ]
        def try_font(size, bold=True):
            for p in (font_paths_bold if bold else font_paths_reg):
                if os.path.exists(p):
                    try: return ImageFont.truetype(p, size)
                    except Exception: continue
            try: return ImageFont.load_default(size=size)
            except TypeError: return ImageFont.load_default()

        fnt_title = try_font(34 * SCALE)
        fnt_val   = try_font(26 * SCALE)
        fnt_label = try_font(22 * SCALE, bold=False)

        # Title
        tb = d.textbbox((0, 0), title, font=fnt_title)
        d.text(((W - (tb[2]-tb[0])) // 2, (TITLE_H - (tb[3]-tb[1])) // 2 - tb[1]),
               title, font=fnt_title, fill=TEXT)

        n = max(len(values), 1)
        max_val = max(values) if values and max(values) > 0 else 1
        chart_top = TITLE_H
        chart_bottom = TITLE_H + BAR_AREA_H
        # gorizontal grid chiziqlari
        for i in range(5):
            gy = chart_bottom - int(BAR_AREA_H * i / 4)
            d.line([(PAD, gy), (W - PAD, gy)], fill=GRID, width=1)

        slot_w = (W - 2 * PAD) / n
        bar_w  = slot_w * 0.5
        for i, (lab, val) in enumerate(zip(labels, values)):
            slot_cx = PAD + slot_w * (i + 0.5)
            bar_h = int(BAR_AREA_H * 0.85 * (val / max_val)) if max_val else 0
            x0 = slot_cx - bar_w / 2
            x1 = slot_cx + bar_w / 2
            y1 = chart_bottom
            y0 = chart_bottom - bar_h
            radius = min(14 * SCALE, int(bar_w / 2))
            try:
                d.rounded_rectangle([x0, y0, x1, y1], radius=radius, fill=bar_color)
            except Exception:
                d.rectangle([x0, y0, x1, y1], fill=bar_color)
            vtxt = str(val)
            vb = d.textbbox((0, 0), vtxt, font=fnt_val)
            d.text((slot_cx - (vb[2]-vb[0]) / 2, y0 - (vb[3]-vb[1]) - 10 * SCALE),
                   vtxt, font=fnt_val, fill=TEXT)
            lb = d.textbbox((0, 0), lab, font=fnt_label)
            d.text((slot_cx - (lb[2]-lb[0]) / 2, chart_bottom + 14 * SCALE),
                   lab, font=fnt_label, fill=SUBTEXT)

        buf = BytesIO()
        img.save(buf, format="PNG")
        buf.seek(0)
        return buf
    except Exception as e:
        try: logger.error(f"_simple_bar_chart xato: {e}")
        except Exception: pass
        return None


def _period_join_counts(joined_iso_list):
    """joined_at ISO satrlar ro'yxati asosida bugun/1-hafta/10-kun/20-kun/1-oy
    ichida qo'shilganlar sonini hisoblaydi."""
    now = datetime.now()
    today_start = datetime(now.year, now.month, now.day)
    counts = {"today": 0, "week": 0, "d10": 0, "d20": 0, "month": 0}
    for iso in joined_iso_list:
        if not iso:
            continue
        try:
            jd = datetime.fromisoformat(iso)
        except Exception:
            continue
        if jd >= today_start:
            counts["today"] += 1
        if jd >= now - timedelta(days=7):
            counts["week"] += 1
        if jd >= now - timedelta(days=10):
            counts["d10"] += 1
        if jd >= now - timedelta(days=20):
            counts["d20"] += 1
        if jd >= now - timedelta(days=30):
            counts["month"] += 1
    return counts

