# ─── PostgreSQL persist: tariflar va narx restartda yo'qolmaydi ────────
# ─── FAYL-ASOSLI KV MIRROR (restart / Postgres yo'q bo'lsa ham o'chmaydi) ──
# MUAMMO: _pg_kv_set fonda ishlaydi va darhol qaytadi. Postgres sekin/xato
# javob bersa yozuv "yoqoldi"ga o'xshab qoladi (masalan VIP bot: tarif/karta
# qo'shildi deydi, /start bosilsa hech narsa saqlanmagan). YECHIM: har yozuvni
# AVVAL diskka SINXRON yozib qo'yamiz (child_data/kv_<suffix>_<key>.json),
# o'qishda ham AVVAL fayldan olamiz. Postgres — qo'shimcha zaxira.
def _kv_file_path(key: str) -> str:
    try:
        suffix = globals().get("_factory_local_suffix") or "root"
    except Exception:
        suffix = "root"
    safe_key = re.sub(r"[^a-zA-Z0-9_.-]+", "_", str(key))[:120] or "key"
    return os.path.join(_PERSIST_DIR, f"kv_{suffix}_{safe_key}.json")

def _kv_file_read(key: str):
    p = _kv_file_path(key)
    try:
        if not os.path.exists(p):
            return None
        with open(p, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return None

def _kv_file_write(key: str, value) -> bool:
    p = _kv_file_path(key)
    try:
        tmp = p + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(value, f, ensure_ascii=False)
        os.replace(tmp, p)
        return True
    except Exception as e:
        try: logger.error(f"_kv_file_write({key}) xato: {e}")
        except: pass
        return False

def _pg_kv_get(key: str):
    """AVVAL mahalliy fayldan, keyin bot_data jadvalidan o'qiydi."""
    val = _kv_file_read(key)
    if val is not None:
        return val
    try:
        if not globals().get("DATABASE_URL") or not globals().get("PSYCOPG2_AVAILABLE"):
            return None
        conn = _get_pg_conn()
        if not conn:
            return None
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT value FROM bot_data WHERE key = %s", (key,))
                row = cur.fetchone()
        finally:
            try: conn.close()
            except: pass
        if not row:
            return None
        val = row[0]
        if isinstance(val, str):
            try: val = json.loads(val)
            except: return None
        # Postgres'dan olindi — mahalliy faylga ham mirror qilib qo'yamiz
        try: _kv_file_write(key, val)
        except Exception: pass
        return val
    except Exception as e:
        try: logger.error(f"_pg_kv_get({key}) xato: {e}")
        except: pass
        return None

def _pg_kv_set(key: str, value) -> bool:
    """AVVAL diskka sinxron yozadi (restart/Postgres yo'q bo'lsa ham
    yo'qolmaydi), keyin fonda Postgres'ga yozadi."""
    # 1) MAHALLIY FAYL — sinxron, ishonchli
    file_ok = _kv_file_write(key, value)
    # 2) POSTGRES — zaxira, fonda
    if not globals().get("DATABASE_URL") or not globals().get("PSYCOPG2_AVAILABLE"):
        return file_ok

    def _worker():
        try:
            conn = _get_pg_conn()
            if not conn:
                return
            try:
                with conn.cursor() as cur:
                    cur.execute("""
                        INSERT INTO bot_data (key, value, updated_at)
                        VALUES (%s, %s, NOW())
                        ON CONFLICT (key) DO UPDATE
                        SET value = EXCLUDED.value, updated_at = NOW()
                    """, (key, json.dumps(value, ensure_ascii=False)))
                conn.commit()
            finally:
                try: conn.close()
                except: pass
        except Exception as e:
            try: logger.error(f"_pg_kv_set({key}) xato (fon oqim): {e}")
            except: pass

    try:
        import threading as _pgkv_threading
        _pgkv_threading.Thread(target=_worker, daemon=True).start()
        return True or file_ok
    except Exception as e:
        try: logger.error(f"_pg_kv_set({key}) oqim ishga tushmadi: {e}")
        except: pass
        return file_ok


def load_create_price() -> int:
    """Bot yaratish narxini PostgreSQL/fayldan o'qiydi. Default 150_000."""
    # 1) PostgreSQL (restartga chidamli)
    try:
        pg_val = _pg_kv_get("factory_create_price")
        if isinstance(pg_val, dict) and "price" in pg_val:
            p = int(pg_val.get("price", 150_000))
            if p >= 0:
                # lokal faylga sync (cache)
                try:
                    with open(FACTORY_PRICE_FILE, "w", encoding="utf-8") as f:
                        json.dump({"price": p}, f, ensure_ascii=False)
                except: pass
                return p
    except Exception as e:
        logger.error(f"load_create_price PG: {e}")
    # 2) Lokal fayl (fallback)
    try:
        if os.path.exists(FACTORY_PRICE_FILE):
            with open(FACTORY_PRICE_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            p = int(data.get("price", 150_000))
            if p >= 0:
                return p
    except Exception as e:
        logger.error(f"load_create_price: {e}")
    return 150_000

def save_create_price(price: int) -> bool:
    """Bot yaratish narxini PostgreSQL ga + faylga saqlaydi."""
    ok_local = False
    try:
        with open(FACTORY_PRICE_FILE, "w", encoding="utf-8") as f:
            json.dump({"price": int(price)}, f, ensure_ascii=False)
        ok_local = True
    except Exception as e:
        logger.error(f"save_create_price fayl: {e}")
    # PostgreSQL — restartda yo'qolmaydi
    try:
        _pg_kv_set("factory_create_price", {"price": int(price)})
    except Exception as e:
        logger.error(f"save_create_price PG: {e}")
    return ok_local

def load_trial_days() -> int:
    """Yangi bot yaratilganda beriladigan tekin kunlar sonini PostgreSQL/fayldan o'qiydi. Default 30."""
    try:
        pg_val = _pg_kv_get("factory_trial_days")
        if isinstance(pg_val, dict) and "days" in pg_val:
            d = int(pg_val.get("days", 30))
            if d >= 0:
                try:
                    with open(FACTORY_TRIAL_DAYS_FILE, "w", encoding="utf-8") as f:
                        json.dump({"days": d}, f, ensure_ascii=False)
                except: pass
                return d
    except Exception as e:
        logger.error(f"load_trial_days PG: {e}")
    try:
        if os.path.exists(FACTORY_TRIAL_DAYS_FILE):
            with open(FACTORY_TRIAL_DAYS_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            d = int(data.get("days", 30))
            if d >= 0:
                return d
    except Exception as e:
        logger.error(f"load_trial_days: {e}")
    return 30

