# ── 💸 Pul yechish MINIMALKASI (barcha botlar uchun global) ──────────────────
_WITHDRAW_MIN_DEFAULT = 25000
_WITHDRAW_MIN_CACHE = {"val": None, "ts": 0.0}
_WITHDRAW_MIN_TTL = 30.0  # sekund — DB yuklamasini kamaytirish uchun
_WITHDRAW_MIN_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "withdraw_min.json")

# 🔒 Balansdan yechishni parallel so'rovlardan himoya qilish uchun lock
_WITHDRAW_LOCK = asyncio.Lock()

_WITHDRAW_PCT_DEFAULT = 5  # foiz (komissiya) — default 5%

def _read_withdraw_file() -> dict:
    """withdraw_min.json ni to'liq o'qiydi. Format: {"amount": int, "pct": int}."""
    try:
        if not os.path.exists(_WITHDRAW_MIN_FILE):
            return {}
        with open(_WITHDRAW_MIN_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        if isinstance(data, dict):
            return data
        # eski format — faqat raqam bo'lsa
        try:
            return {"amount": int(data)}
        except Exception:
            return {}
    except Exception as e:
        try: logger.error(f"withdraw_min faylini o'qishda xato: {e}")
        except Exception: pass
        return {}

def _read_withdraw_min_file() -> int | None:
    d = _read_withdraw_file()
    try:
        amount = int(d.get("amount") or 0)
        return amount if amount >= 1000 else None
    except Exception:
        return None

def _read_withdraw_pct_file() -> int | None:
    d = _read_withdraw_file()
    try:
        if "pct" not in d:
            return None
        pct = int(d.get("pct"))
        if 0 <= pct <= 50:
            return pct
        return None
    except Exception:
        return None

def _write_withdraw_file(amount: int | None = None, pct: int | None = None) -> None:
    folder = os.path.dirname(_WITHDRAW_MIN_FILE) or "."
    os.makedirs(folder, exist_ok=True)
    # eski qiymatlarni saqlab, yangilarini ustiga yozamiz
    cur = _read_withdraw_file()
    if amount is not None:
        cur["amount"] = int(amount)
    if pct is not None:
        cur["pct"] = int(pct)
    cur["updated_at"] = int(time.time())
    tmp = _WITHDRAW_MIN_FILE + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(cur, f, ensure_ascii=False, indent=2)
    os.replace(tmp, _WITHDRAW_MIN_FILE)

def _write_withdraw_min_file(amount: int) -> None:
    _write_withdraw_file(amount=amount)

def get_withdraw_min() -> int:
    """
    Barcha botlarda (kino, VIP, ...) pul yechish minimal miqdorini qaytaradi.
    Lokal JSON fayldan o'qiydi. 30s cache — barcha bola-botlar shu faylni ko'radi.
    """
    try:
        now = time.time()
        if (_WITHDRAW_MIN_CACHE["val"] is not None
                and (now - _WITHDRAW_MIN_CACHE["ts"]) < _WITHDRAW_MIN_TTL):
            return int(_WITHDRAW_MIN_CACHE["val"])
        result = _read_withdraw_min_file() or _WITHDRAW_MIN_DEFAULT
        _WITHDRAW_MIN_CACHE["val"] = result
        _WITHDRAW_MIN_CACHE["ts"] = now
        return result
    except Exception:
        return _WITHDRAW_MIN_DEFAULT

def get_withdraw_pct() -> int:
    """Yechish komissiyasi foizini (0..50) qaytaradi. Default: 5%."""
    try:
        pct = _read_withdraw_pct_file()
        if pct is None:
            return _WITHDRAW_PCT_DEFAULT
        return int(pct)
    except Exception:
        return _WITHDRAW_PCT_DEFAULT

def calc_withdraw_fee(amount: int) -> tuple[int, int, int]:
    """(pct, commission, net) uchligini qaytaradi."""
    try:
        pct = get_withdraw_pct()
        amt = int(amount)
        commission = amt * pct // 100
        net = amt - commission
        return pct, commission, net
    except Exception:
        return _WITHDRAW_PCT_DEFAULT, 0, int(amount)

def set_withdraw_min(amount: int) -> bool:
    try:
        amt = max(1000, int(amount))
        _write_withdraw_file(amount=amt)
        _WITHDRAW_MIN_CACHE["val"] = None  # cache invalidate
        _WITHDRAW_MIN_CACHE["ts"] = 0.0
        return True
    except Exception as e:
        try: logger.error(f"set_withdraw_min: {e}")
        except Exception: pass
        return False

def set_withdraw_pct(pct: int) -> bool:
    try:
        p = int(pct)
        if p < 0 or p > 50:
            return False
        _write_withdraw_file(pct=p)
        return True
    except Exception as e:
        try: logger.error(f"set_withdraw_pct: {e}")
        except Exception: pass
        return False

# ── 📢 REKLAMA MATNI (asosiy bot admini o'zgartiradi, barcha botlar o'qiydi) ──
_AD_TEXT_DEFAULT = "📢 Reklama berish uchun admin bilan bog'laning"
_AD_TEXT_CACHE = {"val": None, "ts": 0.0}
_AD_TEXT_TTL = 60.0

def get_ad_text() -> str:
    """Global reklama matni. 60s cache."""
    try:
        now = time.time()
        if _AD_TEXT_CACHE["val"] is not None and (now - _AD_TEXT_CACHE["ts"]) < _AD_TEXT_TTL:
            return str(_AD_TEXT_CACHE["val"])
        val = _pg_kv_get("ad_text") or {}
        if isinstance(val, dict):
            txt = str(val.get("text") or "").strip()
        else:
            txt = str(val or "").strip()
        result = txt if txt else _AD_TEXT_DEFAULT
        _AD_TEXT_CACHE["val"] = result
        _AD_TEXT_CACHE["ts"] = now
        return result
    except Exception:
        return _AD_TEXT_DEFAULT

def set_ad_text(text: str) -> bool:
    try:
        txt = (text or "").strip()[:1000]
        if not txt:
            return False
        _pg_kv_set("ad_text", {"text": txt})
        _AD_TEXT_CACHE["val"] = None
        _AD_TEXT_CACHE["ts"] = 0.0
        return True
    except Exception as e:
        try: logger.error(f"set_ad_text: {e}")
        except Exception: pass
        return False



def _parse_tariffs_list(data) -> list[dict]:
    """Kelgan qiymatni tariflar ro'yxatiga aylantiradi (dict/list/oldingi format)."""
    if isinstance(data, dict) and "tariffs" in data:
        data = data.get("tariffs")
    out = []
    if isinstance(data, list):
        for t in data:
            if not isinstance(t, dict):
                continue
            try:
                d = int(t.get("days") or 0)
                p_ = int(t.get("price") or 0)
                lbl = str(t.get("label") or f"{d} kun")
                if d > 0 and p_ >= 0:
                    out.append({"label": lbl, "days": d, "price": p_})
            except Exception:
                continue
    return out

# Har bir bot turi uchun alohida tarif to'plami saqlanadi
FACTORY_BOT_TYPES = ["kino", "vip", "vip_pro", "uc", "yulduz", "auto_tolov", "openbudget"]
FACTORY_BOT_TYPE_LABELS = {
    "kino":     "🎬 Dramlar bot",
    "vip":      "💎 VIP kanal bot",
    "vip_pro":  "💎 VIP kanal PRO",
    "uc":       "🎮 UC sotish bot",
    "yulduz":   "⭐ Yulduz bot",
    "openbudget": "💰 Openbudget bot",
}

def _default_tariffs_dict() -> dict:
    return {bt: [dict(t) for t in _DEFAULT_EXTEND_TARIFFS] for bt in FACTORY_BOT_TYPES}

def load_extend_tariffs() -> dict:
    """Har bir bot turi bo'yicha alohida tariflar. Eski (yagona list) format
    avtomatik migratsiya qilinadi — barcha turlarga tarqatiladi."""
    result = _default_tariffs_dict()
    parsed = None
    try:
        pg_val = _pg_kv_get("factory_tariffs")
        if isinstance(pg_val, dict):
            if "by_type" in pg_val and isinstance(pg_val["by_type"], dict):
                parsed = pg_val["by_type"]
            elif "tariffs" in pg_val:
                parsed = pg_val.get("tariffs")
            else:
                # dict of type->list
                parsed = pg_val
        elif isinstance(pg_val, list):
            parsed = pg_val
    except Exception as e:
        logger.error(f"load_extend_tariffs PG: {e}")
    if parsed is None:
        try:
            if os.path.exists(FACTORY_TARIFFS_FILE):
                with open(FACTORY_TARIFFS_FILE, "r", encoding="utf-8") as f:
                    data = json.load(f)
                if isinstance(data, dict) and "by_type" in data:
                    parsed = data["by_type"]
                else:
                    parsed = data
        except Exception as e:
            logger.error(f"load_extend_tariffs fayl: {e}")
    if isinstance(parsed, list):
        migrated = _parse_tariffs_list(parsed)
        if migrated:
            for bt in FACTORY_BOT_TYPES:
                result[bt] = [dict(t) for t in migrated]
    elif isinstance(parsed, dict):
        for bt in FACTORY_BOT_TYPES:
            v = parsed.get(bt)
            lst = _parse_tariffs_list(v)
            if lst:
                result[bt] = lst
    return result

def save_extend_tariffs(tariffs) -> bool:
    """Barcha bot turlari uchun tariflarni saqlaydi (dict format)."""
    if isinstance(tariffs, list):
        tariffs = {bt: [dict(t) for t in tariffs] for bt in FACTORY_BOT_TYPES}
    ok_file = True
    try:
        with open(FACTORY_TARIFFS_FILE, "w", encoding="utf-8") as f:
            json.dump({"by_type": tariffs}, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.error(f"save_extend_tariffs fayl: {e}")
        ok_file = False
    try:
        _pg_kv_set("factory_tariffs", {"by_type": tariffs})
    except Exception as e:
        logger.error(f"save_extend_tariffs PG: {e}")
    return ok_file

def get_tariffs_for(bot_type: str) -> list:
    """Berilgan bot turi uchun tariflar ro'yxatini (dict ichida) qaytaradi.
    Foydalanuvchi ushbu ro'yxatga qo'shsa/o'chirsa — global saqlanadi."""
    bt = str(bot_type or "kino")
    if bt not in FACTORY_BOT_TYPES:
        bt = "kino"
    if bt not in BOT_EXTEND_TARIFFS or not isinstance(BOT_EXTEND_TARIFFS.get(bt), list):
        BOT_EXTEND_TARIFFS[bt] = [dict(t) for t in _DEFAULT_EXTEND_TARIFFS]
    return BOT_EXTEND_TARIFFS[bt]

