def _movie_pool_read(path: str) -> dict:
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                return data
    except Exception as e:
        logger.error(f"_movie_pool_read xato ({path}): {e}")
    return {}


def _movie_pool_write(path: str, data: dict) -> None:
    try:
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False)
        os.replace(tmp, path)
    except Exception as e:
        logger.error(f"_movie_pool_write xato ({path}): {e}")


def _movie_sync_tick():
    """Har ~15 soniyada chaqiriladi (parentda ham, har bir 'kino' turidagi
    bola-botda ham). RAM.movies ni to'g'ridan-to'g'ri o'zgartiradi — keyingi
    oddiy save_sync/avtosaqlash tsikli buni allaqachon diskka yozib qo'yadi."""
    try:
        if not IS_CHILD_BOT:
            # ASOSIY BOT: ⚠️ MUHIM — endi asosiy bot va bola-botlar kinolari
            # BUTUNLAY ALOHIDA. Bola-botlardan hech qanday kino asosiy bot
            # RAM'iga yig'ib olinmaydi (avval mavjud bo'lgan "yig'ish"
            # funksiyasi butunlay o'chirildi). Agar oldingi versiyalardan
            # "child:*" belgili (meros) kinolar RAM'da qolib ketgan bo'lsa,
            # ularni ham shu yerda tozalab tashlaymiz — shunda asosiy botda
            # FAQAT o'zining kinolari qoladi.
            _to_drop = [c for c, m in list(RAM.movies.items())
                        if isinstance(m, dict) and str(m.get("_origin", "")).startswith("child:")]
            for _c in _to_drop:
                try:
                    RAM.movies.pop(_c, None)
                except Exception:
                    pass
        else:
            # BOLA-BOT (kino turi): FAQAT o'z kinolarini boshqaradi.
            # ⚠️ MUHIM: asosiy botdagi kinolar bola-botga UMUMAN chiqmasin —
            #    shuning uchun PARENT_MOVIES_POOL_FILE dan hech nima o'qimaymiz.
            # Ilgari parentdan meros bo'lib RAM ga tushib qolgan har qanday
            #    "parent" belgili kinolarni bola-bot RAM'idan tozalab tashlaymiz —
            #    aks holda ular bir chiqib bir yo'qolib "miltillab" turadi.
            _to_drop = [c for c, m in list(RAM.movies.items())
                        if isinstance(m, dict) and str(m.get("_origin", "")).startswith("parent")]
            for _c in _to_drop:
                try:
                    RAM.movies.pop(_c, None)
                except Exception:
                    pass
            # 3) parentda tugmalarga qo'shilgan premium emoji ID'larni ham
            #    qayta-qayta (restart shart bo'lmasdan) yangilab turamiz
            try:
                parent_emojis = _load_parent_emoji_ids()
                if parent_emojis:
                    for _k, _v in parent_emojis.items():
                        _vs = str(_v).strip()
                        if _vs.isdigit() and RAM.emoji_ids.get(_k) != _vs:
                            RAM.emoji_ids[_k] = _vs
                    EMOJI_IDS.clear()
                    EMOJI_IDS.update(RAM.emoji_ids)
            except Exception as e:
                logger.error(f"_movie_sync_tick (emoji_ids) xato: {e}")
    except Exception as e:
        logger.error(f"_movie_sync_tick xato: {e}")


def movie_sync_watchdog():
    """Faqat 'Dramlar (kino)' turidagi botlarda ishlaydi — asosiy botda va
    'kino' turidagi bola-botlarda (VIP/UC/Yulduz bola-botlari kino tizimidan
    umuman foydalanmaydi, shuning uchun ularda bu ishga tushmaydi)."""
    if IS_CHILD_BOT and FACTORY_BOT_TYPE_ENV != "kino":
        return
    time.sleep(10)  # RAM birinchi marta to'liq yuklanguncha kutamiz
    while True:
        try:
            _movie_sync_tick()
        except Exception as e:
            logger.error(f"movie_sync_watchdog: {e}")
        time.sleep(15)

