def _pg_connect(url: str):
    """
    PostgreSQL ulanish hosil qiladi — Railway internal/external hostlarga mos sslmode bilan.
    Railway'ning ichki tarmoq hosti (*.railway.internal) SSL'ni qo'llamaydi,
    shu sababli sslmode='require' bilan ulanish doim FAIL bo'ladi.
    Tashqi hostlar uchun esa SSL talab qilinadi.

    connect_timeout=3 — Postgres endi ixtiyoriy/yordamchi manba (asosiy manba
    mahalliy fayl), shuning uchun agar server ulanmasa/sekin bo'lsa, bot BUTUN
    foydalanuvchilar uchun sekundlab (yoki minutlab) "muzlab" qolmasligi kerak —
    tezda xato qaytarib, mahalliy faylga o'tadi.
    """
    host = ""
    try:
        host = (_fx_urlparse(url).hostname or "").lower()
    except Exception:
        pass
    if host.endswith(".railway.internal") or host in ("localhost", "127.0.0.1"):
        try:
            return psycopg2.connect(url, sslmode="disable", connect_timeout=3)
        except Exception:
            return psycopg2.connect(url, connect_timeout=3)
    try:
        return psycopg2.connect(url, sslmode="require", connect_timeout=3)
    except Exception:
        # SSL talab qilib bo'lmasa — sslmode'siz qayta urinib ko'ramiz
        return psycopg2.connect(url, connect_timeout=3)


def _factory_db():
    return _pg_connect(DATABASE_URL)


# ══════════════════════════════════════════════════════════
# 🗂 FABRIKA BUXGALTERIYASI — MAHALLIY FAYL (asosiy manba)
# ══════════════════════════════════════════════════════════
# Ilgari bu ma'lumotlar (kim qaysi bola-botni yaratgani, tokeni, muddati va h.k.)
# FAQAT PostgreSQL'da saqlanardi. Agar DATABASE_URL boshqa hostingda ishlamasa
# (masalan Railway'ning ichki "postgres.railway.internal" manzili tashqaridan
# ko'rinmaydi), bola-bot umuman yaratilmas va ishga tushmas edi.
#
# Endi bu ma'lumotlar avvalo MAHALLIY JSON faylga yoziladi (restart bo'lsa
# ham, hosting o'zgarsa ham — fayl saqlanib qoladi va o'chmaydi). PostgreSQL
# mavjud bo'lsa, u ham qo'shimcha ravishda (ixtiyoriy, xato bersa e'tiborsiz
# qoldiriladigan) yozib boriladi — lekin endi hech narsa unga BOG'LIQ emas.
import threading as _fdb_threading
from datetime import timezone as _fdb_tz, timedelta as _fdb_td

FACTORY_LOCAL_FILE = os.environ.get("FACTORY_LOCAL_FILE") or os.path.join(_PROJECT_DIR, "factory_bots.json")
_factory_local_lock = _fdb_threading.Lock()


class FactoryTokenTaken(Exception):
    """Bu token allaqachon boshqa bola-bot uchun ishlatilgan."""
    pass


def _factory_local_load() -> dict:
    try:
        if os.path.exists(FACTORY_LOCAL_FILE):
            with open(FACTORY_LOCAL_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict) and isinstance(data.get("bots"), list):
                data.setdefault("next_id", (max([b.get("id", 0) for b in data["bots"]], default=0) + 1))
                return data
    except Exception as e:
        logger.error(f"_factory_local_load xato: {e}")
    return {"next_id": 1, "bots": []}


def _factory_local_save(data: dict) -> bool:
    try:
        tmp = FACTORY_LOCAL_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(data, f, ensure_ascii=False)
        os.replace(tmp, FACTORY_LOCAL_FILE)
        return True
    except Exception as e:
        logger.error(f"_factory_local_save xato: {e}")
        return False


def _factory_dt_now() -> "datetime":
    return datetime.now(_fdb_tz.utc)


def _factory_iso(dt) -> str | None:
    if dt is None:
        return None
    return dt.isoformat()


def _factory_parse_iso(s):
    if not s:
        return None
    try:
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=_fdb_tz.utc)
        return dt
    except Exception:
        return None


def _factory_row_out(rec: dict) -> dict:
    """Saqlangan yozuvni psycopg2 RealDictCursor natijasiga o'xshash formatga
    o'tkazadi — sana maydonlari datetime obyektiga aylantiriladi, shunda
    factory_is_expired/factory_fmt_dt/factory_days_left o'zgarishsiz ishlayveradi."""
    if not rec:
        return rec
    out = dict(rec)
    for k in ("created_at", "last_started", "deleted_at", "expires_at"):
        out[k] = _factory_parse_iso(out.get(k))
    return out


def factory_init_db():
    """Fabrika buxgalteriyasini tayyorlaydi. Mahalliy fayl HAR DOIM ishlaydi
    (Postgres kerak emas). Postgres mavjud bo'lsa, qo'shimcha ravishda
    (ixtiyoriy) urinib ko'riladi, lekin uning ishlamasligi hech narsani
    to'xtatmaydi."""
    with _factory_local_lock:
        data = _factory_local_load()
        _factory_local_save(data)
    if DATABASE_URL and PSYCOPG2_AVAILABLE:
        try:
            with _factory_db() as conn, conn.cursor() as cur:
                cur.execute("""
                    CREATE SCHEMA IF NOT EXISTS factory;
                    CREATE TABLE IF NOT EXISTS factory.child_bots (
                        id           SERIAL PRIMARY KEY,
                        owner_id     BIGINT NOT NULL,
                        owner_name   TEXT,
                        owner_username TEXT,
                        token        TEXT   NOT NULL UNIQUE,
                        bot_username TEXT,
                        bot_title    TEXT,
                        schema_name  TEXT   NOT NULL UNIQUE,
                        status       TEXT   NOT NULL DEFAULT 'active',
                        created_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
                        last_started TIMESTAMPTZ
                    );
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS owner_name TEXT;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS owner_username TEXT;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS bot_username TEXT;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS bot_title TEXT;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS status TEXT NOT NULL DEFAULT 'active';
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT NOW();
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS last_started TIMESTAMPTZ;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS expires_at TIMESTAMPTZ;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS paid_total BIGINT NOT NULL DEFAULT 0;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS notice3_sent BOOLEAN NOT NULL DEFAULT FALSE;
                    ALTER TABLE factory.child_bots ADD COLUMN IF NOT EXISTS bot_type TEXT NOT NULL DEFAULT 'kino';
                """)
            logger.info("✅ Factory jadvali (Postgres, qo'shimcha) tayyor")
        except Exception as e:
            logger.warning(f"Factory Postgres init o'tkazib yuborildi (mahalliy fayl ishlatiladi): {e}")
    return True

def factory_db_insert(owner_id, owner_name, owner_username, token, uname, title,
                      paid_amount: int = 0, trial_days: int | None = None,
                      bot_type: str = "kino", buyer_id: int | None = None):
    bot_type = (bot_type or "kino").strip().lower()
    if bot_type not in ("kino", "vip", "vip_pro", "uc", "yulduz", "auto_tolov", "openbudget"):
        bot_type = "kino"
    with _factory_local_lock:
        data = _factory_local_load()
        for b in data["bots"]:
            if b.get("token") == token:
                raise FactoryTokenTaken(token)
        bid = data["next_id"]
        data["next_id"] = bid + 1
        schema = f"bot_{bid}"
        now = _factory_dt_now()
        # MUHIM: default qiymatni funksiya e'lon qilingan paytda emas,
        # aynan yaratish paytida olamiz. Aks holda admin sinov muddatini
        # 2 kunga o'zgartirsa ham eski BOT_TRIAL_DAYS ishlashi mumkin.
        effective_trial_days = int(BOT_TRIAL_DAYS if trial_days is None else trial_days)
        expires_at = now + _fdb_td(days=effective_trial_days)
        rec = {
            "id": bid,
            "owner_id": owner_id, "owner_name": owner_name or "",
            "owner_username": owner_username or "", "token": token,
            "bot_username": uname or "", "bot_title": title or "",
            "schema_name": schema, "status": "active",
            "created_at": _factory_iso(now), "last_started": None,
            "deleted_at": None, "expires_at": _factory_iso(expires_at),
            "paid_total": int(paid_amount), "notice3_sent": False,
            "bot_type": bot_type,
            "buyer_id": int(buyer_id) if buyer_id is not None else int(owner_id),
        }
        data["bots"].append(rec)
        _factory_local_save(data)
    # Postgres — faqat "kino"/"vip" turlari o'zining schema-asosli ma'lumotlar
    # bazasidan foydalanadi. Mavjud bo'lsa tayyorlab qo'yamiz (ixtiyoriy).
    if DATABASE_URL and PSYCOPG2_AVAILABLE:
        try:
            with _factory_db() as conn, conn.cursor() as cur:
                cur.execute(f'CREATE SCHEMA IF NOT EXISTS "{schema}"')
                cur.execute(f'''
                    CREATE TABLE IF NOT EXISTS "{schema}".bot_data (
                        key TEXT PRIMARY KEY,
                        value JSONB NOT NULL,
                        updated_at TIMESTAMP DEFAULT NOW()
                    )
                ''')
                cur.execute(
                    f'''INSERT INTO "{schema}".bot_data (key, value, updated_at)
                        VALUES ('main', %s, NOW())
                        ON CONFLICT (key) DO UPDATE
                        SET value = EXCLUDED.value, updated_at = NOW()''',
                    (json.dumps(factory_empty_db(), ensure_ascii=False),))
        except Exception as e:
            logger.warning(f"factory_db_insert: Postgres schema tayyorlanmadi #{bid} (mahalliy fayl bilan davom etiladi): {e}")
    return bid, schema


def factory_db_extend(bid: int, days: int, paid_amount: int = 0):
    """Bot muddatini uzaytiradi. Agar bot allaqachon muddati o'tgan bo'lsa —
    hozirdan boshlab; aks holda mavjud expires_at ga qo'shadi."""
    with _factory_local_lock:
        data = _factory_local_load()
        now = _factory_dt_now()
        for b in data["bots"]:
            if b.get("id") == bid:
                cur_exp = _factory_parse_iso(b.get("expires_at"))
                base = now if (cur_exp is None or cur_exp < now) else cur_exp
                new_exp = base + _fdb_td(days=int(days))
                b["expires_at"] = _factory_iso(new_exp)
                b["paid_total"] = int(b.get("paid_total", 0) or 0) + int(paid_amount)
                if b.get("status") == "expired":
                    b["status"] = "active"
                b["notice3_sent"] = False
                _factory_local_save(data)
                return new_exp
    return None


def factory_db_admin_adjust_days(bid: int, days: int):
    """Admin tomonidan to'g'ridan-to'g'ri kun qo'shish (musbat son) yoki
    ayirish (manfiy son) uchun. paid_total ga tegmaydi — sof muddat tuzatishi."""
    with _factory_local_lock:
        data = _factory_local_load()
        now = _factory_dt_now()
        for b in data["bots"]:
            if b.get("id") == bid:
                cur_exp = _factory_parse_iso(b.get("expires_at")) or now
                new_exp = cur_exp + _fdb_td(days=int(days))
                b["expires_at"] = _factory_iso(new_exp)
                b["notice3_sent"] = False
                _factory_local_save(data)
                return new_exp
    return None


def factory_is_expired(row: dict) -> bool:
    exp = row.get("expires_at") if row else None
    if not exp:
        return False
    try:
        from datetime import datetime as _dt, timezone as _tz
        now = _dt.now(_tz.utc)
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=_tz.utc)
        return exp < now
    except Exception:
        return False


def factory_fmt_dt(dt, fmt: str = "%Y-%m-%d %H:%M") -> str:
    """Berilgan datetime'ni O'zbekiston (Toshkent, UTC+5) vaqtiga o'tkazib qaytaradi.

    PostgreSQL'dagi TIMESTAMPTZ ustuni psycopg2 orqali odatda UTC (yoki server)
    vaqtida qaytadi. Buni har doim shu funksiya orqali Toshkent vaqtiga
    aylantirib ko'rsatish kerak — aks holda admin panelda soat noto'g'ri chiqadi.
    """
    if not dt:
        return "—"
    try:
        from datetime import timezone as _tz, timedelta as _td
        if dt.tzinfo is not None:
            dt_utc = dt.astimezone(_tz.utc).replace(tzinfo=None)
        else:
            dt_utc = dt  # tzsiz qiymat — UTC deb hisoblaymiz (factory_is_expired bilan bir xil)
        tashkent = dt_utc + _td(hours=5)
        return tashkent.strftime(fmt)
    except Exception:
        try:
            return dt.strftime(fmt)
        except Exception:
            return str(dt)


def factory_days_left(row: dict):
    """expires_at ga necha kun (float, manfiy bo'lsa muddati o'tgan) qolganini qaytaradi."""
    exp = row.get("expires_at") if row else None
    if not exp:
        return None
    try:
        from datetime import datetime as _dt, timezone as _tz
        now = _dt.now(_tz.utc)
        if exp.tzinfo is None:
            exp = exp.replace(tzinfo=_tz.utc)
        return (exp - now).total_seconds() / 86400.0
    except Exception:
        return None



def factory_db_active():
    with _factory_local_lock:
        data = _factory_local_load()
        rows = [b for b in data["bots"] if b.get("status") == "active"]
        rows.sort(key=lambda b: b.get("id", 0))
        return [_factory_row_out(b) for b in rows]

def factory_db_user(owner_id):
    with _factory_local_lock:
        data = _factory_local_load()
        rows = [b for b in data["bots"]
                if b.get("status") != "deleted"
                and (b.get("buyer_id") == owner_id
                     or (b.get("buyer_id") is None and b.get("owner_id") == owner_id))]
        rows.sort(key=lambda b: b.get("id", 0))
        return [_factory_row_out(b) for b in rows]

def factory_db_get(bid: int):
    with _factory_local_lock:
        data = _factory_local_load()
        for b in data["bots"]:
            if b.get("id") == bid:
                return _factory_row_out(b)
        return None

# ─── BOLA BOTNING TOKENI ORQALI XABAR YUBORISH (raw Bot API) ──
def _child_bot_api_url(token: str, method: str) -> str:
    """Local Bot API server mavjud bo'lsa — uni ishlatadi (2GB limit).
    Aks holda standart api.telegram.org (50MB limit)."""
    if USE_LOCAL_BOT_API and LOCAL_BOT_API_URL:
        base = LOCAL_BOT_API_URL.rstrip("/")
        # LOCAL_BOT_API_URL odatda "http://127.0.0.1:8081/bot" shaklida
        # kerak: http://127.0.0.1:8081/bot{token}/{method}
        return f"{base}{token}/{method}"
    return f"https://api.telegram.org/bot{token}/{method}"

def _child_bot_send_sync(token: str, method: str, payload: dict):
    url = _child_bot_api_url(token, method)
    try:
        r = requests.post(url, json=payload, timeout=60)
        data = r.json()
    except Exception as e:
        return False, f"HTTP xato: {e}"
    if not data.get("ok"):
        return False, data.get("description") or "noma'lum xato"
    return True, None

def _child_bot_send_file_sync(token: str, method: str, field: str,
                              file_tuple, data: dict):
    url = _child_bot_api_url(token, method)
    # Katta fayllar uchun uzun timeout (2GB ~ 10 daqiqa)
    timeout = VIDEO_IO_TIMEOUT if USE_LOCAL_BOT_API else 120
    try:
        r = requests.post(url, data=data, files={field: file_tuple}, timeout=timeout)
        j = r.json()
    except Exception as e:
        return False, f"HTTP xato: {e}"
    if not j.get("ok"):
        return False, j.get("description") or "noma'lum xato"
    return True, None

async def notify_parent_admin(bot, text: str, parse_mode: str = "HTML") -> bool:
    """Xabarni asosiy bot tokeni orqali asosiy adminga yuboradi.

    Bola botda context.bot ishlatilsa xabar bola bot nomidan ketadi. PARENT_BOT_TOKEN
    berilgan bo'lsa, raw Telegram Bot API orqali aynan asosiy bot nomidan yuboramiz.
    """
    payload = {"chat_id": PARENT_ADMIN_ID, "text": text}
    if parse_mode:
        payload["parse_mode"] = parse_mode

    if PARENT_BOT_TOKEN:
        ok, err = await asyncio.to_thread(_child_bot_send_sync, PARENT_BOT_TOKEN, "sendMessage", payload)
        if ok:
            return True
        logger.error(f"parent bot sendMessage failed: {err}")

    # Fallback: PARENT_BOT_TOKEN kiritilmagan yoki xato bo'lsa, eski usul bilan urinadi.
    try:
        await bot.send_message(PARENT_ADMIN_ID, text, parse_mode=parse_mode)
        return True
    except Exception as e:
        logger.error(f"fallback parent admin send failed: {e}")
        return False

async def _child_bot_send(token: str, method: str, payload: dict):
    return await asyncio.to_thread(_child_bot_send_sync, token, method, payload)

async def _child_bot_send_file(token: str, method: str, field: str,
                               file_tuple, data: dict):
    return await asyncio.to_thread(_child_bot_send_file_sync, token, method,
                                   field, file_tuple, data)

def factory_db_all():
    with _factory_local_lock:
        data = _factory_local_load()
        rows = list(data["bots"])
        rows.sort(key=lambda b: b.get("id", 0), reverse=True)
        return [_factory_row_out(b) for b in rows]

def factory_db_set_status(bid, st):
    with _factory_local_lock:
        data = _factory_local_load()
        for b in data["bots"]:
            if b.get("id") == bid:
                b["status"] = st
                if st == "deleted":
                    b["deleted_at"] = _factory_iso(_factory_dt_now())
                _factory_local_save(data)
                return


def _factory_child_exit_reason() -> str | None:
    """Bola-bot o'zini-o'zi nazorat qiladi.

    Parent/admin panel PM2 yoki OS signali orqali jarayonni o'chira olmasa ham,
    bola-bot factory_bots.json dagi holatni ko'rib o'zi chiqib ketadi:
      • yozuv o'chirilgan bo'lsa;
      • status active bo'lmasa (stopped/deleted/expired);
      • expires_at o'tib ketgan bo'lsa.
    Shu tuzatish admin paneldan to'xtatish/o'chirish va sinov muddati tugashini
    majburiy qiladi.
    """
    if not IS_CHILD_BOT:
        return None
    try:
        bid = int(FACTORY_CHILD_ID or "0")
    except Exception:
        return "FACTORY_CHILD_ID yo'q"
    if bid <= 0:
        return "FACTORY_CHILD_ID noto'g'ri"
    row = factory_db_get(bid)
    if not row:
        return "factory ro'yxatidan o'chirilgan"
    status = str(row.get("status") or "active").lower()
    if status != "active":
        return f"status={status}"
    if factory_is_expired(row):
        return "muddati tugagan"
    return None


def _factory_child_lifecycle_guard():
    """Bola-bot ichida fon nazoratchi: har 1 soniyada holatni tekshiradi.

    os._exit(0) ataylab ishlatiladi: Telegram polling yoki boshqa threadlar
    ushlab qolsa ham jarayon aniq tugashi kerak.
    """
    if not IS_CHILD_BOT:
        return
    while True:
        try:
            reason = _factory_child_exit_reason()
            if reason:
                logger.warning(f"🛑 Bola-bot #{FACTORY_CHILD_ID} o'zini to'xtatdi: {reason}")
                os._exit(0)
        except Exception as e:
            logger.error(f"_factory_child_lifecycle_guard xato: {e}")
        time.sleep(1)


def start_factory_child_lifecycle_guard():
    """Bola-bot ishga tushishi bilan majburiy self-stop nazoratini yoqadi."""
    if not IS_CHILD_BOT:
        return
    _fx_threading.Thread(target=_factory_child_lifecycle_guard, daemon=True).start()
    logger.info(f"🛡 Bola-bot #{FACTORY_CHILD_ID or '?'} lifecycle guard yoqildi")


def _factory_reconcile_on_boot():
    """Asosiy bot ishga tushganda BARCHA bola-botlarni qayta muvofiqlashtiradi.

    Muammo edi: hosting faqat server.py'ni resat qilardi. PM2'dagi eski bola-bot
    jarayonlari xotiraga yuklab olingan ESKI kodni ishlatishda davom etardi —
    ular admin panelidan to'xtatilsa ham lifecycle guard'siz ishlayveradi.

    Yechim: asosiy bot ishga tushishi bilan
    1) DBdagi 'active' bo'lmagan (yoki muddati tugagan) barcha bola-botlar
       PM2'dan majburiy o'chiriladi;
    2) DB'da bo'lmagan, lekin PM2'da qolib ketgan 'factory-child-*'
       yetim ilovalar ham o'chiriladi;
    3) 'active' va muddati tugamagan bola-botlar to'xtatilib qayta ishga
       tushiriladi — shunda ular YANGI server.py kodini (lifecycle guard
       bilan birga) yuklaydi.
    """
    if IS_CHILD_BOT:
        return
    try:
        with _factory_local_lock:
            data = _factory_local_load()
        bots = list((data or {}).get("bots") or [])
    except Exception as e:
        logger.error(f"_factory_reconcile_on_boot: DB o'qilmadi: {e}")
        bots = []

    known_ids: set[int] = set()
    for b in bots:
        try:
            bid = int(b.get("id"))
        except Exception:
            continue
        known_ids.add(bid)
        status = str(b.get("status") or "active").lower()
        row = _factory_row_out(b)
        expired = False
        try:
            expired = factory_is_expired(row)
        except Exception:
            expired = False
        if status != "active" or expired or b.get("deleted_at"):
            try:
                factory_stop(bid)
                logger.warning(f"🧹 Boot reconcile: #{bid} status={status} expired={expired} — PM2'dan o'chirildi")
            except Exception as e:
                logger.error(f"Boot reconcile stop #{bid}: {e}")
            continue
        # active + muddati tugamagan → yangi kod bilan qayta ishga tushur
        try:
            factory_stop(bid)
            time.sleep(1)
            ok = factory_spawn(row)
            logger.info(f"♻️ Boot reconcile: #{bid} qayta ishga tushirildi (ok={ok})")
        except Exception as e:
            logger.error(f"Boot reconcile respawn #{bid}: {e}")

    # PM2'dagi yetim 'factory-child-*' ilovalarini tozalash
    try:
        ok, out = _factory_pm2_run(["jlist"])
        if ok:
            procs = json.loads(out or "[]")
            for proc in procs:
                name = proc.get("name") or ""
                if not name.startswith("factory-child-"):
                    continue
                try:
                    pid_from_name = int(name.rsplit("-", 1)[-1])
                except Exception:
                    continue
                if pid_from_name in known_ids:
                    continue
                _factory_pm2_run(["delete", name])
                logger.warning(f"🧹 Boot reconcile: yetim PM2 ilova {name} o'chirildi")
            _fx_subprocess.run(["pm2", "save"], capture_output=True, timeout=10)
    except Exception as e:
        logger.error(f"Boot reconcile orphan cleanup: {e}")


def factory_db_mark_notice3_sent(bid: int):
    """Muddat tugashiga 3 kun qolgani haqida ogohlantirish yuborilganini belgilaydi —
    bot uzaytirilmaguncha qayta-qayta yuborilmasligi uchun."""
    with _factory_local_lock:
        data = _factory_local_load()
        for b in data["bots"]:
            if b.get("id") == bid:
                b["notice3_sent"] = True
                _factory_local_save(data)
                return

def factory_db_delete(bid: int) -> bool:
    """Bola-botni TO'LIQ o'chiradi: jarayonni to'xtatadi, uning schema/ma'lumotlarini
    o'chiradi va mahalliy fabrika ro'yxatidan (token bilan birga) butunlay olib tashlaydi."""
    row = factory_db_get(bid)
    if not row:
        return False
    schema = row.get("schema_name") or ""

    # 0) Avval statusni deleted qilamiz. Agar hosting PM2/kill signalini
    # bloklasa ham, bola-bot ichidagi lifecycle guard bu holatni ko'rib o'zi
    # 10 soniya ichida chiqib ketadi.
    factory_db_set_status(bid, "deleted")

    # 1) Jarayonni to'xtatamiz (token bilan ishlayotgan bola-bot endi ishlamasligi kerak)
    factory_stop(bid)

    # 2) Postgres schema (agar "kino"/"vip" turi Postgres'da saqlangan bo'lsa) —
    #    ixtiyoriy, mavjud/ulanadigan bo'lsa tozalanadi, bo'lmasa e'tiborsiz qoldiriladi.
    if DATABASE_URL and PSYCOPG2_AVAILABLE and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", schema) and schema != "factory":
        try:
            with _factory_db() as conn, conn.cursor() as cur:
                cur.execute(f'DROP SCHEMA IF EXISTS "{schema}" CASCADE')
        except Exception as e:
            logger.error(f"factory_db_delete: schema #{bid} ({schema}) o'chmadi: {e}")

    # 2b) Fayl-asosli bola-botlar (uc/yulduz) — bularning
    #     ma'lumotlari Postgres schema'da emas, FACTORY_DATA_DIR ichidagi
    #     alohida sqlite fayli/papkasida turadi. Bot bu yerda BUTUNLAY
    #     o'chirilayotgani uchun ularni ham diskdan tozalaymiz — aks holda
    #     token o'chirilgandan keyin ham eskirgan fayllar diskda qolib ketadi.
    _leftover_paths = [
        os.path.join(FACTORY_DATA_DIR, f"uc_bot_data_{bid}.db"),
        os.path.join(FACTORY_DATA_DIR, f"yulduz_bot_data_{bid}"),
        os.path.join(FACTORY_DATA_DIR, f"openbudget_bot_data_{bid}"),
    ]
    for _p in _leftover_paths:
        try:
            if os.path.isdir(_p):
                shutil.rmtree(_p, ignore_errors=True)
            elif os.path.exists(_p):
                os.remove(_p)
        except Exception as e:
            logger.error(f"factory_db_delete: fayl o'chmadi ({_p}): {e}")

    # 3) Asosiy yozuv — token shu yerda saqlanadi, shuning uchun bu qator
    #    o'chirilganda bot token bilan birga butunlay ro'yxatdan o'chadi.
    with _factory_local_lock:
        data = _factory_local_load()
        before = len(data["bots"])
        data["bots"] = [b for b in data["bots"] if b.get("id") != bid]
        deleted = len(data["bots"]) < before
        if deleted:
            _factory_local_save(data)

    return deleted

def factory_db_update_token(bid: int, new_token: str, new_uname: str, new_title: str) -> bool:
    """Bola-botning tokenini yangilaydi — barcha ma'lumotlar (kino, foydalanuvchi, balans) SAQLANIB qoladi."""
    with _factory_local_lock:
        data = _factory_local_load()
        for b in data["bots"]:
            if b.get("id") == bid:
                b["token"] = new_token
                b["bot_username"] = new_uname or ""
                b["bot_title"] = new_title or ""
                _factory_local_save(data)
                return True
        return False

def factory_db_started(bid):
    with _factory_local_lock:
        data = _factory_local_load()
        for b in data["bots"]:
            if b.get("id") == bid:
                b["last_started"] = _factory_iso(_factory_dt_now())
                _factory_local_save(data)
                return

def factory_validate_token(t: str):
    try:
        r = requests.get(f"https://api.telegram.org/bot{t}/getMe", timeout=10).json()
        return r["result"] if r.get("ok") else None
    except Exception:
        return None

def _factory_child_db_url(schema: str) -> str:
    """DATABASE_URL ga search_path=schema qo'shadi — bola-bot izolyatsiyasi.

    MUHIM: urlencode() standart holatda bo'shliqni '+' bilan kodlaydi, lekin
    libpq URI ichidagi '+' belgisini bo'shliqqa AYLANTIRMAYDI — natijada
    'options=-c+search_path=schema' yaroqsiz bo'lib, butun ulanish
    ('Ulanish yo'q') bilan ishlamay qoladi. Shu sababli bo'shliq %20
    ko'rinishida kodlanishi uchun quote_via=quote ishlatiladi.
    """
    u = _fx_urlparse(DATABASE_URL)
    q = dict(_fx_parse_qsl(u.query))
    q["options"] = f"-c search_path={schema}"
    return _fx_urlunparse(u._replace(query=_fx_urlencode(q, quote_via=_fx_quote)))

# ─── Bola-bot PID'ini DISKKA saqlash ────────────────────────────────────
# Muammo: FACTORY_RUNNING faqat XOTIRADA turadi. Agar asosiy bot serveri
# qayta ishga tushsa (redeploy/crash), bu lug'at bo'shab qoladi — lekin
# oldin os.setsid bilan ishga tushirilgan bola-bot jarayoni asosiy botdan
# MUSTAQIL bo'lgani uchun "yetim" holda ishlab qolaveradi. Natijada:
#  • watchdog uni "o'lgan" deb yana bittasini ishga tushiradi (dublikat),
#  • foydalanuvchi botni o'chirganda faqat xotiradagi (yangi) nusxa
#    o'chadi, "yetim" nusxa esa ishlab qolib, bot go'yo o'chmagandek
#    javob berib turaveradi.
# Shu sababli PID diskka ham yoziladi va stop/spawn paytida shu fayldan
# ham tekshirib, haqiqiy egasini /proc orqali tasdiqlab o'chiramiz.
def _factory_pid_file(bid: int) -> str:
    return os.path.join(FACTORY_DATA_DIR, f"child_pid_{bid}.txt")

def _factory_save_pid(bid: int, pid: int):
    try:
        with open(_factory_pid_file(bid), "w") as f:
            f.write(str(pid))
    except Exception as e:
        logger.error(f"_factory_save_pid #{bid}: {e}")

def _factory_read_pid(bid: int):
    try:
        with open(_factory_pid_file(bid), "r") as f:
            return int(f.read().strip())
    except Exception:
        return None

def _factory_clear_pid_file(bid: int):
    try:
        os.remove(_factory_pid_file(bid))
    except Exception:
        pass

def _factory_pid_is_ours(pid: int, bid: int) -> bool:
    """/proc orqali bu PID chindan ham shu bola-bot uchun ishga tushirilgan
    SELF_FILE jarayoni ekanligini tekshiradi (PID qayta ishlatilib
    ketgan, boshqa jarayonga tegishli bo'lib qolmasligi uchun)."""
    try:
        with open(f"/proc/{pid}/cmdline", "rb") as f:
            cmd = f.read().replace(b"\x00", b" ").decode(errors="ignore")
        if SELF_FILE not in cmd:
            return False
    except Exception:
        return True  # /proc mavjud emas (masalan Windows) — baribir o'chirishga urinamiz
    try:
        with open(f"/proc/{pid}/environ", "rb") as f:
            envs = f.read().split(b"\x00")
        for e in envs:
            if e.startswith(b"FACTORY_CHILD_ID="):
                return e == f"FACTORY_CHILD_ID={bid}".encode()
    except Exception:
        pass
    return True

def _factory_pid_alive(pid: int) -> bool:
    """PID hali operatsion tizimda ishlab turganini tekshiradi (signal
    yubormasdan) — os.kill(pid, 0) orqali."""
    try:
        try:
            with open(f"/proc/{pid}/stat", "r", encoding="utf-8", errors="ignore") as f:
                parts = f.read().split()
            if len(parts) > 2 and parts[2] == "Z":
                return False
        except Exception:
            pass
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        # Jarayon bor, lekin bizga signal yuborishga ruxsat yo'q —
        # bu ayni shu hosting cheklovi bo'lishi mumkin (cagefs va h.k.)
        return True
    except Exception:
        return False


def _factory_find_child_pids(bid: int) -> list[int]:
    """PM2 ro'yxatidan chiqmay/yetim qolgan aynan shu bola-bot jarayonlarini
    /proc orqali topadi. Bu stop tugmasi bosilganda status "stopped" bo'lsa
    ham eski polling jarayoni ishlab qolmasligi uchun kerak."""
    if os.name == "nt" or not os.path.isdir("/proc"):
        return []
    found: set[int] = set()
    target_env = f"FACTORY_CHILD_ID={int(bid)}".encode()
    env_file_name = os.path.basename(_factory_env_file(bid))
    my_pid = os.getpid()
    for pid_s in os.listdir("/proc"):
        if not pid_s.isdigit():
            continue
        pid = int(pid_s)
        if pid == my_pid:
            continue
        matched = False
        try:
            with open(f"/proc/{pid}/environ", "rb") as f:
                envs = f.read().split(b"\x00")
            matched = target_env in envs
        except Exception:
            matched = False
        if not matched:
            try:
                with open(f"/proc/{pid}/cmdline", "rb") as f:
                    cmd = f.read().replace(b"\x00", b" ").decode(errors="ignore")
                matched = (SELF_FILE in cmd and env_file_name in cmd)
            except Exception:
                matched = False
        if matched:
            try:
                if _factory_pid_is_ours(pid, bid):
                    found.add(pid)
            except Exception:
                found.add(pid)
    return sorted(found)


def _factory_force_kill_child(bid: int):
    """PM2 delete yetarli bo'lmasa, aynan shu bola-botning qolgan
    jarayonlarini SIGTERM→SIGKILL bilan majburan o'chiradi."""
    pids = set(_factory_find_child_pids(bid))
    pid_from_file = _factory_read_pid(bid)
    if pid_from_file and _factory_pid_is_ours(pid_from_file, bid):
        pids.add(pid_from_file)
    if not pids:
        return

    for sig in (_fx_signal.SIGTERM, _fx_signal.SIGKILL):
        for pid in list(pids):
            if not _factory_pid_alive(pid):
                continue
            try:
                if os.name == "nt":
                    _fx_subprocess.run(["taskkill", "/F", "/T", "/PID", str(pid)], capture_output=True, timeout=5)
                else:
                    try:
                        os.killpg(pid, sig)
                    except Exception:
                        os.kill(pid, sig)
            except Exception as e:
                logger.error(f"Factory #{bid}: majburiy kill ishlamadi (pid={pid}, sig={sig}): {e}")
        time.sleep(0.5)

    still_alive = [pid for pid in sorted(pids) if _factory_pid_alive(pid)]
    if still_alive:
        logger.error(f"❌ Factory #{bid}: stopdan keyin ham tirik PIDlar bor: {still_alive}")
    else:
        logger.warning(f"🧹 Factory #{bid}: qolgan bola-bot jarayonlari majburan o'chirildi: {sorted(pids)}")


def _factory_kill_stale_pid(bid: int):
    """FACTORY_RUNNING xotirasida yo'q, lekin diskdagi PID fayli orqali
    hali ham tirik ekanligi aniqlangan "yetim" bola-bot jarayonini topib,
    majburan o'chiradi. Har doim PID faylini tozalab yakunlaydi."""
    pid = _factory_read_pid(bid)
    if pid:
        try:
            if _factory_pid_is_ours(pid, bid):
                if os.name == "nt":
                    _fx_subprocess.run(["taskkill", "/F", "/T", "/PID", str(pid)],
                                        capture_output=True)
                else:
                    for sig in (_fx_signal.SIGTERM, _fx_signal.SIGKILL):
                        if not _factory_pid_alive(pid):
                            break
                        try:
                            os.killpg(pid, sig)
                        except ProcessLookupError:
                            break
                        except Exception as kill_err:
                            try:
                                os.kill(pid, sig)
                            except Exception:
                                logger.error(
                                    f"_factory_kill_stale_pid #{bid}: "
                                    f"killpg/kill ikkalasi ham ishlamadi (pid={pid}): {kill_err}")
                        time.sleep(0.3)
                # ✅ Natijani ROSTDAN tekshiramiz — signal yuborilgani
                # o'zi jarayon o'lgani degani emas (masalan ruxsat
                # cheklovi tufayli signal e'tiborsiz qoldirilishi mumkin).
                still_alive = _factory_pid_alive(pid)
                if still_alive:
                    logger.error(
                        f"❌ Factory #{bid}: pid={pid} SIGKILL'dan KEYIN HAM tirik! "
                        f"Bu hosting killpg/kill signallarini bloklayotgan bo'lishi mumkin.")
                else:
                    logger.warning(f"🧹 Factory #{bid}: 'yetim' jarayon (pid={pid}) o'chirildi (tasdiqlandi)")
        except Exception as e:
            logger.error(f"_factory_kill_stale_pid #{bid}: {e}")
    _factory_clear_pid_file(bid)


def _factory_pm2_name(bid: int) -> str:
    """Har bir bola-bot uchun PM2'dagi nomi — takrorlanmas bo'lishi uchun
    doim shu naqsh bilan: aynan shu nom orqali keyinchalik topib
    to'xtatiladi/o'chiriladi."""
    return f"factory-child-{bid}"


def _factory_env_file(bid: int) -> str:
    """Bola-bot uchun kerakli barcha environment o'zgaruvchilar shu JSON
    faylga yoziladi — PM2 orqali ishga tushirilganda bola-jarayon buni
    o'zi o'qib, ustiga o'z env'iga qo'shib oladi (qarang: SELF_FILE eng
    yuqorisidagi FACTORY_CHILD_ENV_FILE o'qish logikasi)."""
    return os.path.join(FACTORY_DATA_DIR, f"child_env_{bid}.json")


def _factory_build_child_env(row: dict) -> dict:
    bid = row["id"]
    bot_type = str(row.get("bot_type") or "kino")
    env = {
        "LOVABLE_ROLE": "child",
        "BOT_TOKEN": row["token"],
        "ADMIN_ID": str(row["owner_id"]),
        "PARENT_ADMIN_ID": str(PARENT_ADMIN_ID),
        "DATABASE_URL": _factory_child_db_url(row["schema_name"]),
        "FACTORY_CHILD_ID": str(bid),
        "FACTORY_SCHEMA_NAME": str(row["schema_name"]),
        "FACTORY_BOT_TYPE": bot_type,
        "PYTHONUNBUFFERED": "1",
    }
    if PARENT_BOT_TOKEN:
        env["PARENT_BOT_TOKEN"] = PARENT_BOT_TOKEN
    if bot_type == "uc":
        env["UC_DB_PATH"] = os.path.join(FACTORY_DATA_DIR, f"uc_bot_data_{bid}.db")
    elif bot_type == "yulduz":
        env["YULDUZ_DATA_DIR"] = os.path.join(FACTORY_DATA_DIR, f"yulduz_bot_data_{bid}")
    elif bot_type == "auto_tolov":
        env["AUTO_TOLOV_DATA_DIR"] = os.path.join(FACTORY_DATA_DIR, f"auto_tolov_data_{bid}")
        # Barcha auto_tolov bola-botlar uchun umumiy Telethon ilova hisobi
        # (https://my.telegram.org). Railway Variables ichida kiriting.
        if os.environ.get("TELETHON_API_ID"):
            env["TELETHON_API_ID"] = os.environ.get("TELETHON_API_ID")
        if os.environ.get("TELETHON_API_HASH"):
            env["TELETHON_API_HASH"] = os.environ.get("TELETHON_API_HASH")
        # Har bir auto_tolov bola-bot o'z ichki REST API porti bilan ishga tushadi
        # (8081 + bola-bot ID) — bir xil portga to'qnashmasligi uchun.
        env["AUTO_TOLOV_API_PORT"] = str(8081 + int(bid))
    elif bot_type == "openbudget":
        env["OPENBUDGET_DATA_DIR"] = os.path.join(FACTORY_DATA_DIR, f"openbudget_bot_data_{bid}")
    return env


def _factory_pm2_run(args: list, timeout: int = 20):
    """`pm2 ...` buyrug'ini ishga tushiradi. Bu — bosh bot jarayonining
    ODDIY bolasi (pm2 CLI'ni ishga tushirish), signal yuborish emas —
    shu sababli bu buyruq ushbu hostingda ishlaydi (avval tekshirilgan
    killpg/kill cheklovi faqat ALLAQACHON ishlab turgan bola-bot
    jarayoniga signal yuborishga tegishli edi, yangi jarayon
    ishga tushirishga emas)."""
    try:
        r = _fx_subprocess.run(
            ["pm2", *args], capture_output=True, text=True, timeout=timeout)
        return r.returncode == 0, (r.stdout or "") + (r.stderr or "")
    except Exception as e:
        return False, str(e)


def _factory_is_running(bid: int) -> bool:
    """Bola-botning PM2 ilovasi hozir "online" holatida ekanligini
    tekshiradi — eski FACTORY_RUNNING (xotiradagi Popen) tekshiruvi
    o'rniga endi shu ishlatiladi, chunki bola-botlar endi PM2 orqali
    boshqariladi."""
    name = _factory_pm2_name(bid)
    ok, out = _factory_pm2_run(["jlist"])
    if not ok:
        return False
    try:
        procs = json.loads(out)
    except Exception:
        return False
    for proc in procs:
        if proc.get("name") == name:
            return (proc.get("pm2_env") or {}).get("status") == "online"
    return False




_FACTORY_PROCESS_LOCKS: dict[int, "_fx_threading.RLock"] = {}


def _factory_process_lock(bid: int):
    lock = _FACTORY_PROCESS_LOCKS.get(bid)
    if lock is None:
        lock = _fx_threading.RLock()
        _FACTORY_PROCESS_LOCKS[bid] = lock
    return lock


def factory_spawn(row: dict) -> bool:
    """Bola-botni ALOHIDA PM2 ilovasi sifatida ishga tushuradi.

    ❗ Bu hostingda (coresuz.ru, cagefs-uslubidagi sandbox) Python'ning
    o'zi ishga tushirgan sibling-subprocess'ga os.kill/os.killpg signal
    yuborish BLOKLANGAN (tasdiqlangan: SIGKILL yuborilgandan keyin ham
    jarayon tirik qolган). Shu sababli endi har bir bola-bot PM2'ning
    o'zida ALOHIDA nomlangan ilova ("factory-child-<id>") sifatida
    ro'yxatdan o'tkaziladi — to'xtatish endi ushbu botning HOSTdagi
    "⏸/🗑" tugmasi ishlatgan mexanizm (pm2 delete) orqali bo'ladi, bu esa
    ishlashi allaqachon tasdiqlangan yo'l."""
    bid = row["id"]
    name = _factory_pm2_name(bid)
    with _factory_process_lock(bid):

        # Xavfsizlik uchun — eskisi (agar biror sabab bilan hali PM2'da
        # qolib ketgan bo'lsa) avval tozalanadi, ikkita nusxa bo'lib
        # qolmasligi uchun.
        factory_stop(bid)

        env = _factory_build_child_env(row)
        try:
            with open(_factory_env_file(bid), "w", encoding="utf-8") as f:
                json.dump(env, f)
        except Exception as e:
            logger.error(f"❌ Factory #{bid}: env fayl yozilmadi: {e}")
            return False

        ok, out = _factory_pm2_run([
            "start", SELF_FILE,
            "--name", name,
            "--interpreter", _fx_sys.executable,
            "--time",
            "--", f"--factory-env={_factory_env_file(bid)}",
        ])
        if ok:
            _fx_subprocess.run(["pm2", "save"], capture_output=True, timeout=10)
            factory_db_started(bid)
            logger.info(f"🚀 Factory #{bid} @{row.get('bot_username')} PM2 ilovasi ({name}) sifatida ishga tushdi")
            return True
        logger.error(f"❌ Factory spawn #{bid} (pm2 start): {out}")
        return False


def factory_stop(bid: int):
    """Bola-botni PM2 orqali TO'LIQ o'chiradi (nafaqat to'xtatadi —
    `pm2 delete` ro'yxatdan ham olib tashlaydi, shunda keyingi
    `pm2 start` toza holatdan boshlanadi)."""
    with _factory_process_lock(bid):
        name = _factory_pm2_name(bid)
        ok_stop, out_stop = _factory_pm2_run(["stop", name])
        ok_del, out_del = _factory_pm2_run(["delete", name])
        combined = f"{out_stop}\n{out_del}"
        if ok_stop or ok_del:
            _fx_subprocess.run(["pm2", "save"], capture_output=True, timeout=10)
            logger.warning(f"🧹 Factory #{bid}: PM2 ilovasi ({name}) to'xtatildi/o'chirildi")
        elif "not found" not in combined.lower() and "doesn't exist" not in combined.lower():
            # Ilova umuman topilmagani (allaqachon o'chirilgan) — xato emas.
            logger.error(f"⚠️ Factory #{bid}: pm2 stop/delete natija bermadi: {combined}")

        # PM2 ba'zi hostinglarda polling jarayonini darrov o'chira olmaydi.
        # Shunda /proc orqali aynan shu FACTORY_CHILD_ID bo'yicha qolgan
        # jarayonni topib majburan o'chiramiz.
        time.sleep(0.5)
        _factory_force_kill_child(bid)

        # Diskdagi eski (avvalgi subprocess-asosli patchdan qolgan) PID
        # fayllari bo'lsa ham — endi ishlatilmaydi, lekin bo'lib qolmasin:
        _factory_clear_pid_file(bid)
        try:
            os.remove(_factory_env_file(bid))
        except Exception:
            pass

# ─── Bola-bot qayta ishga tushirishni XAVFSIZ qilish ────────────────────
# Muammo: agar admin sozlamani (rang/matn) tez-tez ketma-ket o'zgartirsa,
# har bir o'zgarish alohida "stop -> sleep(2) -> spawn" vazifasini ishga
# tushiradi. Ular bir-biriga halaqit berib (overlapping), bola-bot
# umuman ishga tushmay qolishi yoki yarim-restart holatida qolib ketishi
# mumkin edi. Bu funksiya bir bot uchun restartlarni NAVBAT bilan
# (bir vaqtning o'zida faqat bittasi) bajaradi va muvaffaqiyatsiz bo'lsa
# adminga xabar beradi.
_FACTORY_RESTART_LOCKS: dict[int, "asyncio.Lock"] = {}

def _get_factory_restart_lock(bid: int) -> "asyncio.Lock":
    lk = _FACTORY_RESTART_LOCKS.get(bid)
    if lk is None:
        lk = asyncio.Lock()
        _FACTORY_RESTART_LOCKS[bid] = lk
    return lk

async def factory_restart_bot(bid: int, row: dict, bot=None, admin_id=None) -> bool:
    """Bola-botni xavfsiz qayta ishga tushiradi. Bir vaqtda faqat bitta
    restart bajariladi (lock orqali) — tez-tez bosilgan tugmalar
    bir-biriga halaqit bermaydi. Ishga tushmasa adminga xabar beradi."""
    lock = _get_factory_restart_lock(bid)
    async with lock:
        try:
            factory_stop(bid)
            await asyncio.sleep(2)
            factory_spawn(row)
            # Process haqiqatan ishga tushib, darrov yiqilmaganini tekshiramiz
            await asyncio.sleep(3)
            alive = _factory_is_running(bid)
            if not alive:
                logger.error(f"factory_restart_bot #{bid}: bot qayta ishga tushmadi yoki darrov yiqildi!")
                if bot is not None and admin_id:
                    try:
                        await bot.send_message(
                            admin_id,
                            f"⚠️ <b>Bot #{bid}</b> qayta ishga tushishda muammo bo'ldi.\n"
                            "Iltimos, yana bir bor «🔄 Standartga qaytarish» yoki sozlamani "
                            "qayta tanlab ko'ring. Davom etsa — Railway loglarini tekshiring.",
                            parse_mode="HTML")
                    except Exception:
                        pass
            return alive
        except Exception as e:
            logger.warning(f"factory_restart_bot #{bid} xato: {e}")
            return False

def _factory_notify_owner_expiring(row: dict, days_left: float):
    """Bot muddati tugashiga ~3 kun (yoki kamroq) qolganda, bot egasiga UNING O'Z
    BOLA BOTI orqali (row['token'] bilan) bir martalik ogohlantirish xabari yuboradi —
    xabar asosiy (parent) «DramlarUz Boti» dan emas, aynan foydalanuvchining o'z
    botidan keladi."""
    try:
        owner_id = row.get("owner_id")
        child_token = row.get("token")
        if not owner_id or not child_token:
            return
        exp_txt = factory_fmt_dt(row.get("expires_at"))
        days_int = max(1, round(days_left))
        text = (
            "⚠️ <b>Diqqat! Bot muddati tugayapti</b>\n\n"
            f"⏳ Tugash vaqti: <code>{exp_txt}</code> (Toshkent vaqti)\n\n"
            f"❗️ Botingizning ishlash muddatiga <b>{days_int} kun</b> qoldi.\n"
            f"Agar muddatni uzaytirmasangiz, <b>{days_int} kundan keyin "
            "botingiz avtomatik to'xtatiladi</b> va ishlamay qoladi.\n\n"
            "<b>Muddatni uzaytirish uchun:</b>\n"
            "1️⃣ <b>@uz_dramlarbot</b> ga kiring\n"
            "2️⃣ «🤝 Hamkorlik Va Pul ishlash» tugmasini bosing\n"
            "3️⃣ «📋 Mening botlarim» tugmasini bosing\n"
            "4️⃣ Botingizni tanlang, tarifni belgilang va muddatni uzaytiring"
        )
        deep_link_kb = {"inline_keyboard": [[
            {"text": "🤝 @uz_dramlarbot ga o'tish", "url": "https://t.me/uz_dramlarbot"}
        ]]}
        # 1) ASOSIY YO'L — bola botning O'ZI orqali yuboramiz, parentdan emas.
        ok, err = _child_bot_send_sync(child_token, "sendMessage",
                                        {"chat_id": owner_id, "text": text, "parse_mode": "HTML",
                                         "reply_markup": deep_link_kb})
        if ok:
            return
        logger.warning(f"factory notice3 #{row.get('id')} bola bot orqali yuborilmadi: {err}")
        # 2) ZAXIRA YO'L — faqat bola bot orqali yuborilmasa (masalan, egasi hali
        #    o'z botiga /start bosmagan bo'lsa), xabar yo'qolib ketmasligi uchun
        #    parent orqali yuboramiz, qaysi bot haqida ekanini aniq ko'rsatamiz.
        if BOT_TOKEN:
            uname = html.escape(str(row.get("bot_username") or f"#{row.get('id')}"))
            fallback_text = f"🤖 Bot: <b>@{uname}</b>\n\n" + text
            ok2, err2 = _child_bot_send_sync(BOT_TOKEN, "sendMessage",
                                              {"chat_id": owner_id, "text": fallback_text, "parse_mode": "HTML",
                                               "reply_markup": deep_link_kb})
            if not ok2:
                logger.warning(f"factory notice3 #{row.get('id')} zaxira (parent) orqali ham yuborilmadi: {err2}")
    except Exception as e:
        logger.error(f"_factory_notify_owner_expiring: {e}")


def factory_watchdog():
    """O'lib qolgan bola-botlarni qayta tushuradi va muddati o'tganlarini to'xtatadi.

    ❗ MUHIM (server qayta ishga tushganda bola-botlar o'chib qolmasligi uchun):
    Bu funksiya — bola-botlarning "tirik" turishini ta'minlaydigan YAGONA doimiy
    mexanizm. Shu sababli u hech qachon butunlay to'xtab qolmasligi kerak — agar
    PostgreSQL ishga tushish paytida vaqtincha javob bermasa ham (Railway'da bu
    odatiy holat), watchdog har 20 soniyada qayta urinib, DB tiklangan zahoti
    barcha aktiv bola-botlarni o'zi avtomatik qayta yuklaydi.

    Shuningdek, har bir aktiv bola-bot uchun muddati tugashiga 3 kun (yoki kamroq)
    qolganda, bot egasiga BIR MARTA ogohlantirish xabari yuboradi (notice3_sent
    bilan belgilanadi — bot uzaytirilganda bu belgi qayta tozalanadi).
    """
    _db_ready = False
    while True:
        try:
            if not _db_ready:
                _db_ready = factory_init_db()
                if not _db_ready:
                    raise RuntimeError("Factory DB hali tayyor emas — qayta uriniladi")
            for row in factory_db_active():
                bid = row["id"]
                # Muddati o'tgan bo'lsa — to'xtatib, 'expired' belgilaymiz
                if factory_is_expired(row):
                    try:
                        factory_db_set_status(bid, "expired")
                        factory_stop(bid)
                        logger.warning(f"⏰ Factory #{bid} muddati o'tdi — to'xtatildi")
                    except Exception as ee:
                        logger.error(f"factory_watchdog expire #{bid}: {ee}")
                    continue
                # ⏰ Muddat tugashiga ≤3 kun qolganda — egasiga BIR MARTA ogohlantirish
                try:
                    days_left = factory_days_left(row)
                    if days_left is not None and 0 < days_left <= 3 and not row.get("notice3_sent"):
                        _factory_notify_owner_expiring(row, days_left)
                        factory_db_mark_notice3_sent(bid)
                except Exception as ee:
                    logger.error(f"factory_watchdog notice3 #{bid}: {ee}")
                if not _factory_is_running(bid):
                    logger.warning(f"♻️ Factory #{bid} qayta tushiramiz (server qayta yoqilgan/o'chgan bo'lsa ham bola-bot avtomatik tiklanadi)")
                    factory_spawn(row)
        except Exception as e:
            logger.error(f"factory_watchdog: {e}")
            _db_ready = False  # keyingi aylanishda DB ulanishni qaytadan tekshiramiz
        time.sleep(20)


def factory_boot_all():
    """Parent ishga tushganda chaqiriladi — watchdog'ni DOIM ishga tushuradi.

    ❗ Avvalgi versiyada: agar PostgreSQL boot paytida bir lahza javob bermasa,
    `factory_init_db()` False qaytarib, funksiya watchdog'ni HECH QACHON
    ishga tushirmasdan to'xtab qolardi — natijada bola-botlar serverdan
    o'chgandan keyin BUTUNLAY tiklanmay qolardi (faqat qo'lda qayta deploy
    qilinganda, ko'pincha omadli holatda, tuzalardi).
    Endi watchdog DB holatidan qat'i nazar har doim ishga tushadi va o'zi
    ichida qayta-qayta urinib, DB tiklangan zahoti barcha aktiv bola-botlarni
    avtomatik qayta tushiradi — shu bilan bola-botlar serverni qayta ishga
    tushirish/qulashidan keyin ham hech qachon butunlay o'chib qolmaydi."""
    if IS_CHILD_BOT:
        return  # bola-bot o'zi ichida factory ishlatmaydi
    _fx_threading.Thread(target=factory_watchdog, daemon=True).start()
    logger.info("🏭 Factory watchdog ishga tushdi — bola-botlar doim avtomatik tiklanib turadi")

