def factory_tariffs_picker_kb() -> dict:
    rows = []
    for bt in FACTORY_BOT_TYPES:
        cnt = len(get_tariffs_for(bt))
        rows.append([ibtn(
            f"{FACTORY_BOT_TYPE_LABELS.get(bt, bt)} ({cnt} ta tarif)",
            data=f"factory_tariffs_admin:{bt}", style="primary")])
    rows.append([ibtn("⬅️ Orqaga", data="factory_admin_list", style="primary")])
    return ikb(rows)

def factory_tariffs_admin_text(bot_type: str = "kino") -> str:
    lst = get_tariffs_for(bot_type)
    lines = [
        f"💰 <b>{FACTORY_BOT_TYPE_LABELS.get(bot_type, bot_type)} — Tariflar</b>",
        "━━━━━━━━━━━━━━━━━━━━",
    ]
    if not lst:
        lines.append("\n📭 Tariflar ro'yxati bo'sh. Yangi tarif qo'shing.")
    else:
        for i, t in enumerate(lst, 1):
            lines.append(
                f"\n<b>{i}.</b> 📅 <b>{html.escape(str(t['label']))}</b>\n"
                f"   ⏱ <code>{int(t['days'])}</code> kun  ·  💵 <b>{int(t['price']):,}</b> so'm".replace(",", " ")
            )
    lines.append("\n━━━━━━━━━━━━━━━━━━━━")
    return "\n".join(lines)

def factory_tariffs_admin_kb(bot_type: str = "kino") -> dict:
    rows = []
    lst = get_tariffs_for(bot_type)
    for i, t in enumerate(lst):
        rows.append([
            ibtn(f"✏️ {t['label']}",  data=f"factory_tariff_edit:{bot_type}:{i}", style="primary"),
            ibtn("🗑",                 data=f"factory_tariff_del:{bot_type}:{i}",  style="danger", emoji_id=PREMIUM_EMOJI_IDS.get("🗑")),
        ])
    rows.append([ibtn("➕ Yangi tarif qo'shish", data=f"factory_tariff_add:{bot_type}", style="success")])
    rows.append([ibtn("⬅️ Bot turini almashtirish", data="factory_tariffs_admin", style="primary")])
    return ikb(rows)

async def factory_send_tariffs_admin(bot, uid, q=None, bot_type: str = None):
    if bot_type is None:
        txt = factory_tariffs_picker_text()
        kb  = factory_tariffs_picker_kb()
    else:
        txt = factory_tariffs_admin_text(bot_type)
        kb  = factory_tariffs_admin_kb(bot_type)
    if q is not None:
        try:
            await q.edit_message_text(txt, parse_mode="HTML", reply_markup=kb)
            return
        except Exception:
            pass
    await sm(bot, uid, txt, kb)

