# AVTOMATIK TO'LOV TIZIMI
#   • VIP bola-bot        → HAMYON API (https://hamyon-api.uz)
#   • Drama (kino) bola-bot → HAMYON API (https://hamyon-api.uz)
#   • Boshqa botlar       → CHECKCARD API (https://checkcard.uz/api)
# Funksiya nomlari (checkcard_*) o'zgartirilmadi — shunchaki ichkarida
# bot turiga qarab kerakli API ga yo'naltiriladi. Chaqiruv kodi
# CheckCard formatidagi javobga tayanadi: shuning uchun Hamyon javobi
# ham CheckCard shakliga o'giriladi:
#   {"status": "success", "order": <pid>, "data": {"status": "paid|pending|cancel"}}
# ══════════════════════════════════════════════════════════

def _is_vip_bot() -> bool:
    """Joriy jarayon VIP (yoki VIP PRO) bola-bot bo'lsa True qaytaradi."""
    try:
        return FACTORY_BOT_TYPE_ENV in ("vip", "vip_pro")
    except Exception:
        return False


def _uses_hamyon() -> bool:
    """Hamyon API orqali avto-to'lov ishlatadigan bot turlari.
    FAQAT bola-botlar (VIP/VIP PRO va Drama/kino) Hamyon API dan foydalanadi.
    Asosiy (parent) bot va boshqa turlar (uc, yulduz) CheckCard API da qoladi."""
    try:
        if not IS_CHILD_BOT:
            return False
        return FACTORY_BOT_TYPE_ENV in ("vip", "vip_pro", "kino")
    except Exception:
        return False


# ─────────────────────────── HAMYON API ────────────────────────────

def _hamyon_create(amount: int, order_id: str) -> dict:
    """Hamyon API orqali yangi to'lov yaratadi.
    Javobni CheckCard-mos shaklga o'giradi.
    """
    try:
        url = f"{HAMYON_API_BASE}/payment/create"
        payload = {
            "shop_id":  HAMYON_SHOP_ID,
            "shop_key": HAMYON_SHOP_KEY,
            "amount":   int(amount),
        }
        r = requests.post(url, data=payload, timeout=20)
        logger.info(f"Hamyon create javob: {r.text[:300]}")
        try:
            data = r.json()
        except Exception:
            return {"status": "error", "message": r.text[:200]}

        pid = data.get("payment_id") or data.get("id") or data.get("order")
        if not pid:
            reason = data.get("message") or data.get("error") or "unknown"
            return {"status": "error", "message": str(reason)}

        return {
            "status": "success",
            "order":  str(pid),
            "card":   data.get("card"),
            "data":   data,
        }
    except Exception as e:
        logger.error(f"Hamyon create xato: {e}")
        return {"status": "error", "message": str(e)}


def _hamyon_check(order: str) -> dict:
    """Hamyon API — to'lov holatini tekshiradi.
    Javob CheckCard formatiga o'giriladi."""
    try:
        url = f"{HAMYON_API_BASE}/merchant/{order}/json"
        r = requests.get(url, timeout=15)
        logger.info(f"Hamyon check javob ({order}): {r.text[:200]}")
        try:
            data = r.json()
        except Exception:
            return {"status": "error"}

        st = str(data.get("status") or "").lower().strip()
        # Hamyon → CheckCard normalizatsiyasi
        if st == "paid":
            norm = "paid"
        elif st in ("cancel", "cancelled", "expired", "canceled"):
            norm = "cancel"
        else:
            norm = "pending"
        return {"status": "success", "data": {"status": norm, "raw": data}}
    except Exception as e:
        logger.error(f"Hamyon check xato: {e}")
        return {"status": "error"}


def _hamyon_cancel(order: str) -> dict:
    """Hamyon API — bekor qilish.
    (Hamyon API'da alohida cancel endpoint yo'q; server tomonida
    to'lov o'z-o'zidan expire bo'ladi. Shuning uchun bu funksiya
    faqat lokal holatni "cancelled" deb belgilash uchun success qaytaradi.)"""
    logger.info(f"Hamyon cancel (lokal) — order={order}")
    return {"status": "success"}


# ─────────────────────────── CHECKCARD API ──────────────────────────

def _checkcard_create(amount: int, order_id: str = None) -> dict:
    """CheckCard API orqali yangi to'lov yaratadi (so'mda)."""
    try:
        if not order_id:
            order_id = f"ord{int(time.time())}"
        url = (f"{CHECKCARD_BASE_URL}?method=create"
               f"&shop_id={CHECKCARD_SHOP_ID}"
               f"&shop_key={CHECKCARD_SHOP_KEY}"
               f"&amount={amount}"
               f"&order={order_id}")
        r = requests.get(url, timeout=20)
        logger.info(f"CheckCard create javob: {r.text[:300]}")
        return r.json()
    except Exception as e:
        logger.error(f"CheckCard create xato: {e}")
        return {"status": "error", "message": str(e)}


def _checkcard_check(order: str) -> dict:
    try:
        url = (f"{CHECKCARD_BASE_URL}?method=check"
               f"&shop_id={CHECKCARD_SHOP_ID}"
               f"&shop_key={CHECKCARD_SHOP_KEY}"
               f"&order={order}")
        r = requests.get(url, timeout=20)
        logger.info(f"CheckCard check javob: {r.text[:200]}")
        return r.json()
    except Exception as e:
        logger.error(f"CheckCard check xato: {e}")
        return {"status": "error"}


def _checkcard_cancel(order: str) -> dict:
    try:
        url = (f"{CHECKCARD_BASE_URL}?method=cancel"
               f"&shop_id={CHECKCARD_SHOP_ID}"
               f"&shop_key={CHECKCARD_SHOP_KEY}"
               f"&order={order}")
        r = requests.get(url, timeout=20)
        logger.info(f"CheckCard cancel javob ({order}): {r.text[:200]}")
        return r.json()
    except Exception as e:
        logger.error(f"CheckCard cancel xato: {e}")
        return {"status": "error"}


# ─────────── UMUMIY WRAPPERLAR (chaqiruv kodi shularni ishlatadi) ───────────

def checkcard_create_payment(amount: int, order_id: str = None) -> dict:
    """VIP va Drama (kino) botlar → Hamyon API; boshqa botlar → CheckCard API."""
    if _uses_hamyon():
        if not order_id:
            order_id = f"ord{int(time.time())}"
        return _hamyon_create(amount, order_id)
    return _checkcard_create(amount, order_id)


def checkcard_check_payment(order: str) -> dict:
    """VIP va Drama (kino) botlar → Hamyon check; boshqa botlar → CheckCard check."""
    if _uses_hamyon():
        return _hamyon_check(order)
    return _checkcard_check(order)


def checkcard_cancel_payment(order: str) -> dict:
    """VIP va Drama (kino) botlar → Hamyon cancel (lokal); boshqa botlar → CheckCard cancel."""
    if _uses_hamyon():
        return _hamyon_cancel(order)
    return _checkcard_cancel(order)


def checkcard_shop_info() -> dict:
    """Do'kon ma'lumotlarini oladi."""
    try:
        url = (f"{CHECKCARD_BASE_URL}?method=shop"
               f"&shop_id={CHECKCARD_SHOP_ID}"
               f"&shop_key={CHECKCARD_SHOP_KEY}")
        r = requests.get(url, timeout=20)
        return r.json()
    except Exception as e:
        logger.error(f"CheckCard shop info xato: {e}")
        return {"status": "error"}


def price_to_int(value) -> int:
    """Narxni xavfsiz int ga aylantiradi. 0/bo'sh qiymat bepul hisoblanadi."""
    try:
        if value in (None, "", 0, "0"):
            return 0
        return int(str(value).strip())
    except Exception:
        return 0


def episode_paid_key(code, ep) -> str:
    """Har bir kino-qism uchun yagona alohida to'lov kaliti."""
    return f"{str(code).upper()}_{str(ep)}"


def _clear_movie_paid_access(code: str, ep: str | None = None):
    """Kino/qism o'chganda foydalanuvchilardagi eski ochilgan accesslarni ham tozalaydi."""
    code = str(code).upper().strip()
    target_key = episode_paid_key(code, ep) if ep is not None else None
    prefix = f"{code}_"
    for user in (RAM.users or {}).values():
        paid = user.get("paid_episodes") or {}
        if target_key:
            paid.pop(target_key, None)
        else:
            for key in list(paid.keys()):
                if str(key).startswith(prefix):
                    paid.pop(key, None)


def _shift_movie_paid_access_after_ep_delete(code: str, deleted_ep: int):
    """Bitta qism o'chirilganda keyingi qismlarning user access raqamlarini ham siljitadi."""
    code = str(code).upper().strip()
    prefix = f"{code}_"
    for user in (RAM.users or {}).values():
        paid = user.get("paid_episodes") or {}
        if not isinstance(paid, dict):
            continue
        new_paid = {}
        for key, value in list(paid.items()):
            key_s = str(key)
            if not key_s.startswith(prefix):
                new_paid[key] = value
                continue
            try:
                ep_num = int(key_s.rsplit("_", 1)[1])
            except Exception:
                continue
            if ep_num < deleted_ep:
                new_paid[key] = value
            elif ep_num > deleted_ep:
                new_paid[episode_paid_key(code, ep_num - 1)] = value
        user["paid_episodes"] = new_paid


def has_approved_payment(user_id, code, ep) -> bool:
    """Faqat shu foydalanuvchi + shu kino + shu qism uchun tasdiqlangan chekni tekshiradi."""
    uid = str(user_id)
    code = str(code).upper()
    ep = str(ep)
    for pay in (RAM.pending_payments or {}).values():
        if (str(pay.get("user_id")) == uid
                and str(pay.get("code", "")).upper() == code
                and str(pay.get("ep")) == ep
                and pay.get("status") == "approved"):
            return True
    return False


def is_premium_user(user_id) -> bool:
    """Foydalanuvchi premium muddati ichidami?"""
    try:
        u = RAM.get_user(str(user_id)) or {}
        until = float(u.get("premium_until") or 0)
        return until > time.time()
    except Exception:
        return False


def is_blocked_user(user_id) -> bool:
    """Foydalanuvchi admin tomonidan bloklangan mi?"""
    uid_str = str(user_id)
    return uid_str in (RAM.blocked_users or {})


def premium_left_days(user_id) -> int:
    try:
        u = RAM.get_user(str(user_id)) or {}
        until = float(u.get("premium_until") or 0)
        left = (until - time.time()) / 86400.0
        return int(left) if left > 0 else 0
    except Exception:
        return 0


EPISODE_ACCESS_DURATION = 7 * 24 * 3600  # 7 kun = 604800 soniya (sotib olgandan keyin 7 kun bepul)


def is_episode_paid(user_id, code, ep) -> bool:
    """
    Bir qism sotib olingani faqat o'sha qism uchun tekshiriladi.
    Premium foydalanuvchilar uchun barcha qismlar bepul ochiq.
    Balansdan sotib olingan qismlar 7 kundan keyin qayta pullik bolib qoladi.
    """
    if is_premium_user(user_id):
        return True
    uid = str(user_id)
    code = str(code).upper()
    ep = str(ep)
    key = episode_paid_key(code, ep)
    user = RAM.ensure_user(uid)
    paid = user.setdefault("paid_episodes", {})
    value = paid.get(key)

    if isinstance(value, dict):
        if value.get("status") != "approved" and not value.get("approved"):
            return False
        # Expire tekshirish — faqat balance orqali sotib olingan qismlar uchun
        expire_at = value.get("expire_at")
        if expire_at:
            if time.time() > float(expire_at):
                return False  # Muddati otgan — qayta pullik
        return True

    if value:
        return has_approved_payment(uid, code, ep)

    return False


def episode_expires_in(user_id, code, ep) -> int:
    """Qism muddati tugashiga necha soniya qolganini qaytaradi. 0 = muddatsiz yoki otgan."""
    uid = str(user_id)
    code = str(code).upper()
    ep = str(ep)
    key = episode_paid_key(code, ep)
    user = RAM.ensure_user(uid)
    paid = user.get("paid_episodes", {})
    value = paid.get(key)
    if isinstance(value, dict) and value.get("expire_at"):
        left = float(value["expire_at"]) - time.time()
        return max(0, int(left))
    return 0


