# ─── UNICODE QALIN ─────────────────────────────────────────
def to_bold(text: str) -> str:
    result = []
    for ch in text:
        if 'A' <= ch <= 'Z':   result.append(chr(0x1D5D4 + ord(ch) - ord('A')))
        elif 'a' <= ch <= 'z': result.append(chr(0x1D5EE + ord(ch) - ord('a')))
        elif '0' <= ch <= '9': result.append(chr(0x1D7EC + ord(ch) - ord('0')))
        else:                  result.append(ch)
    return ''.join(result)

