def _get_pg_conn():
    """PostgreSQL ulanish hosil qiladi."""
    if not DATABASE_URL:
        return None
    try:
        conn = _pg_connect(DATABASE_URL)
        return conn
    except Exception as e:
        logger.error(f"PostgreSQL ulanish xato: {e}")
        return None


def _pg_init_table():
    """Jadval yo'q bo'lsa yaratadi."""
    conn = _get_pg_conn()
    if not conn:
        return False
    try:
        with conn.cursor() as cur:
            cur.execute("""
                CREATE TABLE IF NOT EXISTS bot_data (
                    key TEXT PRIMARY KEY,
                    value JSONB NOT NULL,
                    updated_at TIMESTAMP DEFAULT NOW()
                )
            """)
        conn.commit()
        conn.close()
        logger.info("✅ PostgreSQL jadval tayyor")
        return True
    except Exception as e:
        logger.error(f"PostgreSQL jadval yaratish xato: {e}")
        return False


def _save_postgres(data: dict, retries: int = 3) -> bool:
    """PostgreSQL ga saqlaydi."""
    if not DATABASE_URL or not PSYCOPG2_AVAILABLE:
        return False
    movies = data.get("movies") if isinstance(data, dict) else None
    if isinstance(movies, dict) and len(movies) == 0 and len(RAM.movies) > 0:
        logger.warning("🛑 Bo'sh movies bilan PostgreSQL ga yozish RAD ETILDI — himoya.")
        return False
    for attempt in range(retries):
        conn = None
        try:
            conn = _get_pg_conn()
            if not conn:
                raise Exception("Ulanish yo'q")
            with conn.cursor() as cur:
                cur.execute("""
                    INSERT INTO bot_data (key, value, updated_at)
                    VALUES ('main', %s, NOW())
                    ON CONFLICT (key) DO UPDATE
                    SET value = EXCLUDED.value, updated_at = NOW()
                """, (json.dumps(data, ensure_ascii=False),))
            conn.commit()
            conn.close()
            size_kb = len(json.dumps(data, ensure_ascii=False).encode("utf-8")) / 1024
            logger.info(f"✅ PostgreSQL saqlandi ({size_kb:.1f} KB)")
            return True
        except Exception as e:
            logger.error(f"PostgreSQL save #{attempt+1} xato: {e}")
            DB_STATUS["last_err_detail"] = str(e)
            if conn:
                try: conn.close()
                except: pass
        if attempt < retries - 1:
            time.sleep(3 * (attempt + 1))
    return False


def _load_postgres() -> dict | None:
    """PostgreSQL dan yuklaydi."""
    if not DATABASE_URL or not PSYCOPG2_AVAILABLE:
        return None
    for attempt in range(6):
        conn = None
        try:
            conn = _get_pg_conn()
            if not conn:
                raise Exception("Ulanish yo'q")
            with conn.cursor() as cur:
                cur.execute("SELECT value FROM bot_data WHERE key = 'main'")
                row = cur.fetchone()
            conn.close()
            if row:
                data = row[0]
                if isinstance(data, dict):
                    logger.info(f"✅ PostgreSQL dan yuklandi: "
                                f"{len(data.get('movies', {}))} kino, "
                                f"{len(data.get('users', {}))} user")
                    return data
                elif isinstance(data, str):
                    parsed = json.loads(data)
                    logger.info(f"✅ PostgreSQL dan yuklandi (str): "
                                f"{len(parsed.get('movies', {}))} kino")
                    return parsed
            else:
                logger.warning("PostgreSQL da ma'lumot yo'q (bo'sh jadval)")
                return {}
        except Exception as e:
            logger.error(f"PostgreSQL load #{attempt+1} xato: {e}")
            DB_STATUS["last_err_detail"] = str(e)
            if conn:
                try: conn.close()
                except: pass
        if attempt < 5:
            time.sleep(2 * (attempt + 1))
    logger.error("❌ PostgreSQL dan yuklab bo'lmadi (6 urinish).")
    return None


# JSONBlob funksiyalar — PostgreSQL ga yo'naltiriladi (orqaga moslik)
def _save_jsonblob(data: dict, retries: int = 3) -> bool:
    return _save_postgres(data, retries)


def _load_jsonblob() -> dict | None:
    return _load_postgres()


def _load_parent_emoji_ids() -> dict | None:
    """Bola-bot uchun: asosiy (parent) bot sozlagan emoji_id larni o'qiydi.

    ENDI BIRINCHI NAVBATDA parentning mahalliy zaxira fayli (db_backup.json)
    dan o'qiydi — bu Postgres'ga umuman bog'liq emas, shuning uchun DATABASE_URL
    ishlamasa/ulanmasa ham (masalan boshqa hostingda) tugmadagi emoji bola-botga
    to'liq chiqadi. Postgres faqat qo'shimcha/ixtiyoriy urinish sifatida qoladi."""
    # 1) Mahalliy fayl — asosiy manba
    try:
        if os.path.exists(PARENT_LOCAL_BACKUP_FILE):
            with open(PARENT_LOCAL_BACKUP_FILE, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, dict):
                eids = data.get("emoji_ids") or {}
                out = {k: str(v).strip() for k, v in eids.items() if str(v).strip().isdigit()}
                if out:
                    return out
    except Exception as e:
        logger.error(f"_load_parent_emoji_ids (mahalliy fayl) xato: {e}")
    # 2) PostgreSQL — ixtiyoriy, mavjud bo'lsa qo'shimcha urinish
    if not DATABASE_URL or not PSYCOPG2_AVAILABLE:
        return None
    try:
        u = _fx_urlparse(DATABASE_URL)
        q = dict(_fx_parse_qsl(u.query))
        q["options"] = "-c search_path=public"
        parent_url = _fx_urlunparse(u._replace(query=_fx_urlencode(q, quote_via=_fx_quote)))
        conn = _pg_connect(parent_url)
        try:
            with conn.cursor() as cur:
                cur.execute("SELECT value FROM public.bot_data WHERE key = 'main'")
                row = cur.fetchone()
        finally:
            try: conn.close()
            except: pass
        if not row:
            return None
        data = row[0]
        if isinstance(data, str):
            data = json.loads(data)
        if not isinstance(data, dict):
            return None
        eids = data.get("emoji_ids") or {}
        # Faqat raqamli (premium custom emoji) IDlarni qaytaramiz
        return {k: str(v).strip() for k, v in eids.items() if str(v).strip().isdigit()}
    except Exception as e:
        logger.error(f"_load_parent_emoji_ids (Postgres) xato: {e}")
        return None


# ══════════════════════════════════════════════════════════
# DB YUKLASH — ishga tushganda bir marta chaqiriladi
# ══════════════════════════════════════════════════════════

def _merge_db(blob: dict | None, local: dict | None) -> dict:
    """
    JSONBlob va lokal fayldagi ma'lumotlarni BIRLASHTIRADI.
    Hech qanday kino yo'qolmasligi uchun:
      • Har bir kino bo'yicha — qaysi manbada ko'proq qism bo'lsa, o'sha tanlanadi
      • Faqat bir manbada bor kinolar — o'shanday qo'shiladi
      • Foydalanuvchilar — birlashadi (lokal ustun, chunki yangiroq)
      • Sozlamalar — lokal ustun
    """
    blob  = blob  if isinstance(blob,  dict) else {}
    local = local if isinstance(local, dict) else {}

    blob_movies  = (blob.get("movies")  or {}) if isinstance(blob.get("movies"),  dict) else {}
    local_movies = (local.get("movies") or {}) if isinstance(local.get("movies"), dict) else {}

    deleted_codes = {}
    for src in (blob, local):
        try:
            dc = ((src.get("settings") or {}).get("deleted_movie_codes") or {})
            if isinstance(dc, dict):
                deleted_codes.update({str(k).upper().strip(): v for k, v in dc.items()})
        except Exception:
            pass

    merged_movies: dict = {}
    all_codes = set(blob_movies.keys()) | set(local_movies.keys())
    for code in all_codes:
        code_key = str(code).upper().strip()
        b = blob_movies.get(code)
        l = local_movies.get(code)
        deleted_at = float(deleted_codes.get(code_key) or 0)
        newest_added = max(
            float((b or {}).get("added_at") or 0),
            float((l or {}).get("added_at") or 0),
        )
        if deleted_at and newest_added <= deleted_at:
            continue
        if deleted_at and newest_added > deleted_at:
            deleted_codes.pop(code_key, None)
        if b and not l:
            merged_movies[code] = b
        elif l and not b:
            merged_movies[code] = l
        elif b and l:
            # Ikkalasida ham bor — ko'proq qism bor versiyani olamiz
            b_eps = len((b or {}).get("episodes", []) or [])
            l_eps = len((l or {}).get("episodes", []) or [])
            if l_eps >= b_eps:
                base = dict(l)
                # narxlarni ham birlashtir
                prices = dict((b or {}).get("prices", {}) or {})
                prices.update((l or {}).get("prices", {}) or {})
                base["prices"] = prices
                merged_movies[code] = base
            else:
                base = dict(b)
                prices = dict((l or {}).get("prices", {}) or {})
                prices.update((b or {}).get("prices", {}) or {})
                base["prices"] = prices
                merged_movies[code] = base

    # Foydalanuvchilar — birlashadi, balans yo'qolmasin
    merged_users = {}
    blob_users  = (blob.get("users")  or {}) if isinstance(blob.get("users"),  dict) else {}
    local_users = (local.get("users") or {}) if isinstance(local.get("users"), dict) else {}
    all_uids = set(blob_users.keys()) | set(local_users.keys())
    for uid_key in all_uids:
        bu = blob_users.get(uid_key) or {}
        lu = local_users.get(uid_key) or {}
        if not bu:
            merged_users[uid_key] = lu
        elif not lu:
            merged_users[uid_key] = bu
        else:
            # Ikkalasida bor — lokal asosiy, lekin balans/topup_total ni max olamiz
            merged = dict(lu)
            # Balans: ikkalasidan kattasini ol (yo'qolmasin)
            b_bal  = int(bu.get("balance") or 0)
            l_bal  = int(lu.get("balance") or 0)
            merged["balance"] = max(b_bal, l_bal)
            b_top  = int(bu.get("topup_total") or 0)
            l_top  = int(lu.get("topup_total") or 0)
            merged["topup_total"] = max(b_top, l_top)
            # paid_episodes — birlashtir (ikkalasidagi ham bo'lsin)
            paid_b = bu.get("paid_episodes") or {}
            paid_l = lu.get("paid_episodes") or {}
            merged_paid = dict(paid_b)
            merged_paid.update(paid_l)
            merged["paid_episodes"] = merged_paid
            # premium_until — yangiroqni ol
            p_b = float(bu.get("premium_until") or 0)
            p_l = float(lu.get("premium_until") or 0)
            merged["premium_until"] = max(p_b, p_l)
            merged_users[uid_key] = merged

    # Boshqa maydonlar — lokal ustun, bo'lmasa blob
    def pick(key, default):
        if key in local and local.get(key):
            return local.get(key)
        if key in blob and blob.get(key):
            return blob.get(key)
        return default

    # ❗ payment_methods / premium_plans uchun ALOHIDA pick:
    #   foydalanuvchi qo'lda o'chirsa (bo'sh ro'yxat) — bo'sh holat
    #   saqlanishi kerak. Shuning uchun truthy emas, kalit
    #   mavjudligi bo'yicha tanlaymiz. Lokal har o'zgarishda
    #   darhol yoziladi, shuning uchun lokal ustun turadi.
    def pick_exact(key, default):
        if key in local:
            return local.get(key) if local.get(key) is not None else default
        if key in blob:
            return blob.get(key) if blob.get(key) is not None else default
        return default

    merged_settings = pick("settings", {
        "install_file_id": None, "install_video_id": None, "kino_kanal_url": "",
    })
    if not isinstance(merged_settings, dict):
        merged_settings = {}
    merged_settings["deleted_movie_codes"] = deleted_codes

    return {
        "movies":           merged_movies,
        "users":            merged_users,
        "channels":         pick("channels", []),
        "simple_links":     pick("simple_links", []),
        "card_number":      pick("card_number", ""),
        "pending_payments": pick("pending_payments", {}),
        "settings":         merged_settings,
        "stats":            pick("stats", {"total_views": 0}),
        "btn_texts":        pick("btn_texts", {}),
        "emoji_ids":        pick("emoji_ids", {}),
        "sub_admins":       pick("sub_admins", {}),
        "blocked_users":    pick("blocked_users", {}),
        "premium_plans":    pick_exact("premium_plans", []),
        "payment_methods":  pick_exact("payment_methods", {"auto": [], "manual": []}),
    }


def _sync_factory_prices_from_ram():
    """
    ⚠️ MUHIM TUZATISH: Bot yaratish narxlari (Dramlar/VIP/Yulduz) va tekin
    kunlar avval alohida fayllarga (+ ixtiyoriy alohida PG key'larga) saqlanardi.
    Bu ayrim serverlarda (masalan Railway'da lokal disk restart/redeployda
    tozalanadi) narxni o'zgartirgandan keyin qayta ochilganda ESKI narxni
    ko'rsatishga olib kelardi.

    Endi bu qiymatlar RAM.settings ichida saqlanadi — bu aynan referral_amount,
    kino_kanal_url va boshqa sozlamalar ishlatadigan, isbotlangan ishonchli
    saqlash yo'li (PostgreSQL "bot_data" jadvali, key='main', butun RAM bilan
    birga). Shu funksiya db_initial_load() dan keyin chaqiriladi va RAM dan
    global narx o'zgaruvchilarini to'g'irlaydi (agar RAM'da qiymat bo'lmasa —
    eski fayl/PG-key qiymatini yoki defaultni RAM'ga yozib qo'yadi).
    """
    global BOT_CREATE_PRICE, VIP_CREATE_PRICE, VIP_PRO_CREATE_PRICE, YULDUZ_CREATE_PRICE, OPENBUDGET_CREATE_PRICE, AUTO_TOLOV_CREATE_PRICE, BOT_TRIAL_DAYS
    s = RAM.settings
    changed = False

    def _sync_one(ram_key, cur_val, default_val):
        nonlocal changed
        v = s.get(ram_key)
        if isinstance(v, (int, float)) and v >= 0:
            return int(v)
        # RAM'da hali yo'q — hozirgi (fayl/PG-key'dan yuklangan) qiymatni RAM'ga yozamiz
        s[ram_key] = int(cur_val if cur_val is not None else default_val)
        changed = True
        return s[ram_key]

    BOT_CREATE_PRICE   = _sync_one("factory_create_price",      BOT_CREATE_PRICE,   150_000)
    VIP_CREATE_PRICE   = _sync_one("factory_vip_create_price",  VIP_CREATE_PRICE,   50_000)
    VIP_PRO_CREATE_PRICE = _sync_one("factory_vip_pro_create_price", VIP_PRO_CREATE_PRICE, 50_000)
    YULDUZ_CREATE_PRICE = _sync_one("factory_yulduz_create_price",YULDUZ_CREATE_PRICE, 150_000)
    OPENBUDGET_CREATE_PRICE = _sync_one("factory_openbudget_create_price", OPENBUDGET_CREATE_PRICE, 50_000)
    AUTO_TOLOV_CREATE_PRICE = _sync_one("factory_auto_tolov_create_price", AUTO_TOLOV_CREATE_PRICE, 50_000)
    BOT_TRIAL_DAYS     = _sync_one("factory_trial_days",        BOT_TRIAL_DAYS,     30)

    if changed:
        try:
            _save_postgres(RAM.to_dict(), retries=1)
        except Exception as e:
            logger.error(f"_sync_factory_prices_from_ram save xato: {e}")
    logger.info(f"💰 Bot yaratish narxlari RAM'dan yuklandi: kino={BOT_CREATE_PRICE} "
                f"vip={VIP_CREATE_PRICE} vip_pro={VIP_PRO_CREATE_PRICE} yulduz={YULDUZ_CREATE_PRICE} "
                f"openbudget={OPENBUDGET_CREATE_PRICE} auto_tolov={AUTO_TOLOV_CREATE_PRICE} trial_days={BOT_TRIAL_DAYS}")


async def _set_factory_price_setting(ram_key: str, value: int):
    """Narx/sozlamani RAM.settings'ga yozadi va ISHONCHLI (asosiy) saqlash
    yo'li orqali darhol saqlaydi — restart/redeploy'da yo'qolmasligi uchun."""
    RAM.settings[ram_key] = int(value)
    try:
        await save_now()
    except Exception as e:
        logger.error(f"_set_factory_price_setting({ram_key}) save_now xato: {e}")
        try:
            await save_sync()
        except Exception as e2:
            logger.error(f"_set_factory_price_setting({ram_key}) save_sync xato: {e2}")



def db_initial_load():
    """
    Ishga tushganda:
    1. PostgreSQL jadvalni tekshiradi/yaratadi
    2. PostgreSQL VA lokal fayldan ikkalasini ham yuklaymiz
    3. Ularni BIRLASHTIRAMIZ (hech qanday kino yo'qolmaydi)
    4. RAMga yozamiz
    5. Ikkala manbaga ham birlashtirilgan natijani sync qilamiz

    ❗ MUHIM: Agar PostgreSQL yuklab bo'lmasa VA lokal ham bo'sh bo'lsa —
       bot bo'sh RAM bilan ishga tushadi.
    """
    logger.info("🔄 Ma'lumotlar yuklanmoqda (PostgreSQL + lokal birlashtirish)...")

    # PostgreSQL jadvalni yaratamiz (yo'q bo'lsa)
    if DATABASE_URL and PSYCOPG2_AVAILABLE:
        _pg_init_table()

    if IS_CHILD_BOT:
        # ❗ MUHIM XAVFSIZLIK TUZATISHI:
        # Ilgari bu yerda FAQAT PostgreSQL tekshirilardi. Agar hosting reset/restart
        # vaqtida Postgres'ga ulanish bir zumga muvaffaqiyatsiz bo'lsa (masalan tarmoq
        # sekinlashsa yoki DB hali tayyor bo'lmasa), bot buni "yangi bola-bot" deb
        # xato tushunib, DARHOL bo'sh bazani Postgres'ga yozib, haqiqiy ma'lumotni
        # (kinolar, userlar, balanslar) O'CHIRIB YUBORARDI.
        #
        # Endi har bir bola-bot o'zining ALOHIDA lokal fayliga (db_backup_<id>.json,
        # movies_backup_<id>.json — child_data papkasida/instansiya papkasida saqlanadi)
        # ham tayanadi. Bu fayl har bir o'zgarishda darhol yoziladi (save_now/schedule_save),
        # shuning uchun Postgres vaqtincha ishlamay qolsa ham ma'lumot fayldan tiklanadi.
        # Bo'sh baza faqat ikkala manba (Postgres VA lokal fayl) haqiqatan ham
        # bo'sh bo'lgandagina (ya'ni bot hali umuman ishlatilmagan bo'lsa) yaratiladi.
        blob  = _load_postgres()
        local = _load_local()

        has_blob  = isinstance(blob, dict)  and bool(blob.get("movies")  or blob.get("users")  or blob.get("settings"))
        has_local = isinstance(local, dict) and bool(local.get("movies") or local.get("users") or local.get("settings"))

        if has_blob and has_local:
            merged = _merge_db(blob, local)
            RAM.from_dict(merged)
            logger.info(f"✅ Bola-bot #{FACTORY_CHILD_ID or '?'} Postgres+lokal birlashtirildi: {len(RAM.movies)} kino, {len(RAM.users)} user")
            _save_local(merged)
        elif has_blob:
            RAM.from_dict(blob)
            logger.info(f"✅ Bola-bot #{FACTORY_CHILD_ID or '?'} o'z bazasidan yuklandi: {len(RAM.movies)} kino, {len(RAM.users)} user")
            _save_local(blob)
        elif has_local:
            # Postgres o'qilmadi (ulanish xatosi yoki vaqtincha ishlamayapti) —
            # LEKIN lokal faylda ma'lumot bor. HECH QACHON bo'sh baza yozmaymiz.
            RAM.from_dict(local)
            logger.warning(f"⚠️ Bola-bot #{FACTORY_CHILD_ID or '?'} Postgres'dan yuklanmadi — "
                            f"lokal zaxira fayldan tiklandi: {len(RAM.movies)} kino, {len(RAM.users)} user. "
                            "Postgres ustiga BO'SH yozilmadi (ma'lumot himoyalandi).")
            # Postgres qayta tiklanganda (keyingi saqlashda) haqiqiy ma'lumot yoziladi.
        else:
            empty = factory_empty_db()
            RAM.from_dict(empty)
            if DATABASE_URL and PSYCOPG2_AVAILABLE:
                _save_postgres(empty, retries=1)
            _save_local(empty)
            logger.info(f"🆕 Bola-bot #{FACTORY_CHILD_ID or '?'} yangi bo'sh baza bilan ochildi")
        # ─── Asosiy (parent) botdan premium emoji ID larni olib kelamiz ───
        try:
            parent_emojis = _load_parent_emoji_ids()
            if parent_emojis:
                changed = False
                for _k, _v in parent_emojis.items():
                    _vs = str(_v).strip()
                    if _vs.isdigit() and RAM.emoji_ids.get(_k) != _vs:
                        RAM.emoji_ids[_k] = _vs
                        changed = True
                if changed:
                    logger.info(f"✨ Parent bot dan {len(parent_emojis)} ta premium emoji ID ko'chirildi")
                    try:
                        _save_postgres(RAM.to_dict(), retries=1)
                    except Exception as _se:
                        logger.error(f"emoji_ids save xato: {_se}")
        except Exception as _pe:
            logger.error(f"Parent emoji_ids olishda xato: {_pe}")
        EMOJI_IDS.clear()
        EMOJI_IDS.update(RAM.emoji_ids)
        return

    blob  = _load_postgres()
    local = _load_local()

    has_blob  = bool(blob  and (blob.get("movies")  or blob.get("users")))
    has_local = bool(local and (local.get("movies") or local.get("users")))

    # ❗ XAVFSIZLIK: agar JSONBlob URL berilgan bo'lsa-yu, undan
    # yuklab bo'lmagan bo'lsa — lokal fayldan ishlashda davom etamiz.
    # load_failed ni BOTNI TO'XTATISH uchun emas, faqat log uchun ishlatamiz.
    # Kinolar qo'shilganda save_now() chaqiriladi va JSONBlob ga yozishga urinadi.
    if DATABASE_URL and blob is None:
        logger.error("🛑 PostgreSQL dan yuklab bo'lmadi! "
                     "Lokal fayldan ishlashda davom etamiz.")
        DB_STATUS["storage_ok"] = False
        DB_STATUS["ram_only"]   = True
        DB_STATUS["last_err"]   = "JSONBlob yuklanmadi — lokal fayldan yuklanmoqda"
        # load_failed = False qilamiz — saqlash bloklanmasin!
        DB_STATUS["load_failed"] = False
        if has_local:
            RAM.from_dict(local)
            for _k in list(RAM.emoji_ids.keys()):
                if not str(RAM.emoji_ids.get(_k, "")).strip().isdigit():
                    del RAM.emoji_ids[_k]
            EMOJI_IDS.clear()
            EMOJI_IDS.update(RAM.emoji_ids)
            logger.warning(f"⚠️ Faqat lokal yuklandi: {len(RAM.movies)} kino. "
                           "JSONBlob ga keyinroq uriniladi...")
        else:
            RAM.loaded = True
            logger.warning("⚠️ Hech narsa yuklanmadi. Bo'sh RAM bilan ishga tushdi.")
        return

    if not has_blob and not has_local:
        logger.warning("⚠️ Ma'lumot topilmadi — bo'sh RAM boshlanadi")
        RAM.loaded = True
        return

    merged = _merge_db(blob, local)
    RAM.from_dict(merged)

    # ─── Eski oddiy emoji (📁 📩 🦹 va h.k.) larni RAM dan va bazadan tozalaymiz ───
    for _k in list(RAM.emoji_ids.keys()):
        _v = str(RAM.emoji_ids.get(_k, "")).strip()
        if not _v.isdigit():
            del RAM.emoji_ids[_k]
    EMOJI_IDS.clear()
    EMOJI_IDS.update(RAM.emoji_ids)

    # Tozalangan emoji_ids bilan merged ni qayta yasaymiz — bazaga shu saqlansin
    merged["emoji_ids"] = dict(RAM.emoji_ids)

    blob_eps  = sum(len(m.get("episodes", []) or []) for m in (blob.get("movies")  or {}).values()) if has_blob  else 0
    local_eps = sum(len(m.get("episodes", []) or []) for m in (local.get("movies") or {}).values()) if has_local else 0
    merged_eps = sum(len(m.get("episodes", []) or []) for m in RAM.movies.values())
    logger.info(f"✅ Birlashtirildi → RAM: {len(RAM.movies)} kino, {merged_eps} qism, {len(RAM.users)} user "
                f"(blob: {len(blob.get('movies',{}) if has_blob else {})}/{blob_eps}, "
                f"lokal: {len(local.get('movies',{}) if has_local else {})}/{local_eps})")

    # Ikkala manbaga ham birlashtirilgan natijani yozib qo'yamiz —
    # endi keyingi safar ham hech narsa yo'qolmaydi.
    _save_local(merged)
    if DATABASE_URL:
        threading.Thread(target=_save_postgres, args=(copy.deepcopy(merged),), daemon=True).start()
        logger.info("⏳ Birlashtirilgan ma'lumot PostgreSQL ga sync qilinmoqda (fon)...")


# ══════════════════════════════════════════════════════════
# SAQLASH — RAM → lokal + JSONBlob (debounced background)
# ══════════════════════════════════════════════════════════
#
# Strategiya:
#   • RAM      — darhol yoziladi (millisaniyada)
#   • Lokal    — har o'zgarishda darhol yoziladi (tez, ishonchli)
#   • JSONBlob — DEBOUNCE bilan fon rejimida (oxirgi o'zgarishdan
#                JSONBLOB_DEBOUNCE soniya keyin bir marta yoziladi).
#   Misol: admin ketma-ket 10 ta qism yuborsa — JSONBlob ga
#          BIR MARTA, hammasi tugagandan keyin yoziladi.
# ──────────────────────────────────────────────────────────

JSONBLOB_DEBOUNCE = 12.0   # soniya — qism yuborish tugagandan keyin
LOCAL_DEBOUNCE    = 1.5    # soniya — lokal disk yozish ham debounced

_jsonblob_timer_task = None     # asyncio.Task — kutilayotgan saqlash
_local_timer_task    = None     # asyncio.Task — lokal debounced yozish
_jsonblob_save_lock = None      # asyncio.Lock — _setup da yaratiladi


def _ensure_lock():
    global _jsonblob_save_lock
    if _jsonblob_save_lock is None:
        _jsonblob_save_lock = asyncio.Lock()
    return _jsonblob_save_lock


async def _do_jsonblob_save() -> bool:
    """Haqiqiy JSONBlob ga yozish (status ham yangilanadi)."""
    async with _ensure_lock():
        data = RAM.to_dict()
        ok = await asyncio.to_thread(_save_jsonblob, data)
        now_str = datetime.now().strftime("%H:%M:%S")
        if ok:
            DB_STATUS.update({
                "storage_ok": True,
                "fail_count": 0,
                "last_save_ok": now_str,
                "ram_only": False,
                "pending_save": False,
            })
        else:
            DB_STATUS["fail_count"] = DB_STATUS.get("fail_count", 0) + 1
            DB_STATUS["last_err"] = now_str
            if DB_STATUS["fail_count"] >= 2:
                DB_STATUS.update({"storage_ok": False, "ram_only": True})
        return ok


async def _delayed_jsonblob_save(delay: float):
    """Belgilangan vaqtdan keyin JSONBlob ga yozish."""
    try:
        await asyncio.sleep(delay)
    except asyncio.CancelledError:
        return  # yangi o'zgarish keldi — bu task bekor qilindi
    try:
        await _do_jsonblob_save()
    except Exception as e:
        logger.error(f"JSONBlob debounced save xato: {e}")


async def _delayed_local_save(delay: float):
    """Belgilangan vaqtdan keyin lokal faylga yozish (debounced)."""
    try:
        await asyncio.sleep(delay)
    except asyncio.CancelledError:
        return
    try:
        # to_dict() (deepcopy) ham thread ichida — event loop bloklanmasin
        def _do():
            _save_local(RAM.to_dict())
        await asyncio.to_thread(_do)
    except Exception as e:
        logger.error(f"Lokal debounced save xato: {e}")


async def schedule_save(delay: float = JSONBLOB_DEBOUNCE):
    """
    RAMni saqlash navbatiga qo'yadi — FIRE-AND-FORGET.
    Handler HECH NARSANI kutmaydi (oldin await bilan disk yozishni
    kutayotgan edi — bu bosilishlar orasida 2-3 daqiqa lagga sabab bo'lardi).

      • Lokal fayl — LOCAL_DEBOUNCE soniyadan keyin fon rejimida yoziladi
      • JSONBlob  — `delay` soniyadan keyin fon rejimida yoziladi
      • Ikkalasi ham debounced: ketma-ket 10 ta o'zgarish — bir marta yozish.
    """
    global _jsonblob_timer_task, _local_timer_task
    DB_STATUS["pending_save"] = True

    # Lokal — debounced fon
    if _local_timer_task and not _local_timer_task.done():
        _local_timer_task.cancel()
    try:
        _local_timer_task = asyncio.create_task(_delayed_local_save(LOCAL_DEBOUNCE))
    except RuntimeError:
        # loop yo'q — sinxron kontekst
        threading.Thread(
            target=lambda: _save_local(RAM.to_dict()), daemon=True
        ).start()

    # JSONBlob — debounced fon
    if _jsonblob_timer_task and not _jsonblob_timer_task.done():
        _jsonblob_timer_task.cancel()
    try:
        _jsonblob_timer_task = asyncio.create_task(_delayed_jsonblob_save(delay))
    except RuntimeError:
        pass


async def save_sync():
    """
    Lokal + JSONBlob fon rejimida — TO'LIQ THREAD'da ishlaydi,
    shuning uchun callback/message handlerlar ichida chaqirilganda
    botning boshqa foydalanuvchilarga javob berishini TO'XTATMAYDI.
    (Oldin bu funksiya sinxron edi va katta RAM/JSON serialize+disk
    yozish operatsiyasi event loop'ni bloklab, "start" va tugmalarga
    javobni sekinlashtirardi.)
    """
    def _do():
        data = RAM.to_dict()
        _save_local(data)
        threading.Thread(target=_save_jsonblob, args=(copy.deepcopy(data),), daemon=True).start()
    await asyncio.to_thread(_do)


def save_sync_fallback():
    """
    Faqat event loop YO'Q bo'lgan sinxron kontekstlar uchun zaxira
    (masalan, register_user RuntimeError ushlaganda). Bu holatlarda
    asyncio.to_thread ishlatib bo'lmaydi, shuning uchun to'g'ridan-to'g'ri
    background thread'da ishga tushiramiz — chaqiruvchi kodni bloklamaydi.
    """
    def _do():
        data = RAM.to_dict()
        _save_local(data)
        threading.Thread(target=_save_jsonblob, args=(copy.deepcopy(data),), daemon=True).start()
    threading.Thread(target=_do, daemon=True).start()


async def save_now() -> bool:
    """
    DARHOL saqlash — kutilayotgan debounce taymerni bekor qiladi va
    JSONBlob ga shu lahzada yozadi. Muhim operatsiyalar uchun.
    """
    global _jsonblob_timer_task
    if _jsonblob_timer_task and not _jsonblob_timer_task.done():
        _jsonblob_timer_task.cancel()
    try:
        await asyncio.to_thread(_save_local, RAM.to_dict())
    except Exception as e:
        logger.error(f"Lokal saqlash xato: {e}")
    return await _do_jsonblob_save()


async def save_ram_only():
    """
    Faqat lokal faylga yozadi — JSONBlob ga TEGMAYDI.
    Qism (video) qo'shganda ishlatiladi: ko'p video ketma-ket
    yuborilsa, har biri uchun JSONBlob ga yozish shart emas.
    """
    try:
        await asyncio.to_thread(_save_local, RAM.to_dict())
    except Exception as e:
        logger.error(f"save_ram_only lokal xato: {e}")
    DB_STATUS["pending_save"] = True


