def _check_ffmpeg() -> bool:
    """ffmpeg o'rnatilganligini tekshiradi — har safar yangi tekshiruv."""
    for ffmpeg_path in ["ffmpeg", "/usr/bin/ffmpeg", "/usr/local/bin/ffmpeg"]:
        try:
            result = subprocess.run(
                [ffmpeg_path, "-version"], capture_output=True, timeout=5
            )
            if result.returncode == 0:
                logger.info(f"✅ ffmpeg topildi: {ffmpeg_path}")
                return True
        except Exception:
            continue
    try:
        r = subprocess.run(["which", "ffmpeg"], capture_output=True, timeout=3, text=True)
        if r.returncode == 0 and r.stdout.strip():
            logger.info(f"✅ ffmpeg (which): {r.stdout.strip()}")
            return True
    except Exception:
        pass
    logger.warning("❌ ffmpeg hech qaerda topilmadi!")
    return False


def _find_font() -> str:
    """Serverda mavjud fontni topadi."""
    candidates = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
        "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",
        "/usr/share/fonts/truetype/ubuntu/Ubuntu-B.ttf",
        "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
        "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
    ]
    for p in candidates:
        if os.path.exists(p):
            return p
    # Tizimdan birinchi .ttf faylni qidiramiz
    try:
        r = subprocess.run(
            ["find", "/usr/share/fonts", "-name", "*.ttf", "-type", "f"],
            capture_output=True, timeout=5, text=True
        )
        lines = [l.strip() for l in r.stdout.splitlines() if l.strip()]
        if lines:
            return lines[0]
    except Exception:
        pass
    return ""


def _probe_video_info(path: str):
    """ffprobe orqali video width/height/duration ni o'qiydi. Telegram native ko'rinishi uchun kerak."""
    try:
        r = subprocess.run(
            ["ffprobe", "-v", "error",
             "-select_streams", "v:0",
             "-show_entries", "stream=width,height:format=duration",
             "-of", "default=noprint_wrappers=1:nokey=0",
             path],
            capture_output=True, timeout=15, text=True,
        )
        w = h = 0
        d = 0
        for line in r.stdout.splitlines():
            if line.startswith("width="):
                try: w = int(line.split("=", 1)[1])
                except: pass
            elif line.startswith("height="):
                try: h = int(line.split("=", 1)[1])
                except: pass
            elif line.startswith("duration="):
                try: d = int(float(line.split("=", 1)[1]))
                except: pass
        return w, h, d
    except Exception as e:
        logger.warning(f"ffprobe xato: {e}")
        return 0, 0, 0


def _make_video_thumb(video_path: str):
    """Video uchun 1-soniyadan thumbnail yaratadi (Telegram preview uchun)."""
    try:
        fd, thumb_path = tempfile.mkstemp(suffix=".jpg", prefix="wm_thumb_")
        os.close(fd)
        r = subprocess.run(
            ["ffmpeg", "-y", "-hide_banner", "-loglevel", "error",
             "-ss", "1", "-i", video_path,
             "-frames:v", "1",
             "-vf", "scale='min(320,iw)':-2",
             "-q:v", "5",
             thumb_path],
            capture_output=True, timeout=20,
        )
        if r.returncode == 0 and os.path.exists(thumb_path) and os.path.getsize(thumb_path) > 100:
            return thumb_path
        try: os.unlink(thumb_path)
        except Exception: pass
        return None
    except Exception as e:
        logger.warning(f"thumb yaratishda xato: {e}")
        return None


# ═══════════════════════════════════════════════════════════
# PYROGRAM (MTProto) — 2GB gacha fayllarni yuklab olish uchun
# Cloud Bot API faqat 20MB gacha yuklab oladi. API_ID/API_HASH + bot_token bilan
# Pyrogram orqali to'g'ridan-to'g'ri Telegram MTProto'ga ulanamiz — 2GB gacha.
# ═══════════════════════════════════════════════════════════
_PYRO_CLIENT = None
_PYRO_LOCK = asyncio.Lock()
_PYRO_TRIED = False

async def _get_pyrogram_client():
    global _PYRO_CLIENT, _PYRO_TRIED
    if _PYRO_CLIENT is not None:
        return _PYRO_CLIENT
    async with _PYRO_LOCK:
        if _PYRO_CLIENT is not None:
            return _PYRO_CLIENT
        if _PYRO_TRIED:
            return None
        _PYRO_TRIED = True
        try:
            from pyrogram import Client  # type: ignore
        except Exception as e:
            logger.error(f"❌ pyrogram o'rnatilmagan: {e}. O'rnatish: pip install pyrogram tgcrypto")
            return None
        if not (API_ID and API_HASH and BOT_TOKEN):
            logger.error("❌ Pyrogram uchun API_ID/API_HASH/BOT_TOKEN to'liq emas")
            return None
        try:
            c = Client(
                name="wm_bot_dl",
                api_id=API_ID,
                api_hash=API_HASH,
                bot_token=BOT_TOKEN,
                in_memory=True,
                no_updates=True,
                workdir=tempfile.gettempdir(),
            )
            await c.start()
            _PYRO_CLIENT = c
            logger.info("✅ Pyrogram (MTProto) ulandi — 2GB gacha fayl yuklab olish mumkin")
            return _PYRO_CLIENT
        except Exception as e:
            logger.error(f"❌ Pyrogram ulanmadi: {e}")
            return None

async def _download_via_pyrogram(file_id: str, target_path: str, progress_cb=None):
    """Bot API file_id orqali MTProto'dan to'g'ridan-to'g'ri yuklab oladi (2GB gacha)."""
    cli = await _get_pyrogram_client()
    if not cli:
        return None
    try:
        kwargs = {"file_name": target_path}
        if progress_cb is not None:
            async def _pg(current, total):
                try:
                    pct = int(current / total * 100) if total else 0
                    if pct < 0: pct = 0
                    if pct > 100: pct = 100
                    res = progress_cb(pct)
                    if asyncio.iscoroutine(res):
                        await res
                except Exception:
                    pass
            kwargs["progress"] = _pg
        out = await cli.download_media(file_id, **kwargs)
        if out and os.path.exists(target_path) and os.path.getsize(target_path) > 1000:
            mb = os.path.getsize(target_path) // 1024 // 1024
            logger.info(f"✅ Pyrogram MTProto orqali yuklandi: {mb} MB → {target_path}")
            return target_path
        logger.error(f"Pyrogram yuklab oldi-yu, fayl bo'sh/yo'q: out={out}")
    except Exception as e:
        logger.error(f"❌ Pyrogram download xato: {e}")
    return None


async def _download_tg_file_safely(tg_file, target_path: str, file_id: str = ""):
    """
    Telegram'dan katta fayllarni xavfsiz yuklab oladi.
    1) Local Bot API rejimida — diskdan nusxa (lahzada)
    2) Oddiy Bot API yuklab olish (≤20MB cloud rejimida)
    3) Pyrogram MTProto fallback (20MB–2GB)
    """
    import shutil
    # 1) Local Bot API: tg_file.file_path — diskdagi absolute path bo'lishi mumkin
    try:
        local_path = getattr(tg_file, "file_path", None) or ""
        if local_path and isinstance(local_path, str):
            if os.path.isabs(local_path) and os.path.exists(local_path):
                try:
                    if os.path.exists(target_path):
                        os.unlink(target_path)
                    try:
                        os.link(local_path, target_path)
                    except Exception:
                        shutil.copyfile(local_path, target_path)
                    logger.info(f"✅ Local Bot API fayli: {local_path} ({os.path.getsize(target_path)//1024//1024} MB)")
                    return target_path
                except Exception as e:
                    logger.warning(f"Local nusxalash xato, HTTP ga o'tildi: {e}")
    except Exception as e:
        logger.warning(f"Local fayl tekshirish xato: {e}")

    # 2) Oddiy Bot API yuklab olish
    try:
        try:
            return await tg_file.download_to_drive(
                target_path,
                read_timeout=VIDEO_IO_TIMEOUT,
                write_timeout=VIDEO_IO_TIMEOUT,
                connect_timeout=VIDEO_IO_TIMEOUT,
                pool_timeout=VIDEO_IO_TIMEOUT,
            )
        except TypeError:
            return await tg_file.download_to_drive(target_path)
    except Exception as e:
        logger.warning(f"Bot API download xato ({e}) — Pyrogram MTProto'ga o'tiladi")

    # 3) Pyrogram fallback (>20MB fayllar uchun)
    fid = file_id or getattr(tg_file, "file_id", "") or ""
    if fid:
        out = await _download_via_pyrogram(fid, target_path)
        if out:
            return out
    raise RuntimeError("Faylni yuklab bo'lmadi: Bot API ham, Pyrogram ham muvaffaqiyatsiz")


def _compress_video_to_telegram_limit(input_path: str):
    """
    Telegram native video qilib yuborish uchun fayl juda katta bo'lsa siqadi,
    lekin video resolution/aspect ratio o'zgarmaydi. Ya'ni original video o'lchami saqlanadi.
    """
    tmp_paths = []
    try:
        original_size = os.path.getsize(input_path)
        if original_size <= TELEGRAM_SAFE_UPLOAD_LIMIT_BYTES:
            return input_path, None

        width, height, duration = _probe_video_info(input_path)
        duration = max(int(duration or 0), 1)
        logger.warning(
            f"Video {original_size // 1024 // 1024}MB — Telegram video rejimi uchun "
            f"siqiladi, resolution saqlanadi ({width}x{height}, {duration}s)"
        )

        def _encode_to_limit(mult: float):
            fd, tmp_path = tempfile.mkstemp(suffix=".mp4", prefix="wm_fit_")
            os.close(fd)
            tmp_paths.append(tmp_path)

            target_bits = int(TELEGRAM_SAFE_UPLOAD_LIMIT_BYTES * 8 * 0.90 * mult)
            total_bitrate = max(260_000, target_bits // duration)
            audio_bitrate = 96_000 if total_bitrate > 520_000 else 64_000
            video_bitrate = max(180_000, total_bitrate - audio_bitrate)

            cmd = [
                "ffmpeg", "-y",
                "-hide_banner", "-loglevel", "error",
                "-i", input_path,
                "-map", "0:v:0", "-map", "0:a?",
                "-c:v", "libx264",
                "-preset", "ultrafast",
                "-x264-params", "rc-lookahead=10:ref=1:bframes=0",
                "-b:v", str(video_bitrate),
                "-maxrate", str(int(video_bitrate * 1.12)),
                "-bufsize", str(int(video_bitrate * 2)),
                "-pix_fmt", "yuv420p",
                "-map_metadata", "0",
                "-c:a", "aac",
                "-b:a", str(audio_bitrate),
                "-movflags", "+faststart",
                tmp_path,
            ]
            result = subprocess.run(cmd, capture_output=True, timeout=WM_FFMPEG_TIMEOUT)
            if result.returncode != 0:
                err = result.stderr.decode("utf-8", errors="replace")
                logger.warning(f"Video limitga siqish xato: {err[:800]}")
                return None
            if not os.path.exists(tmp_path) or os.path.getsize(tmp_path) <= 1000:
                return None
            return tmp_path

        for mult in (1.0, 0.78, 0.58):
            candidate = _encode_to_limit(mult)
            if candidate and os.path.getsize(candidate) <= TELEGRAM_SAFE_UPLOAD_LIMIT_BYTES:
                for p in list(tmp_paths):
                    if p != candidate and os.path.exists(p):
                        try: os.unlink(p)
                        except Exception: pass
                logger.info(f"Video native rejimga tayyor: {os.path.getsize(candidate)//1024//1024}MB")
                return candidate, candidate

        logger.warning("Video limitga sig'madi — original fayl bilan send_video uriniladi")
        for p in tmp_paths:
            if os.path.exists(p):
                try: os.unlink(p)
                except Exception: pass
    except subprocess.TimeoutExpired:
        logger.warning(f"Video siqish: vaqt tugadi ({WM_FFMPEG_TIMEOUT} soniya)")
    except Exception as e:
        logger.warning(f"Video siqishda xato: {e}")
    return input_path, None


# ══════════════════════════════════════════════════════════
# 🗜 VIDEO HAJMINI KICHRAYTIRISH — Admin funksiyasi
# ══════════════════════════════════════════════════════════
# State: {uid: {"state": "wait_mb"|"wait_videos", "target_mb": int, "queue": [file_id,...], "processed": int, "total": int}}
_COMPRESS_SESSIONS: dict[int, dict] = {}
COMPRESS_MIN_VIDEOS = 2
COMPRESS_MAX_VIDEOS = 100

def _run_ffmpeg_with_progress(cmd: list, duration_s: float, progress_cb=None, timeout: int | None = None):
    """ffmpeg ni -progress pipe:1 bilan yuritadi va progress_cb(percent) ni 1..100 oralig'ida chaqiradi."""
    full = list(cmd)
    try:
        i = full.index("-i")
        full = full[:i] + ["-progress", "pipe:1", "-nostats"] + full[i:]
    except ValueError:
        full = full + ["-progress", "pipe:1", "-nostats"]
    proc = subprocess.Popen(full, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    last_pct = 0
    dur_us = max(1.0, float(duration_s or 1) * 1_000_000.0)
    try:
        if proc.stdout is not None:
            for raw in proc.stdout:
                line = raw.decode("utf-8", "replace").strip()
                if not line:
                    continue
                if line.startswith("out_time_ms=") or line.startswith("out_time_us="):
                    try:
                        us = int(line.split("=", 1)[1])
                        pct = int(us / dur_us * 100)
                        if pct < 1: pct = 1
                        if pct > 99: pct = 99
                        if pct != last_pct and progress_cb:
                            last_pct = pct
                            try: progress_cb(pct)
                            except Exception: pass
                    except Exception:
                        pass
                elif line.startswith("progress=end"):
                    if progress_cb:
                        try: progress_cb(100)
                        except Exception: pass
        try:
            proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            proc.kill()
            raise
        err = b""
        try:
            if proc.stderr is not None:
                err = proc.stderr.read() or b""
        except Exception:
            pass
        return proc.returncode, err
    finally:
        try:
            if proc.stdout: proc.stdout.close()
            if proc.stderr: proc.stderr.close()
        except Exception:
            pass


def _compress_video_to_target_mb(input_path: str, target_mb: int, progress_cb=None) -> tuple[str | None, str | None]:
    """
    Videoni berilgan target_mb (megabayt) gacha siqadi.
    2-pass encoding ishlatadi — aniq hajmga tushiradi.
    Agar birinchi urinishda ham katta bo'lsa, avtomatik qayta siqadi (3 urinish).
    Qaytaradi: (output_path, tmp_path_to_cleanup | None)
    """
    all_tmp = []
    try:
        original_size = os.path.getsize(input_path)
        # Telegram 50MB limitidan xavfsiz — 85% ni target sifatida ishlatamiz
        safe_target_mb = min(target_mb, 47)
        target_bytes = safe_target_mb * 1024 * 1024

        if original_size <= target_bytes:
            logger.info(f"Video allaqachon {original_size//1024//1024}MB — siqish shart emas")
            return input_path, None

        width, height, duration = _probe_video_info(input_path)
        duration = max(int(duration or 1), 1)
        logger.info(f"🗜 Video siqilmoqda: {original_size//1024//1024}MB → maqsad {safe_target_mb}MB "
                    f"({width}x{height}, {duration}s)")

        current_input = input_path
        last_tmp = None

        for attempt in range(1, 4):  # Max 3 urinish
            # Har urinishda 85% ni olish (container overhead uchun)
            attempt_target_bytes = int(target_bytes * (0.88 - attempt * 0.03))
            target_bits = int(attempt_target_bytes * 8)
            total_bitrate = max(150_000, target_bits // duration)
            audio_bitrate = 96_000 if total_bitrate < 500_000 else 128_000
            video_bitrate = max(100_000, total_bitrate - audio_bitrate)

            fd, tmp_path = tempfile.mkstemp(suffix=".mp4", prefix=f"compress_{attempt}_")
            os.close(fd)
            all_tmp.append(tmp_path)

            # 2-pass encoding — aniq hajmni kafolatlaydi
            pass_log_fd, pass_log = tempfile.mkstemp(prefix="ffpass_")
            os.close(pass_log_fd)
            all_tmp.append(pass_log + "-0.log")

            try:
                # Pass 1
                cmd_pass1 = [
                    "ffmpeg", "-y",
                    "-hide_banner", "-loglevel", "error",
                    "-i", current_input,
                    "-map", "0:v:0",
                    "-c:v", "libx264",
                    "-preset", "fast",
                    "-b:v", str(video_bitrate),
                    "-pass", "1",
                    "-passlogfile", pass_log,
                    "-an",
                    "-f", "null", "/dev/null",
                ]

                # Pass 2
                cmd_pass2 = [
                    "ffmpeg", "-y",
                    "-hide_banner", "-loglevel", "error",
                    "-i", current_input,
                    "-map", "0:v:0", "-map", "0:a?",
                    "-c:v", "libx264",
                    "-preset", "fast",
                    "-b:v", str(video_bitrate),
                    "-maxrate", str(int(video_bitrate * 1.2)),
                    "-bufsize", str(int(video_bitrate * 2)),
                    "-pass", "2",
                    "-passlogfile", pass_log,
                    "-pix_fmt", "yuv420p",
                    "-map_metadata", "0",
                    "-c:a", "aac",
                    "-b:a", str(audio_bitrate),
                    "-movflags", "+faststart",
                    tmp_path,
                ]
                def _p1(pct, _attempt=attempt):
                    if progress_cb:
                        try: progress_cb(int(pct * 0.4))
                        except Exception: pass
                rc1, _ = _run_ffmpeg_with_progress(cmd_pass1, duration, _p1, timeout=WM_FFMPEG_TIMEOUT)
                if rc1 != 0:
                    logger.warning(f"2-pass pass1 xato, 1-pass ga o'tamiz")
                    raise RuntimeError("pass1 failed")

                def _p2(pct):
                    if progress_cb:
                        try: progress_cb(40 + int(pct * 0.6))
                        except Exception: pass
                rc2, err2 = _run_ffmpeg_with_progress(cmd_pass2, duration, _p2, timeout=WM_FFMPEG_TIMEOUT)
                if rc2 != 0:
                    err = err2.decode("utf-8", errors="replace")
                    logger.error(f"🗜 ffmpeg pass2 xato: {err[:300]}")
                    raise RuntimeError("pass2 failed")

            except RuntimeError:
                # 2-pass o'tmasa — oddiy 1-pass
                cmd_simple = [
                    "ffmpeg", "-y",
                    "-hide_banner", "-loglevel", "error",
                    "-i", current_input,
                    "-map", "0:v:0", "-map", "0:a?",
                    "-c:v", "libx264",
                    "-preset", "fast",
                    "-b:v", str(video_bitrate),
                    "-maxrate", str(int(video_bitrate * 1.2)),
                    "-bufsize", str(int(video_bitrate * 2)),
                    "-pix_fmt", "yuv420p",
                    "-map_metadata", "0",
                    "-c:a", "aac",
                    "-b:a", str(audio_bitrate),
                    "-movflags", "+faststart",
                    tmp_path,
                ]
                rc_s, err_s = _run_ffmpeg_with_progress(cmd_simple, duration, progress_cb, timeout=WM_FFMPEG_TIMEOUT)
                if rc_s != 0:
                    err = err_s.decode("utf-8", errors="replace")
                    logger.error(f"🗜 ffmpeg simple xato: {err[:300]}")
                    return None, None

            if not os.path.exists(tmp_path) or os.path.getsize(tmp_path) <= 1000:
                return None, None

            out_size = os.path.getsize(tmp_path)
            out_mb = out_size // 1024 // 1024
            logger.info(f"🗜 Urinish {attempt}: {out_mb}MB (maqsad {safe_target_mb}MB)")

            if out_size <= target_bytes:
                logger.info(f"✅ Siqildi: {out_mb}MB (maqsad {safe_target_mb}MB)")
                last_tmp = tmp_path
                break
            else:
                logger.info(f"⚠️ Hali katta ({out_mb}MB), qayta siqilmoqda...")
                # Keyingi urinishda siqilgan faylni input sifatida ishlatamiz
                current_input = tmp_path
                last_tmp = tmp_path

        if last_tmp and os.path.exists(last_tmp):
            return last_tmp, last_tmp
        return None, None

    except subprocess.TimeoutExpired:
        logger.warning(f"🗜 Video siqish timeout ({WM_FFMPEG_TIMEOUT}s)")
        return None, None
    except Exception as e:
        logger.error(f"🗜 Video siqishda xato: {e}")
        return None, None
    finally:
        # pass log fayllarini tozalash
        for p in all_tmp:
            if p and os.path.exists(p) and p.endswith(".log"):
                try: os.unlink(p)
                except Exception: pass


async def _run_compress_queue(bot, uid: int):
    """Admin yuborgan videolarni navbat bilan siqib, o'ziga qaytaradi."""
    sess = _COMPRESS_SESSIONS.get(uid)
    if not sess:
        return
    queue = sess.get("queue", [])
    target_mb = sess.get("target_mb", 30)
    total = sess.get("total", len(queue))
    processed = sess.get("processed", 0)

    status_msg = None
    try:
        status_msg = await bot.send_message(
            uid,
            f"⏳ <b>Videolar hajmi kichraytirilmoqda...</b>\n"
            f"📦 Jami: <b>{total}</b> ta video\n"
            f"🎯 Maqsad: <b>{target_mb} MB</b>\n\n"
            f"🔄 Iltimos kuting...",
            parse_mode="HTML"
        )
    except Exception:
        pass

    loop = asyncio.get_event_loop()

    for idx, file_id in enumerate(queue, 1):
        sess["processed"] = processed + idx - 1

        # Progress state for this video
        progress_state = {"phase": "⬇️ Yuklanmoqda", "percent": 0, "last_edit": 0.0, "last_text": ""}

        def _bar(pct: int) -> str:
            pct = max(0, min(100, int(pct)))
            filled = pct // 10
            return "▰" * filled + "▱" * (10 - filled)

        async def _render_progress(force: bool = False):
            if not status_msg:
                return
            now = time.time()
            if not force and (now - progress_state["last_edit"]) < 1.5:
                return
            pct = progress_state["percent"]
            phase = progress_state["phase"]
            text = (
                f"⏳ <b>Videolar hajmi kichraytirilmoqda...</b>\n"
                f"📦 {idx}/{total} ta video\n"
                f"🎯 Maqsad: <b>{target_mb} MB</b>\n\n"
                f"{phase}\n"
                f"<code>{_bar(pct)}</code> <b>{pct}%</b>"
            )
            if text == progress_state["last_text"]:
                return
            progress_state["last_edit"] = now
            progress_state["last_text"] = text
            try:
                await bot.edit_message_text(
                    text,
                    chat_id=uid,
                    message_id=status_msg.message_id,
                    parse_mode="HTML",
                )
            except Exception:
                pass

        def _set_progress(phase: str, pct: int, force: bool = False):
            progress_state["phase"] = phase
            progress_state["percent"] = max(0, min(100, int(pct)))
            try:
                fut = asyncio.run_coroutine_threadsafe(_render_progress(force=force), loop)
                # Don't wait — fire and forget
                _ = fut
            except Exception:
                pass

        try:
            # Boshlanish — 0%
            progress_state["phase"] = "⬇️ Yuklanmoqda"
            progress_state["percent"] = 0
            await _render_progress(force=True)

            # Faylni yuklab olish — Pyrogram MTProto orqali 2GB gacha
            fd, dl_path = tempfile.mkstemp(suffix=".mp4", prefix="dl_compress_")
            os.close(fd)
            try:
                # Avval Pyrogram bilan yuklab ko'ramiz (500MB+ uchun ham ishlaydi)
                async def _dl_cb(pct):
                    progress_state["phase"] = "⬇️ Yuklanmoqda"
                    progress_state["percent"] = pct
                    await _render_progress()
                pyro_ok = await _download_via_pyrogram(file_id, dl_path, progress_cb=_dl_cb)
                if not pyro_ok or not os.path.exists(dl_path) or os.path.getsize(dl_path) < 1000:
                    # Pyrogram o'tmasa — oddiy bot API orqali urinib ko'ramiz
                    tg_file = await bot.get_file(file_id)
                    await _download_tg_file_safely(tg_file, dl_path, file_id)
                orig_size_mb = os.path.getsize(dl_path) // 1024 // 1024

                # Siqish
                _set_progress("🗜 Siqilmoqda", 0, force=True)
                def _cmp_cb(pct):
                    _set_progress("🗜 Siqilmoqda", pct)
                out_path, tmp_to_del = await asyncio.to_thread(
                    _compress_video_to_target_mb, dl_path, target_mb, _cmp_cb
                )
                if out_path:
                    new_size_mb = os.path.getsize(out_path) // 1024 // 1024
                    caption = (
                        f"✅ <b>Video #{idx}</b>\n"
                        f"📉 {orig_size_mb} MB → <b>{new_size_mb} MB</b>\n"
                        f"🎯 Maqsad: {target_mb} MB"
                    )
                    # Yuborish progress
                    progress_state["phase"] = "📤 Yuborilmoqda"
                    progress_state["percent"] = 0
                    await _render_progress(force=True)

                    async def _up_cb(pct):
                        progress_state["phase"] = "📤 Yuborilmoqda"
                        progress_state["percent"] = pct
                        await _render_progress()

                    # Faylni yuborish — avval Pyrogram (cheklovsiz), keyin Bot API
                    sent = await _send_video_via_pyrogram(uid, out_path, caption, progress_cb=_up_cb)
                    if not sent:
                        await _send_video_file_safely(
                            bot, uid, out_path, caption, pm="HTML"
                        )
                    # 100% ko'rsatish
                    progress_state["phase"] = "✅ Tayyor"
                    progress_state["percent"] = 100
                    await _render_progress(force=True)

                    if tmp_to_del and tmp_to_del != dl_path and os.path.exists(tmp_to_del):
                        try: os.unlink(tmp_to_del)
                        except Exception: pass
                else:
                    await bot.send_message(
                        uid,
                        f"⚠️ <b>Video #{idx}</b> — siqishda xato yuz berdi, o'tkazib yuborildi.",
                        parse_mode="HTML"
                    )
            finally:
                if os.path.exists(dl_path):
                    try: os.unlink(dl_path)
                    except Exception: pass

        except Exception as e:
            logger.error(f"_run_compress_queue #{idx}: {e}")
            try:
                await bot.send_message(
                    uid,
                    f"⚠️ <b>Video #{idx}</b> — yuklashda xato: {html.escape(str(e)[:100])}",
                    parse_mode="HTML"
                )
            except Exception:
                pass

        # Har video o'rtasida kichik pauza (flood oldini olish)
        await asyncio.sleep(1.5)

    # Tugadi
    _COMPRESS_SESSIONS.pop(uid, None)
    try:
        if status_msg:
            await bot.edit_message_text(
                f"✅ <b>Hammasi tayyor!</b>\n"
                f"📦 {total} ta video kichraytirildi.\n"
                f"🎯 Maqsad hajm: <b>{target_mb} MB</b>",
                chat_id=uid,
                message_id=status_msg.message_id,
                parse_mode="HTML"
            )
    except Exception:
        try:
            await bot.send_message(
                uid,
                f"✅ <b>Hammasi tayyor!</b> {total} ta video kichraytirildi.",
                parse_mode="HTML",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("⬅️ Admin panel", callback_data="go_admin_panel")
                ]])
            )
        except Exception:
            pass


async def _send_video_via_pyrogram(chat_id: int, video_path: str, caption: str, progress_cb=None) -> bool:
    """Pyrogram MTProto orqali video yuboradi — hajm cheklovsiz (2GB gacha)."""
    try:
        cli = await _get_pyrogram_client()
        if not cli:
            return False
        width, height, duration = _probe_video_info(video_path)
        thumb_path = _make_video_thumb(video_path)
        kw = {
            "chat_id": chat_id,
            "video": video_path,
            "caption": caption,
            "parse_mode": "html",
        }
        if width and height:
            kw["width"] = width
            kw["height"] = height
        if duration:
            kw["duration"] = int(duration)
        if thumb_path and os.path.exists(thumb_path):
            kw["thumb"] = thumb_path
        if progress_cb is not None:
            async def _pg(current, total):
                try:
                    pct = int(current / total * 100) if total else 0
                    if pct < 0: pct = 0
                    if pct > 100: pct = 100
                    res = progress_cb(pct)
                    if asyncio.iscoroutine(res):
                        await res
                except Exception:
                    pass
            kw["progress"] = _pg
        await cli.send_video(**kw)
        if thumb_path and os.path.exists(thumb_path):
            try: os.unlink(thumb_path)
            except: pass
        logger.info(f"✅ Pyrogram orqali video yuborildi: {video_path}")
        return True
    except Exception as e:
        logger.error(f"❌ Pyrogram send_video xato: {e}")
        return False



async def _send_video_file_safely(bot, chat_id: int, video_path: str, caption: str,
                                  markup=None, pm="HTML", protect=False):
    """Tayyor videoni Telegram'ga timeoutlarni uzaytirib, bir nechta fallback bilan yuboradi."""
    from telegram import InputFile
    from telegram.error import BadRequest, NetworkError, RetryAfter, TelegramError, TimedOut

    width, height, duration = _probe_video_info(video_path)
    thumb_path = _make_video_thumb(video_path)
    base_kw = {
        "chat_id": chat_id,
        "caption": caption,
        "parse_mode": pm,
    }
    if markup: base_kw["reply_markup"] = markup
    if protect: base_kw["protect_content"] = True
    if width and height:
        base_kw["width"] = width
        base_kw["height"] = height
    if duration:
        base_kw["duration"] = duration

    def _timeout_kw():
        return {
            "read_timeout": VIDEO_IO_TIMEOUT,
            "write_timeout": VIDEO_IO_TIMEOUT,
            "connect_timeout": VIDEO_IO_TIMEOUT,
            "pool_timeout": VIDEO_IO_TIMEOUT,
        }

    async def _try_send_video(use_thumb: bool, use_meta: bool):
        kw = dict(base_kw)
        if not use_meta:
            kw.pop("width", None)
            kw.pop("height", None)
            kw.pop("duration", None)
        kw.update(_timeout_kw())
        with open(video_path, "rb") as vf:
            kw["video"] = InputFile(vf, filename="video.mp4")
            if use_thumb and thumb_path and os.path.exists(thumb_path):
                with open(thumb_path, "rb") as th:
                    kw["thumbnail"] = InputFile(th, filename="thumb.jpg")
                    return await bot.send_video(**kw)
            return await bot.send_video(**kw)

    async def _try_send_document():
        kw = {
            "chat_id": chat_id,
            "caption": caption,
            "parse_mode": pm,
        }
        if markup: kw["reply_markup"] = markup
        if protect: kw["protect_content"] = True
        kw.update(_timeout_kw())
        with open(video_path, "rb") as vf:
            kw["document"] = InputFile(vf, filename="video.mp4")
            return await bot.send_document(**kw)

    last_error = None
    try:
        send_variants = [(True, True), (False, True), (False, False)]
        for attempt in range(1, 4):
            for use_thumb, use_meta in send_variants:
                try:
                    return await _try_send_video(use_thumb, use_meta)
                except TypeError:
                    with open(video_path, "rb") as vf:
                        kw = dict(base_kw)
                        if not use_meta:
                            kw.pop("width", None)
                            kw.pop("height", None)
                            kw.pop("duration", None)
                        kw["video"] = vf
                        return await bot.send_video(**kw)
                except RetryAfter as e:
                    last_error = e
                    logger.warning(f"send_video RetryAfter: {e.retry_after}s")
                    await asyncio.sleep(float(e.retry_after) + 1)
                except (TimedOut, NetworkError) as e:
                    last_error = e
                    logger.warning(f"send_video urinish {attempt}/3 tarmoq xatosi: {e}")
                    break
                except BadRequest as e:
                    last_error = e
                    err_str = str(e).lower()
                    if "file is too big" in err_str or "request entity too large" in err_str:
                        logger.error(f"send_video: fayl juda katta — Telegram qabul qilmayapti")
                        raise  # qayta urinish befoyda, darhol chiqamiz
                    logger.warning(f"send_video varianti o'tmadi (thumb={use_thumb}, meta={use_meta}): {e}")
                    continue
                except TelegramError as e:
                    last_error = e
                    logger.warning(f"send_video Telegram xato: {e}")
                    continue
            if attempt < 3:
                await asyncio.sleep(2 * attempt)

        if os.environ.get("ALLOW_DOCUMENT_FALLBACK", "0") == "1":
            logger.warning(f"send_video bo'lmadi, document fallback qilinadi: {last_error}")
            return await _try_send_document()
        logger.error(f"send_video bo'lmadi — document rejimga o'tkazilmadi: {last_error}")
        raise last_error or RuntimeError("send_video bo'lmadi")
    finally:
        if thumb_path and os.path.exists(thumb_path):
            try: os.unlink(thumb_path)
            except Exception: pass


async def _send_original_video_fallback(bot, chat_id: int, file_id: str, caption: str,
                                        markup=None, pm="HTML", protect=False,
                                        user_id=None, username: str = ""):
    """
    Fallback: ffmpeg watermark muvaffaqiyatsiz bo'lsa, video oddiy caption bilan ketadi.
    Caption'ga ID/username qo'shilmaydi — watermark faqat video ICHIDA suzib chiqishi kerak.
    """
    try:
        return await bot.send_video(
            chat_id=chat_id,
            video=file_id,
            caption=caption or "",
            parse_mode=pm,
            reply_markup=markup,
            protect_content=True,
            read_timeout=VIDEO_IO_TIMEOUT,
            write_timeout=VIDEO_IO_TIMEOUT,
            connect_timeout=VIDEO_IO_TIMEOUT,
            pool_timeout=VIDEO_IO_TIMEOUT,
        )
    except Exception as e:
        logger.error(f"original fallback send_video xato: {e}")
        try:
            return await sm(
                bot, chat_id,
                "⚠️ Video yuborishda muammo bo'ldi. Iltimos, biroz kutib qaytadan urinib ko'ring.",
                pm=pm,
            )
        except Exception as e2:
            logger.error(f"fallback notice xato: {e2}")
            return None


def _add_watermark_ffmpeg(input_path: str, output_path: str, user_id: str, username: str = "", phone: str = "", wm_custom_text: str = "", wm_color: str = "white") -> bool:
    """
    ffmpeg orqali videoga majburiy watermark qo'shadi.
    Watermark: custom matn (bo'lsa) yoki "O'g'irlash taqiqlanadi" + telefon + ID + username.
    """
    textfile_path = None
    try:
        safe_user_id = str(user_id or "").strip() or "Nomaʼlum"
        safe_username = str(username or "").strip().replace("\n", " ").replace("\r", " ")
        safe_username = safe_username[:32]
        if safe_username and not safe_username.startswith("@"):
            safe_username = "@" + safe_username
        if not safe_username or safe_username == "@":
            safe_username = "Username qo'yilmagan"

        safe_phone = str(phone or "").strip().replace("\n", " ").replace("\r", " ")[:16]
        if not safe_phone:
            safe_phone = "Tel: yo'q"
        elif not safe_phone.startswith("+"):
            safe_phone = "+" + safe_phone

        fd, textfile_path = tempfile.mkstemp(suffix=".txt", prefix="wm_txt_")
        os.close(fd)

        # Custom matn bo'lsa — uni ishlatamiz, aks holda standart
        if wm_custom_text and wm_custom_text.strip():
            wm_line = wm_custom_text.strip()[:80]
        else:
            wm_line = "O'g'irlash taqiqlanadi"

        # Rang tekshiruvi
        allowed_colors = {"white", "red", "yellow", "green", "blue", "orange", "cyan"}
        safe_color = wm_color if wm_color in allowed_colors else "white"

        with open(textfile_path, "w", encoding="utf-8") as tf:
            tf.write(
                f"{wm_line}\n"
                f"Tel: {safe_phone}\n"
                f"ID: {safe_user_id}\n"
                f"User: {safe_username}"
            )


        font_path = _find_font()
        font_opt = f":fontfile={font_path}" if font_path else ""

        # Watermark UZLUKSIZ silliq suzib yuradi (sin/cos asosida) — asosiy botdagidek.
        # Doim ko'rinadi, kichik o'lchamda, ekran bo'ylab oqib yuradi.
        x_expr = "(w-text_w-20)*(0.5+0.5*sin(2*PI*t/13))"
        y_expr = "(h-text_h-20)*(0.5+0.5*cos(2*PI*t/17))"

        vf_filter = (
            f"drawtext=textfile={textfile_path}"
            f"{font_opt}"
            f":fontsize=13"
            f":fontcolor={safe_color}@0.85"
            f":line_spacing=3"
            f":box=1:boxcolor=black@0.35:boxborderw=6"
            f":borderw=1:bordercolor=black@0.7"
            f":x='{x_expr}'"
            f":y='{y_expr}'"
        )

        # MAKSIMAL TEZLIK: ultrafast + zerolatency + CRF 28 + x264 tuning.
        # 20MB video ~5-15s da watermarklanadi (avval 10 daqiqa edi).
        # `-threads 2` — parallel encodelar bir-birini bo'g'ib qo'ymasligi uchun.
        attempts = [
            {"acodec": ["-c:a", "copy"], "label": "ultrafast+crf28+audio-copy"},
            {"acodec": ["-c:a", "aac", "-b:a", "128k"], "label": "ultrafast+crf28+audio-aac"},
        ]
        last_err = ""
        for idx, att in enumerate(attempts, start=1):
            cmd = [
                "ffmpeg", "-y",
                "-hide_banner", "-loglevel", "error",
                "-fflags", "+genpts",
                "-i", input_path,
                "-vf", vf_filter,
                "-map", "0:v:0", "-map", "0:a?",
                "-c:v", "libx264",
                "-preset", "ultrafast",
                "-tune", "zerolatency",
                "-crf", "28",
                "-x264-params", "ref=1:bframes=0:rc-lookahead=0:me=dia:subme=1:trellis=0:8x8dct=0:weightp=0:mixed-refs=0:aq-mode=0",
                "-threads", "2",
                "-pix_fmt", "yuv420p",
                "-map_metadata", "0",
                *att["acodec"],
                "-movflags", "+faststart",
                output_path,
            ]

            logger.info(f"ffmpeg watermark: urinish {idx}/{len(attempts)} ({att['label']})")
            try:
                result = subprocess.run(cmd, capture_output=True, timeout=WM_FFMPEG_TIMEOUT)
            except subprocess.TimeoutExpired:
                last_err = f"timeout ({WM_FFMPEG_TIMEOUT}s)"
                logger.warning(f"ffmpeg watermark urinish {idx}: vaqt tugadi")
                continue

            if result.returncode == 0 and os.path.exists(output_path) and os.path.getsize(output_path) > 1000:
                logger.info(f"ffmpeg watermark: muvaffaqiyatli ({os.path.getsize(output_path)//1024} KB, urinish {idx}: {att['label']})")
                return True

            last_err = result.stderr.decode("utf-8", errors="replace")[:800] if result.returncode != 0 else "output bo'sh"
            logger.warning(f"ffmpeg watermark urinish {idx} ({att['label']}) xato: {last_err[:300]}")

        logger.error(f"ffmpeg watermark: barcha urinishlar muvaffaqiyatsiz. Oxirgi: {last_err[:500]}")
        return False

    except Exception as e:
        logger.error(f"ffmpeg istisno: {e}")
        return False
    finally:
        if textfile_path and os.path.exists(textfile_path):
            try:
                os.unlink(textfile_path)
            except Exception:
                pass


# ─── Parallel watermark cheklovi (CPU tiqilmasin) ──────
# MUHIM: Railway/kichik serverlarda CPU 1-2 core bo'ladi. 24 ta parallel ffmpeg
# bir-birini bo'g'adi va har biri 10 daqiqa oladi. Default 2 ga tushirildi —
# har bir video tezroq tugaydi. Kuchli serverda WM_PARALLEL=4 yoki 6 qiling.
_WM_SEMAPHORE = asyncio.Semaphore(int(os.environ.get("WM_PARALLEL") or "2"))

# Watermarklangan videolarni cache qilamiz — bir xil (file_id, user_id) qayta ishlanmasin
_WM_CACHE: dict = {}
_WM_CACHE_MAX = 2000
_WM_VERSION = "popup_every_3s_native_video_v5"



WARN_PREFIX = ""  # Caption'ga matn qo'shilmaydi — watermark faqat video ICHIDA chiqadi

def _with_warn(caption: str) -> str:
    # Hech narsa qo'shmaymiz — caption qanday bo'lsa shunday qoldiramiz
    return caption or ""

_USER_VIDEO_LOCKS: dict = {}

def _get_user_video_lock(uid) -> asyncio.Lock:
    try:
        key = int(uid)
    except Exception:
        key = 0
    lk = _USER_VIDEO_LOCKS.get(key)
    if lk is None:
        lk = asyncio.Lock()
        _USER_VIDEO_LOCKS[key] = lk
    return lk


def _ffprobe_duration_seconds(path: str) -> float:
    """ffprobe orqali video davomiyligini (sekund) qaytaradi. Xato bo'lsa 0."""
    try:
        out = subprocess.run(
            [
                "ffprobe", "-v", "error",
                "-show_entries", "format=duration",
                "-of", "default=noprint_wrappers=1:nokey=1",
                path,
            ],
            capture_output=True, timeout=20,
        )
        if out.returncode == 0:
            return float((out.stdout or b"").decode("utf-8", errors="replace").strip() or "0")
    except Exception as e:
        logger.warning(f"ffprobe duration xato: {e}")
    return 0.0


# Watermark faqat qisqa videolar uchun (sekund). Default: 20 daqiqa.
WM_MAX_DURATION = int(os.environ.get("WM_MAX_DURATION") or str(20 * 60))
# Ehtimoliy 20-daqiqali video o'lchami uchun proksi (Pyrogram'siz get_file uchun chegara).
# 200 MB dan katta fayllarni umuman yuklab olmaymiz — to'g'ridan-to'g'ri original yuboramiz.
WM_MAX_BYTES = int(os.environ.get("WM_MAX_BYTES") or str(100 * 1024 * 1024))


def _get_ep_meta(movie: dict, file_id: str):
    """Upload paytida saqlangan video metadata (duration, size) ni qaytaradi.
    Topilmasa (0, 0) — eski qo'shilgan qismlar uchun."""
    try:
        meta = (movie or {}).get("episode_meta", {}) or {}
        info = meta.get(file_id) or {}
        return int(info.get("duration", 0) or 0), int(info.get("size", 0) or 0)
    except Exception:
        return 0, 0





async def sv_watermarked(bot, chat_id: int, file_id: str, caption: str,
                         user_id, username: str = "", markup=None, pm="HTML", protect=False, phone: str = "",
                         dur_hint: int = 0, size_hint: int = 0):
    """
    Videoni foydalanuvchiga yuboradi.
    Qoidalar:
      • Har bir foydalanuvchi uchun NAVBAT: bitta video tugamaguncha keyingisi yuborilmaydi.
      • Davomiyligi ≤ 20 daq bo'lgan videolarga ekranda suzib yuruvchi watermark
        (Tel + ID + Username) qo'shiladi.
      • Davomiyligi > 20 daq bo'lgan (yoki o'lchami juda katta) videolar
        watermarksiz, Telegram'ning o'z file_id orqali DARHOL yuboriladi
        (qayta yuklab olish/encoding YO'Q — Pyrogram MTProto bilan 2GB gacha).
      • dur_hint / size_hint berilsa (upload paytida saqlangan metadata) —
        katta/uzun videolar UMUMAN yuklab olinmasdan darhol yuboriladi (tez!).
    """
    # MAJBURIY: protect_content (faqat oddiy foydalanuvchilar uchun)
    # ── ADMIN BYPASS: adminga watermark VA protect_content QO'YILMAYDI ──
    try:
        if int(chat_id) == ADMIN_ID:
            return await bot.send_video(
                chat_id=chat_id, video=file_id, caption=caption,
                parse_mode=pm, reply_markup=markup,
                protect_content=False,
            )
    except Exception as _adm_e:
        logger.warning(f"sv_watermarked admin bypass xato: {_adm_e}")

    # ── BARCHA BOTLAR (parent + bola): watermark QO'YILMAYDI ──
    # Foydalanuvchi qism tugmasini bosgan zahoti video DARHOL, ichida
    # suzib yuruvchi yozuvsiz, Telegram'ning o'z file_id orqali yuboriladi.
    # (ffmpeg watermark bosqichi butunlay o'tkazib yuboriladi — tez!)
    try:
        return await bot.send_video(
            chat_id=chat_id, video=file_id, caption=caption,
            parse_mode=pm, reply_markup=markup,
            protect_content=bool(protect),
        )
    except Exception as _pe:
        logger.warning(f"sv_watermarked send_video xato: {_pe} — fallback")
        return await _send_original_video_fallback(
            bot, chat_id, file_id, caption,
            markup=markup, pm=pm, protect=bool(protect),
            user_id=user_id, username=username,
        )

    protect = True
    caption = _with_warn(caption)

    # ── TEZKOR QAROR: faqat O'LCHAM bo'yicha ──
    # FAQAT 100 MB dan KATTA videolar watermarksiz, darhol original file_id bilan yuboriladi.
    # 100 MB gacha bo'lgan BARCHA videolarga (davomiyligi qancha bo'lmasin)
    # ekranda suzib yuruvchi watermark (ID + Tel + Username) qo'shiladi.
    # size_hint berilgan bo'lsa — yuklab olmasdan tekshirish mumkin
    if size_hint and size_hint > WM_MAX_BYTES:
        _sh_mb = size_hint // 1024 // 1024
        logger.info(
            f"sv_watermarked: hint bo'yicha katta video "
            f"({_sh_mb} MB > 100 MB) — watermarksiz darhol yuboriladi"
        )
        return await _send_original_video_fallback(
            bot, chat_id, file_id, caption,
            markup=markup, pm=pm, protect=protect,
            user_id=user_id, username=username,
        )

    # Bitta foydalanuvchi: bir vaqtning o'zida BITTA video. Navbat bilan ishlaydi.
    user_lock = _get_user_video_lock(user_id) if user_id else None
    if user_lock is not None and user_lock.locked():
        # Foydalanuvchi avvalgi video tugashini kutadi — qisqa eslatma
        try:
            await bot.send_message(
                chat_id=chat_id,
                text="⏳ <b>Avvalgi video tugashini kuting...</b>\nNavbatga qo'shildingiz.",
                parse_mode="HTML",
            )
        except Exception:
            pass

    async def _run():
        return await _sv_watermarked_impl(
            bot, chat_id, file_id, caption,
            user_id=user_id, username=username, markup=markup, pm=pm,
            protect=protect, phone=phone,
        )

    if user_lock is None:
        return await _run()
    async with user_lock:
        return await _run()


async def _sv_watermarked_impl(bot, chat_id: int, file_id: str, caption: str,
                               user_id, username: str = "", markup=None, pm="HTML",
                               protect=True, phone: str = ""):
    # Phone yo'q bo'lsa — RAM dan olamiz
    if not phone and user_id:
        try:
            phone = (RAM.users.get(str(user_id), {}) or {}).get("phone", "") or ""
        except Exception:
            phone = ""

    # Cache: shu (file_id, user_id, JORIY rang+matn) avval ishlangan bo'lsa —
    # tayyor file_id bilan yuboramiz (tez!). Rang/matn o'zgarsa kalit ham
    # o'zgaradi — eski watermark qaytarilib qolmaydi.
    _wm_settings_sig = f"{RAM.settings.get('wm_custom_text') or ''}|{RAM.settings.get('wm_color') or 'white'}"
    cache_key = (_WM_VERSION, str(file_id), int(user_id) if user_id else 0, _wm_settings_sig)
    cached_fid = _WM_CACHE.get(cache_key)
    if cached_fid:
        try:
            return await bot.send_video(
                chat_id=chat_id, video=cached_fid, caption=caption,
                parse_mode=pm, reply_markup=markup, protect_content=True,
            )
        except Exception as ce:
            logger.warning(f"cache fid ishlamadi, qayta ishlanadi: {ce}")
            _WM_CACHE.pop(cache_key, None)

    # ── 1) O'lcham bo'yicha probe — 100 MB gacha watermark bilan, kattasi watermarksiz yuboriladi.
    _fsize = 0
    try:
        _probe = await asyncio.wait_for(bot.get_file(file_id), timeout=10)
        _fsize = int(getattr(_probe, "file_size", 0) or 0)
    except Exception:
        _probe = None

    # ── HAJM TEKSHIRUVI: 100 MB dan katta videolar watermarksiz original yuboriladi ──
    if _fsize and _fsize > WM_MAX_BYTES:
        _size_mb = _fsize // 1024 // 1024
        logger.info(f"sv_watermarked: video {_size_mb} MB > 100 MB — watermarksiz original yuboriladi")
        return await _send_original_video_fallback(
            bot, chat_id, file_id, caption,
            markup=markup, pm=pm, protect=protect,
            user_id=user_id, username=username,
        )

    if not _check_ffmpeg():
        logger.error("❌ ffmpeg topilmadi — watermarksiz original yuboriladi")
        return await _send_original_video_fallback(
            bot, chat_id, file_id, caption,
            markup=markup, pm=pm, protect=protect,
            user_id=user_id, username=username,
        )

    tmp_in = None
    tmp_out = None
    tmp_small = None

    # ── Progress animatsiyasi (1% → 100%) ─────────────────
    progress_msg = None
    progress_task = None
    try:
        progress_msg = await bot.send_message(
            chat_id=chat_id,
            text="📤 <b>Video yuborilmoqda...</b>\n\n▱▱▱▱▱▱▱▱▱▱  1%",
            parse_mode="HTML",
        )
    except Exception:
        progress_msg = None

    async def _animate_progress():
        if not progress_msg:
            return
        pct = 1
        try:
            while True:
                await asyncio.sleep(1.0)
                # Tezroq boshda, sekinroq 95% atrofida
                if pct < 60:
                    pct += 6
                elif pct < 85:
                    pct += 3
                elif pct < 95:
                    pct += 1
                if pct > 95:
                    pct = 95
                filled = int(pct / 10)
                bar = "▰" * filled + "▱" * (10 - filled)
                try:
                    await bot.edit_message_text(
                        chat_id=chat_id,
                        message_id=progress_msg.message_id,
                        text=f"📤 <b>Video yuborilmoqda...</b>\n\n{bar}  {pct}%",
                        parse_mode="HTML",
                    )
                except Exception:
                    pass
        except asyncio.CancelledError:
            return

    try:
        progress_task = asyncio.create_task(_animate_progress())
    except Exception:
        progress_task = None

    try:
        async def _do_watermark():
            nonlocal tmp_in, tmp_out, tmp_small

            fd_in, tmp_in = tempfile.mkstemp(suffix=".mp4", prefix="wm_in_")
            fd_out, tmp_out = tempfile.mkstemp(suffix=".mp4", prefix="wm_out_")
            os.close(fd_in)
            os.close(fd_out)

            # Bot API get_file 20MB dan katta fayllarda "file is too big" beradi.
            # Shu sababli try/except: muvaffaqiyatsiz bo'lsa, to'g'ridan-to'g'ri Pyrogram MTProto.
            tg_file = None
            try:
                tg_file = await bot.get_file(file_id)
            except Exception as ge:
                logger.warning(f"bot.get_file xato ({ge}) — Pyrogram MTProto ishlatiladi")

            if tg_file is not None:
                await _download_tg_file_safely(tg_file, tmp_in, file_id=file_id)
            else:
                # To'g'ridan-to'g'ri Pyrogram orqali (katta fayllar uchun)
                out = await _download_via_pyrogram(file_id, tmp_in)
                if not out:
                    raise RuntimeError("Katta video yuklab olinmadi (Pyrogram ham ishlamadi). API_ID/API_HASH tekshiring.")

            logger.info(f"Watermark: {str(file_id)[:20]}... yuklab olindi ({os.path.getsize(tmp_in)//1024//1024} MB)")

            # ── O'LCHAM tekshiruvi: yuklab olgandan keyin ham hajmni qayta tekshiramiz ──
            # (get_file da _fsize 0 bo'lib qolgan bo'lishi mumkin, diskdagi haqiqiy o'lchamni tekshiramiz)
            _disk_size = os.path.getsize(tmp_in) if tmp_in and os.path.exists(tmp_in) else 0
            if _disk_size and _disk_size > WM_MAX_BYTES:
                _disk_mb = _disk_size // 1024 // 1024
                logger.info(f"Video disk: {_disk_mb} MB > 100 MB — watermarksiz original yuboriladi")
                return await _send_original_video_fallback(
                    bot, chat_id, file_id, caption,
                    markup=markup, pm=pm, protect=protect,
                    user_id=user_id, username=username,
                )

            async with _WM_SEMAPHORE:
                _wm_custom = str(RAM.settings.get("wm_custom_text") or "")
                _wm_color  = str(RAM.settings.get("wm_color") or "white")
                success = await asyncio.to_thread(
                    _add_watermark_ffmpeg,
                    tmp_in,
                    tmp_out,
                    str(user_id),
                    str(username or ""),
                    str(phone or ""),
                    _wm_custom,
                    _wm_color,
                )


            if success and os.path.exists(tmp_out) and os.path.getsize(tmp_out) > 1000:
                send_path, tmp_small = await asyncio.to_thread(_compress_video_to_telegram_limit, tmp_out)
                msg = await _send_video_file_safely(
                    bot, chat_id, send_path, caption,
                    markup=markup, pm=pm, protect=protect,
                )
                try:
                    # Cache faqat native video file_id uchun: document file_id ni keyingi safar
                    # send_video sifatida yuborish xato berishi mumkin.
                    fid = getattr(getattr(msg, "video", None), "file_id", None)
                    if fid:
                        if len(_WM_CACHE) > _WM_CACHE_MAX:
                            _WM_CACHE.clear()
                        _WM_CACHE[cache_key] = fid
                except Exception:
                    pass
                return msg

            logger.error("Watermark qo'yilmadi — original video fallback yuboriladi (caption watermark bilan)")
            return await _send_original_video_fallback(
                bot, chat_id, file_id, caption,
                markup=markup, pm=pm, protect=protect,
                user_id=user_id, username=username,
            )

        return await asyncio.wait_for(_do_watermark(), timeout=WM_TOTAL_TIMEOUT)

    except asyncio.TimeoutError:
        logger.error(f"sv_watermarked: {WM_TOTAL_TIMEOUT}s timeout — original video fallback yuboriladi")
        try:
            return await _send_original_video_fallback(
                bot, chat_id, file_id, caption,
                markup=markup, pm=pm, protect=protect,
                user_id=user_id, username=username,
            )
        except Exception as fb_e:
            logger.error(f"original fallback ham xato: {fb_e}")
            return await sm(bot, chat_id, "❌ Video yuborishda xato. Qayta urinib ko'ring.", pm=pm)
    except Exception as e:
        logger.error(f"sv_watermarked xato: {e}")
        try:
            return await _send_original_video_fallback(
                bot, chat_id, file_id, caption,
                markup=markup, pm=pm, protect=protect,
                user_id=user_id, username=username,
            )
        except Exception as fb_e:
            logger.error(f"original fallback ham xato: {fb_e}")
            return await sm(bot, chat_id, "❌ Video yuborishda xato. Qayta urinib ko'ring.", pm=pm)
    finally:
        # Progress animatsiyasini to'xtatamiz va 100% ko'rsatib o'chiramiz
        if progress_task and not progress_task.done():
            progress_task.cancel()
            try:
                await progress_task
            except Exception:
                pass
        if progress_msg:
            try:
                await bot.edit_message_text(
                    chat_id=chat_id,
                    message_id=progress_msg.message_id,
                    text="📤 <b>Video yuborilmoqda...</b>\n\n▰▰▰▰▰▰▰▰▰▰  100%",
                    parse_mode="HTML",
                )
                await asyncio.sleep(0.4)
                await bot.delete_message(chat_id=chat_id, message_id=progress_msg.message_id)
            except Exception:
                pass

        for p in [tmp_in, tmp_out, tmp_small]:
            if p and os.path.exists(p):
                try:
                    os.unlink(p)
                except Exception:
                    pass

