def _strip_html(text: str) -> str:
    """HTML teglarini va rasmda koʻrinmaydigan emoji/unicode belgilarni olib tashlaydi."""
    text = re.sub(r'<[^>]+>', '', text or '')
    # Emoji va maxsus unicode belgilarni olib tashlaymiz (font ko'rsata olmaydi — toʻrtburchak chiqadi)
    text = re.sub(
        r'[\U0001F000-\U0001FFFF\U00002600-\U000027BF\U0000FE00-\U0000FE0F'
        r'\U00020000-\U0002FA1F\u200d\ufe0f\u200b-\u200f]+',
        '', text
    )
    return text.strip()

def generate_premium_users_image(premium_list: list) -> "BytesIO | None":
    """
    Premium foydalanuvchilar ro'yxatini chiroyli rasm sifatida qaytaradi.
    premium_list: [{uid, name, username, phone, until, days_left}, ...]
    """
    if not PIL_AVAILABLE:
        return None

    SCALE    = 2
    IMG_W    = 1400 * SCALE
    PAD_X    = 44   * SCALE
    TOP_PAD  = 24   * SCALE
    CARD_H   = 190  * SCALE
    GAP      = 18   * SCALE
    HEADER_H = 170  * SCALE
    FOOTER_H = 110  * SCALE

    BG_COLOR   = (245, 247, 255)
    GRID_COLOR = (210, 215, 235)
    HEADER_BG  = (75, 0, 130)       # to'q binafsha
    WHITE      = (255, 255, 255)
    TEXT_DARK  = (25, 30, 50)
    GOLD       = (212, 160, 0)
    GREEN      = (30, 140, 60)
    GRAY       = (120, 120, 140)
    ACCENT_COLORS = [
        (130, 0, 180), (0, 120, 200), (180, 60, 0),
        (0, 150, 100), (180, 0, 80),  (60, 60, 200),
    ]

    count = max(len(premium_list), 1)
    img_h = HEADER_H + TOP_PAD + count * (CARD_H + GAP) + FOOTER_H + 10
    img   = Image.new("RGB", (IMG_W, img_h), BG_COLOR)
    draw  = ImageDraw.Draw(img)

    font_paths_bold = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
        "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",
        "/usr/share/fonts/truetype/ubuntu/Ubuntu-B.ttf",
        "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
    ]
    font_paths_reg = [
        "/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
        "/usr/share/fonts/truetype/freefont/FreeSans.ttf",
        "/usr/share/fonts/truetype/ubuntu/Ubuntu-R.ttf",
        "/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
    ]
    def try_font(size, bold=True):
        paths = font_paths_bold if bold else font_paths_reg
        for p in paths:
            if os.path.exists(p):
                try: return ImageFont.truetype(p, size)
                except: continue
        try: return ImageFont.load_default(size=size)
        except TypeError: return ImageFont.load_default()

    fnt_header  = try_font(86 * SCALE)
    fnt_name    = try_font(64 * SCALE)
    fnt_sub     = try_font(46 * SCALE, bold=False)
    fnt_badge   = try_font(44 * SCALE)
    fnt_footer  = try_font(36 * SCALE, bold=False)

    # Grid
    for x in range(0, IMG_W, 50 * SCALE):
        draw.line([(x, 0), (x, img_h)], fill=GRID_COLOR, width=1)
    for y in range(0, img_h, 50 * SCALE):
        draw.line([(0, y), (IMG_W, y)], fill=GRID_COLOR, width=1)

    # Header
    draw.rectangle([(0, 0), (IMG_W, HEADER_H)], fill=HEADER_BG)
    h_text = f"PREMIUM FOYDALANUVCHILAR  ({len(premium_list)} ta)"
    try:
        hbb = draw.textbbox((0, 0), h_text, font=fnt_header)
        hx  = (IMG_W - (hbb[2] - hbb[0])) // 2
        hy  = (HEADER_H - (hbb[3] - hbb[1])) // 2
    except: hx, hy = PAD_X, 28 * SCALE
    draw.text((hx, hy), h_text, fill=GOLD, font=fnt_header)

    if not premium_list:
        # Bo'sh holatda
        draw.text((PAD_X, HEADER_H + 60*SCALE), "Premium foydalanuvchilar yo'q", fill=GRAY, font=fnt_name)
    else:
        for idx, u in enumerate(premium_list):
            y0  = HEADER_H + TOP_PAD + idx * (CARD_H + GAP)
            y1  = y0 + CARD_H
            x0  = PAD_X
            x1  = IMG_W - PAD_X
            col = ACCENT_COLORS[idx % len(ACCENT_COLORS)]

            # Card
            draw.rounded_rectangle([x0, y0, x1, y1], radius=20*SCALE, fill=WHITE, outline=col, width=4*SCALE)
            # Sol rang chizig'i
            draw.rounded_rectangle([x0, y0, x0+12*SCALE, y1], radius=6*SCALE, fill=col)

            # Raqam doirasi
            BADGE_SZ = 110 * SCALE
            bx0 = x0 + 28 * SCALE
            bx1 = bx0 + BADGE_SZ
            by0 = y0 + (CARD_H - BADGE_SZ) // 2
            by1 = by0 + BADGE_SZ
            draw.ellipse([bx0, by0, bx1, by1], fill=col)
            num_txt = str(idx + 1)
            try:
                nb  = draw.textbbox((0, 0), num_txt, font=fnt_name)
                nxc = bx0 + (BADGE_SZ - (nb[2] - nb[0])) // 2
                nyc = by0 + (BADGE_SZ - (nb[3] - nb[1])) // 2 - 3*SCALE
            except: nxc, nyc = bx0 + 30*SCALE, by0 + 25*SCALE
            draw.text((nxc, nyc), num_txt, fill=WHITE, font=fnt_name)

            tx = bx1 + 30 * SCALE

            # Ism
            name = str(u.get("name") or u.get("uid") or "?")
            if len(name) > 24: name = name[:22] + "…"
            draw.text((tx, y0 + 22*SCALE), name, fill=TEXT_DARK, font=fnt_name)

            # ID | Username
            uid_txt   = f"ID: {u.get('uid', '?')}"
            uname_txt = f"  @{u.get('username')}" if u.get("username") else ""
            phone_txt = f"  Tel: {u.get('phone')}" if u.get("phone") else ""
            line2 = uid_txt + uname_txt + phone_txt
            if len(line2) > 44: line2 = line2[:42] + "…"
            draw.text((tx, y0 + 82*SCALE), line2, fill=GRAY, font=fnt_sub)

            # Muddat
            days_left = int(u.get("days_left", 0))
            until_str = u.get("until_str", "")
            if days_left > 7:
                days_color = GREEN
            elif days_left > 0:
                days_color = (200, 100, 0)
            else:
                days_color = (180, 0, 0)
            badge_txt = f"Premium: {until_str}  ({days_left} kun qoldi)"
            draw.text((tx, y0 + 130*SCALE), badge_txt, fill=days_color, font=fnt_badge)

    # Footer
    fy = img_h - FOOTER_H
    draw.rectangle([(0, fy), (IMG_W, img_h)], fill=HEADER_BG)
    now_str = _tashkent_now_str() if "_tashkent_now_str" in dir() else ""
    f_text = f"DramlarUz Bot  |  {now_str}  |  Jami: {len(premium_list)} ta premium"
    try:
        fbb = draw.textbbox((0, 0), f_text, font=fnt_footer)
        fx  = (IMG_W - (fbb[2] - fbb[0])) // 2
        fy2 = fy + (FOOTER_H - (fbb[3] - fbb[1])) // 2
    except: fx, fy2 = PAD_X, fy + 16*SCALE
    draw.text((fx, fy2), f_text, fill=GOLD, font=fnt_footer)

    buf = BytesIO()
    buf.name = f"premium_users_{int(time.time())}.png"
    img.save(buf, format="PNG", optimize=False, compress_level=1)
    buf.seek(0)
    return buf


PHOTO_PAGE_SIZE  = 20
KINO_LIST_PAGE_SIZE = 10


def generate_movies_image(movie_slice: list, page: int = 1, total_pages: int = 1,
                          total_count: int = 0, start_offset: int = 0) -> BytesIO | None:
    if not PIL_AVAILABLE or not movie_slice:
        return None

    BG_COLOR    = (250, 250, 252)
    GRID_COLOR  = (208, 213, 228)
    HEADER_BG   = (20, 60, 160)
    WHITE       = (255, 255, 255)
    TEXT_DARK   = (28, 33, 52)
    CODE_COLOR  = (60, 90, 190)
    VIEWS_COLOR = (40, 140, 70)
    EP_COLOR    = (100, 100, 130)
    ACCENT_COLORS = [
        (25, 95, 215), (40, 160, 70), (200, 50, 60),
        (200, 120, 0), (110, 60, 190), (0, 140, 180),
    ]
    # 4K sifat — kenglik 2160px (4K vertikal). Yozuvlar yirik va tiniq.
    SCALE    = 2
    IMG_W    = 1080 * SCALE   # 2160px
    PAD_X    = 40   * SCALE
    TOP_PAD  = 24   * SCALE
    CARD_H   = 170  * SCALE
    GAP      = 20   * SCALE
    HEADER_H = 160  * SCALE
    FOOTER_H = 100  * SCALE
    BADGE_SZ = 120  * SCALE
    GRID_STP = 50   * SCALE

    img_h = HEADER_H + TOP_PAD + len(movie_slice) * (CARD_H + GAP) + FOOTER_H + 10
    img  = Image.new("RGB", (IMG_W, img_h), BG_COLOR)
    draw = ImageDraw.Draw(img)

    font_paths_bold = [
        "/usr/share/fonts/truetype/google-fonts/Poppins-Bold.ttf",
        "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
        "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf",
        "/usr/share/fonts/truetype/freefont/FreeSansBold.ttf",
        "/usr/share/fonts/truetype/ubuntu/Ubuntu-B.ttf",
        "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf",
    ]
    def try_font(size):
        for p in font_paths_bold:
            if os.path.exists(p):
                try: return ImageFont.truetype(p, size)
                except: continue
        # Fontlar topilmasa: yangi PIL'da load_default(size=...) ishlaydi
        try:
            return ImageFont.load_default(size=size)
        except TypeError:
            return ImageFont.load_default()

    fnt_header = try_font(72 * SCALE)
    fnt_num    = try_font(54 * SCALE)
    fnt_title  = try_font(46 * SCALE)
    fnt_sub    = try_font(34 * SCALE)
    fnt_footer = try_font(38 * SCALE)

    for x in range(0, IMG_W, GRID_STP):
        draw.line([(x, 0), (x, img_h)], fill=GRID_COLOR, width=1)
    for y in range(0, img_h, GRID_STP):
        draw.line([(0, y), (IMG_W, y)], fill=GRID_COLOR, width=1)

    draw.rectangle([(0, 0), (IMG_W, HEADER_H)], fill=HEADER_BG)
    h_text = "BARCHA KINOLAR"
    try:
        hbb = draw.textbbox((0, 0), h_text, font=fnt_header)
        hx  = (IMG_W - (hbb[2] - hbb[0])) // 2
        hy  = (HEADER_H - (hbb[3] - hbb[1])) // 2
    except: hx, hy = 40, 28
    draw.text((hx, hy), h_text, fill=WHITE, font=fnt_header)

    for idx, (code, movie) in enumerate(movie_slice):
        y0 = HEADER_H + TOP_PAD + idx * (CARD_H + GAP)
        y1 = y0 + CARD_H
        x0 = PAD_X
        x1 = IMG_W - PAD_X
        col = ACCENT_COLORS[idx % len(ACCENT_COLORS)]
        draw.rounded_rectangle([x0, y0, x1, y1], radius=20*SCALE, fill=WHITE, outline=col, width=5*SCALE)
        draw.rounded_rectangle([x0, y0, x0 + 14*SCALE, y1], radius=7*SCALE, fill=col)
        bx0 = x0 + 32*SCALE
        bx1 = bx0 + BADGE_SZ
        by0 = y0 + (CARD_H - BADGE_SZ) // 2
        by1 = by0 + BADGE_SZ
        draw.ellipse([bx0, by0, bx1, by1], fill=col)
        num_txt = str(start_offset + idx + 1)
        try:
            nb  = draw.textbbox((0, 0), num_txt, font=fnt_num)
            nxc = bx0 + (BADGE_SZ - (nb[2] - nb[0])) // 2
            nyc = by0 + (BADGE_SZ - (nb[3] - nb[1])) // 2 - 4*SCALE
        except: nxc, nyc = bx0 + 30, by0 + 25
        draw.text((nxc, nyc), num_txt, fill=WHITE, font=fnt_num)
        tx = bx1 + 32*SCALE
        raw_title = _strip_html(movie.get("title", code))
        if len(raw_title) > 40: raw_title = raw_title[:38] + "…"
        title_y = y0 + 28*SCALE
        draw.text((tx, title_y), raw_title, fill=TEXT_DARK, font=fnt_title)
        ep_count    = len(movie.get("episodes", []))
        views_total = sum(movie.get("views", {}).values())
        sub_y = y0 + 100*SCALE
        code_part  = f"Kod: {code}"
        ep_part    = f"  |  {ep_count} ta qism mavjud"
        views_part = f"  |  {views_total} korilgan"
        draw.text((tx, sub_y), code_part, fill=CODE_COLOR, font=fnt_sub)
        try:
            cb = draw.textbbox((0, 0), code_part, font=fnt_sub)
            ex = tx + (cb[2] - cb[0])
        except: ex = tx + 200
        draw.text((ex, sub_y), ep_part, fill=EP_COLOR, font=fnt_sub)
        try:
            eb = draw.textbbox((0, 0), ep_part, font=fnt_sub)
            vx = ex + (eb[2] - eb[0])
        except: vx = ex + 160
        draw.text((vx, sub_y), views_part, fill=VIEWS_COLOR, font=fnt_sub)

    fy = img_h - FOOTER_H
    draw.rectangle([(0, fy), (IMG_W, img_h)], fill=HEADER_BG)
    if total_pages > 1:
        start_n = (page - 1) * KINO_LIST_PAGE_SIZE + 1
        end_n   = start_n + len(movie_slice) - 1
        f_text  = f"{start_n}-{end_n} ko'rsatildi  |  Jami: {total_count} ta  |  Kino kodini yuboring!"
    else:
        f_text = f"Jami: {total_count} ta kino  |  Kino kodini yuboring!"
    try:
        fbb = draw.textbbox((0, 0), f_text, font=fnt_footer)
        fx  = (IMG_W - (fbb[2] - fbb[0])) // 2
        fy2 = fy + (FOOTER_H - (fbb[3] - fbb[1])) // 2
    except: fx, fy2 = 40, fy + 16
    draw.text((fx, fy2), f_text, fill=WHITE, font=fnt_footer)

    buf = BytesIO()
    buf.name = f"kinolar_{int(time.time())}.png"
    img.save(buf, format="PNG", optimize=False, compress_level=1)
    buf.seek(0)
    return buf


