# ══════════════════════════════════════════════════════════
# ADMIN STATE HANDLER
# ══════════════════════════════════════════════════════════

async def admin_state_handler(update, context, text: str) -> bool:
    state = context.user_data.get("admin_state")
    uid   = update.effective_user.id
    if not state: return False

    if state == "broadcast_msg":
        bc = {
            "type": "copy",
            "from_chat_id": update.message.chat_id,
            "message_id": update.message.message_id,
            "buttons": [],
        }
        context.user_data["bc_msg"] = bc
        context.user_data.pop("admin_state", None)
        await sm(context.bot, uid, "✅ Xabar qabul qilindi.\n\n<b>Tugmali xabar yuborasizmi?</b>",
                 markup=bc_yesno_kb())
        return True

    if state == "set_referral_price":
        if not text.strip().isdigit() or int(text.strip()) <= 0:
            await sm(context.bot, uid, "❌ Faqat musbat <b>raqam</b> kiriting (masalan: 200):")
            return True
        amount = int(text.strip())
        RAM.settings["referral_amount"] = amount
        await save_now()
        context.user_data.pop("admin_state", None)
        await sm(context.bot, uid,
            f"✅ <b>Referral narxi yangilandi!</b>\n\n"
            f"🎁 Yangi referral mukofoti: <b>{amount:,} so'm</b>",
            admin_menu_kb(uid))
        return True

    if state == "set_withdraw_min":
        digits = re.sub(r"\D", "", text)
        if not digits or int(digits) < 1000:
            await sm(context.bot, uid,
                "❌ Faqat raqam kiriting (minimal 1 000 so'm). Masalan: <code>50000</code>")
            return True
        amt = int(digits)
        ok = set_withdraw_min(amt)
        if not ok:
            context.user_data.pop("admin_state", None)
            await sm(context.bot, uid, "❌ Saqlashda xato yuz berdi.", admin_menu_kb(uid))
            return True
        # 2-qadam: komissiya foizini so'raymiz
        context.user_data["admin_state"] = "set_withdraw_pct"
        context.user_data["_wd_new_min"] = amt
        cur_pct = get_withdraw_pct()
        await sm(context.bot, uid,
            f"✅ Minimalka saqlandi: <b>{amt:,} so'm</b>\n\n"
            f"2-qadam — endi <b>komissiya foizini</b> kiriting (0 dan 50 gacha).\n"
            f"Hozirgi qiymat: <b>{cur_pct}%</b>\n\n"
            f"Masalan: <code>5</code> — 5% komissiya\n"
            f"Yoki <code>0</code> — komissiyasiz.")
        return True

    if state == "set_withdraw_pct":
        digits = re.sub(r"\D", "", text)
        if digits == "":
            await sm(context.bot, uid, "❌ Faqat raqam kiriting (0 dan 50 gacha). Masalan: <code>5</code>")
            return True
        pct = int(digits)
        if pct < 0 or pct > 50:
            await sm(context.bot, uid, "❌ Foiz 0 dan 50 gacha bo'lishi kerak. Qaytadan kiriting:")
            return True
        ok = set_withdraw_pct(pct)
        amt = int(context.user_data.pop("_wd_new_min", 0) or get_withdraw_min())
        context.user_data.pop("admin_state", None)
        if ok:
            await sm(context.bot, uid,
                f"✅ <b>Sozlamalar yangilandi!</b>\n\n"
                f"💸 Minimalka: <b>{amt:,} so'm</b>\n"
                f"📉 Komissiya: <b>{pct}%</b>\n\n"
                f"<i>Asosiy bot va barcha bola-botlar (kino, VIP…) shu qiymatlarni ishlatadi.</i>",
                admin_menu_kb(uid))
        else:
            await sm(context.bot, uid, "❌ Foizni saqlashda xato yuz berdi.", admin_menu_kb(uid))
        return True



    # ─── Bot muddatini uzaytirish — TARIF qo'shish/tahrirlash ───────────
    if state in ("factory_tariff_new_label", "factory_tariff_edit_label"):
        buf = context.user_data.setdefault("factory_tariff_buf", {})
        is_edit = (state == "factory_tariff_edit_label")
        idx = context.user_data.get("factory_tariff_idx")
        _bt = context.user_data.get("factory_tariff_bt") or "kino"
        _lst = get_tariffs_for(_bt)
        val = text.strip()
        if is_edit and val == "-":
            try:
                buf["label"] = str(_lst[idx]["label"])
            except Exception:
                buf["label"] = val or "Tarif"
        else:
            if not val:
                await sm(context.bot, uid, "❌ Nom bo'sh bo'lmasin. Yana kiriting:")
                return True
            buf["label"] = val[:30]
        context.user_data["admin_state"] = (
            "factory_tariff_edit_days" if is_edit else "factory_tariff_new_days"
        )
        await sm(context.bot, uid,
                 "2/3 — Tarif <b>muddatini (kun)</b> kiriting (masalan: <code>60</code>):"
                 + ("\n<i>Eski qiymat uchun</i> <code>-</code>" if is_edit else ""))
        return True

    if state in ("factory_tariff_new_days", "factory_tariff_edit_days"):
        buf = context.user_data.setdefault("factory_tariff_buf", {})
        is_edit = (state == "factory_tariff_edit_days")
        idx = context.user_data.get("factory_tariff_idx")
        _bt = context.user_data.get("factory_tariff_bt") or "kino"
        _lst = get_tariffs_for(_bt)
        val = text.strip()
        if is_edit and val == "-":
            try:
                buf["days"] = int(_lst[idx]["days"])
            except Exception:
                await sm(context.bot, uid, "❌ Musbat butun son kiriting:")
                return True
        else:
            if not val.isdigit() or int(val) <= 0:
                await sm(context.bot, uid, "❌ Musbat butun son kiriting (kun):")
                return True
            buf["days"] = int(val)
        context.user_data["admin_state"] = (
            "factory_tariff_edit_price" if is_edit else "factory_tariff_new_price"
        )
        await sm(context.bot, uid,
                 "3/3 — Tarif <b>narxini (so'm)</b> kiriting (masalan: <code>180000</code>):"
                 + ("\n<i>Eski qiymat uchun</i> <code>-</code>" if is_edit else ""))
        return True

    if state in ("factory_tariff_new_price", "factory_tariff_edit_price"):
        buf = context.user_data.setdefault("factory_tariff_buf", {})
        is_edit = (state == "factory_tariff_edit_price")
        idx = context.user_data.get("factory_tariff_idx")
        _bt = context.user_data.get("factory_tariff_bt") or "kino"
        _lst = get_tariffs_for(_bt)
        val = text.strip().replace(" ", "").replace("'", "")
        if is_edit and val == "-":
            try:
                buf["price"] = int(_lst[idx]["price"])
            except Exception:
                await sm(context.bot, uid, "❌ Musbat butun son kiriting:")
                return True
        else:
            if not val.isdigit() or int(val) <= 0:
                await sm(context.bot, uid, "❌ Musbat butun son kiriting (so'm):")
                return True
            buf["price"] = int(val)
        new_t = {
            "label": str(buf.get("label") or f"{int(buf['days'])} kun"),
            "days":  int(buf["days"]),
            "price": int(buf["price"]),
        }
        if is_edit and isinstance(idx, int) and 0 <= idx < len(_lst):
            _lst[idx] = new_t
            msg = "✅ <b>Tarif yangilandi!</b>"
        else:
            _lst.append(new_t)
            _lst.sort(key=lambda x: int(x.get("days", 0)))
            msg = "✅ <b>Yangi tarif qo'shildi!</b>"
        save_extend_tariffs(BOT_EXTEND_TARIFFS)
        for k in ("admin_state", "factory_tariff_buf", "factory_tariff_idx", "factory_tariff_bt"):
            context.user_data.pop(k, None)
        await sm(context.bot, uid,
                 f"{msg}  ({FACTORY_BOT_TYPE_LABELS.get(_bt, _bt)})\n\n"
                 f"📅 <b>{html.escape(new_t['label'])}</b>\n"
                 f"⏱ {new_t['days']} kun  ·  💵 {new_t['price']:,} so'm".replace(",", " "))
        await factory_send_tariffs_admin(context.bot, uid, None, _bt)
        return True

    # ─── Botlarni kunini uzaytirish/kamaytirish (admin, ID bo'yicha) ─────
    if state == "factory_setdays_id":
        val = text.strip().lstrip("#")
        if not val.isdigit():
            await sm(context.bot, uid, "❌ Faqat bot <b>ID</b> raqamini kiriting (masalan: <code>12</code>):")
            return True
        bid = int(val)
        row = factory_db_get(bid)
        if not row:
            await sm(context.bot, uid, f"❌ <code>{bid}</code> ID li bot topilmadi. Qayta kiriting:")
            return True
        context.user_data["factory_setdays_bid"] = bid
        context.user_data["admin_state"] = "factory_setdays_days"
        exp_txt = factory_fmt_dt(row.get("expires_at"))
        await sm(context.bot, uid,
                 f"🤖 <b>@{html.escape(str(row.get('bot_username') or bid))}</b>\n"
                 f"⏳ Joriy muddat: <code>{exp_txt}</code> (Toshkent)\n\n"
                 "2/2 — Necha <b>kun qo'shish</b> (musbat son) yoki "
                 "<b>ayirish</b> (manfiy son) kerakligini kiriting:\n"
                 "<i>Masalan: <code>5</code> — 5 kun qo'shadi · <code>-3</code> — 3 kun ayiradi</i>",
                 ikb([[ibtn("❌ Bekor qilish", data="factory_admin_list")]]))
        return True

    if state == "factory_setdays_days":
        bid = context.user_data.get("factory_setdays_bid")
        row = factory_db_get(bid) if bid else None
        if not row:
            clear_admin_state(context)
            await sm(context.bot, uid, "❌ Bot topilmadi. Qaytadan boshlang.", admin_menu_kb(uid))
            return True
        val = text.strip().replace(" ", "")
        try:
            days = int(val)
        except Exception:
            await sm(context.bot, uid, "❌ Faqat butun son kiriting (masalan: <code>5</code> yoki <code>-3</code>):")
            return True
        if days == 0:
            await sm(context.bot, uid, "❌ <code>0</code> kiritib bo'lmaydi. Qayta kiriting:")
            return True
        new_exp = factory_db_admin_adjust_days(bid, days)
        # Yangi muddatga qarab holatni moslaymiz: kelajakda bo'lsa — yoqamiz/ishga tushuramiz,
        # hozir/o'tmishda bo'lsa — to'xtatib 'expired' belgilaymiz.
        try:
            row2 = factory_db_get(bid)
            if row2:
                still_valid = (new_exp is not None) and not factory_is_expired(row2)
                if still_valid:
                    if row2["status"] != "active":
                        factory_db_set_status(bid, "active")
                        row2 = factory_db_get(bid)
                    p_running = _factory_is_running(bid)
                    if not p_running:
                        factory_spawn(row2)
                elif row2["status"] == "active":
                    factory_db_set_status(bid, "expired")
                    factory_stop(bid)
        except Exception as e:
            logger.error(f"factory_setdays_days spawn/stop: {e}")
        clear_admin_state(context)
        exp_txt = factory_fmt_dt(new_exp)
        sign_txt = f"+{days}" if days > 0 else str(days)
        await sm(context.bot, uid,
                 f"✅ <b>Muddat yangilandi!</b>\n\n"
                 f"🤖 <b>@{html.escape(str(row.get('bot_username') or bid))}</b>\n"
                 f"📅 O'zgarish: <b>{sign_txt} kun</b>\n"
                 f"⏳ Yangi muddat: <code>{exp_txt}</code> (Toshkent)")
        await factory_send_admin_list(context.bot, uid)
        return True

    # ─── Bot yaratish narxini o'zgartirish (text holati) ─────────────────────
    if state == "factory_set_create_price":
        global BOT_CREATE_PRICE
        val = text.strip().replace(" ", "").replace("'", "")
        if not val.isdigit():
            await sm(context.bot, uid, "❌ Faqat musbat butun son kiriting (so'm), masalan: <code>200000</code>\n"
                                       "Tekin qilish uchun <code>0</code> kiriting:")
            return True
        new_price = int(val)
        BOT_CREATE_PRICE = new_price
        save_create_price(new_price)
        await _set_factory_price_setting("factory_create_price", new_price)
        clear_admin_state(context)
        if new_price == 0:
            price_txt = "🎁 <b>TEKIN</b> (0 so'm)"
        else:
            price_txt = f"<b>{new_price:,} so'm</b>".replace(",", " ")
        await sm(context.bot, uid,
                 f"✅ <b>Bot yaratish narxi yangilandi!</b>\n\n"
                 f"🏷 Yangi narx: {price_txt}",
                 ikb([[ibtn("⬅️ Botlarni boshqarish", data="factory_admin_list")]]))
        return True

    # ─── VIP kanal bot yaratish narxini o'zgartirish (text holati) ───────────
    if state == "factory_set_vip_price":
        global VIP_CREATE_PRICE
        val = text.strip().replace(" ", "").replace("'", "")
        if not val.isdigit():
            await sm(context.bot, uid, "❌ Faqat musbat butun son kiriting (so'm), masalan: <code>50000</code>\n"
                                       "Tekin qilish uchun <code>0</code> kiriting:")
            return True
        new_price = int(val)
        VIP_CREATE_PRICE = new_price
        save_vip_create_price(new_price)
        await _set_factory_price_setting("factory_vip_create_price", new_price)
        clear_admin_state(context)
        if new_price == 0:
            price_txt = "🎁 <b>TEKIN</b> (0 so'm)"
        else:
            price_txt = f"<b>{new_price:,} so'm</b>".replace(",", " ")
        await sm(context.bot, uid,
                 f"✅ <b>VIP kanal bot yaratish narxi yangilandi!</b>\n\n"
                 f"🏷 Yangi narx: {price_txt}",
                 ikb([[ibtn("⬅️ Botlarni boshqarish", data="factory_admin_list")]]))
        return True

    # ─── Yulduz bot yaratish narxini o'zgartirish (text holati) ──────────────
    if state == "factory_set_yulduz_price":
        global YULDUZ_CREATE_PRICE
        val = text.strip().replace(" ", "").replace("'", "")
        if not val.isdigit():
            await sm(context.bot, uid, "❌ Faqat musbat butun son kiriting (so'm), masalan: <code>150000</code>\n"
                                       "Tekin qilish uchun <code>0</code> kiriting:")
            return True
        new_price = int(val)
        YULDUZ_CREATE_PRICE = new_price
        save_yulduz_create_price(new_price)
        await _set_factory_price_setting("factory_yulduz_create_price", new_price)
        clear_admin_state(context)
        if new_price == 0:
            price_txt = "🎁 <b>TEKIN</b> (0 so'm)"
        else:
            price_txt = f"<b>{new_price:,} so'm</b>".replace(",", " ")
        await sm(context.bot, uid,
                 f"✅ <b>Yulduz bot yaratish narxi yangilandi!</b>\n\n"
                 f"🏷 Yangi narx: {price_txt}",
                 ikb([[ibtn("⬅️ Botlarni boshqarish", data="factory_admin_list")]]))
        return True

    # ─── Openbudget bot yaratish narxini o'zgartirish (text holati) ───────────
    if state == "factory_set_openbudget_price":
        global OPENBUDGET_CREATE_PRICE
        val = text.strip().replace(" ", "").replace("'", "")
        if not val.isdigit():
            await sm(context.bot, uid, "❌ Faqat musbat butun son kiriting (so'm), masalan: <code>50000</code>\n"
                                       "Tekin qilish uchun <code>0</code> kiriting:")
            return True
        new_price = int(val)
        OPENBUDGET_CREATE_PRICE = new_price
        save_openbudget_create_price(new_price)
        await _set_factory_price_setting("factory_openbudget_create_price", new_price)
        clear_admin_state(context)
