    # ── Bola botga xabar — rasm yoki matn yuborish ──
    if (not IS_CHILD_BOT) and context.user_data.get("child_msg_state") == "await_msg":
        tgt = context.user_data.get("child_msg_target") or {}
        owner_id = int(tgt.get("owner_id") or 0)
        token    = tgt.get("token") or ""
