# RAILWAY HEALTH CHECK + CHECKCARD WEBHOOK SERVER
# ══════════════════════════════════════════════════════════

# Global bot reference — webhook handler uchun
_BOT_APP = None
_MAIN_LOOP = None   # asyncio event loop — HTTP thread'dan Pyrogram/PTB corotine chaqirish uchun

# ══════════════════════════════════════════════════════════
# 🌐 SAYTDA TOMOSHA QILISH — kino qismini brauzerda ochish
#   Foydalanuvchi qismni bosganda, video Telegramga yuborilishi bilan
#   birga, "🌐 Saytda tomosha qilish" tugmasi ham beriladi. Bu tugma
#   PUBLIC_SITE_URL/watch/<token> manzilini ochadi — u yerda video HTML5
#   pleer orqali ko'rsatiladi. Faqat shu tokenni olgan foydalanuvchi
#   ochadi va token muddati tugagach ishlamay qoladi.
# ══════════════════════════════════════════════════════════
import secrets as _fx_secrets

_WATCH_TOKENS = {}          # token -> {"code":.., "ep":.., "user_id":.., "expire_at":.., "file_id":.., "title":..}
_WATCH_TOKENS_LOCK = threading.Lock()
WATCH_TOKEN_TTL = 6 * 3600  # token 6 soat amal qiladi

def create_watch_token(code: str, ep: str, user_id, file_id: str, title: str = "") -> str:
    token = _fx_secrets.token_urlsafe(20)
    with _WATCH_TOKENS_LOCK:
        now = time.time()
        for t in list(_WATCH_TOKENS.keys()):
            if _WATCH_TOKENS[t]["expire_at"] < now:
                _WATCH_TOKENS.pop(t, None)
        _WATCH_TOKENS[token] = {
            "code": code, "ep": ep, "user_id": str(user_id),
            "file_id": file_id, "title": title,
            "expire_at": now + WATCH_TOKEN_TTL,
        }
    return token

def get_watch_token(token: str):
    with _WATCH_TOKENS_LOCK:
        row = _WATCH_TOKENS.get(token)
        if not row:
            return None
        if row["expire_at"] < time.time():
            _WATCH_TOKENS.pop(token, None)
            return None
        return row

# ─── Video fayllarni diskka keshlab, brauzerga Range so'rovlari bilan
#     uzatish uchun papka. Pyrogram (API_ID/API_HASH) orqali 2GB gacha
#     fayl yuklab olinadi — oddiy Bot API'ning 20MB chegarasidan chetlab
#     o'tiladi (xuddi admin panelidagi "video siqish" funksiyasi kabi).
_VIDEO_CACHE_DIR = os.path.join(_PERSIST_DIR, "watch_cache")
try:
    os.makedirs(_VIDEO_CACHE_DIR, exist_ok=True)
except Exception:
    pass
_VIDEO_DL_LOCKS = {}
_VIDEO_DL_MASTER_LOCK = threading.Lock()

def _video_cache_path(file_id: str) -> str:
    safe = re.sub(r"[^A-Za-z0-9_-]", "_", file_id)[:180]
    return os.path.join(_VIDEO_CACHE_DIR, safe + ".mp4")

def _ensure_local_video_file(file_id: str, timeout: int = 900):
    """
    file_id'ga mos videoni diskda kesh qiladi (agar hali yo'q bo'lsa,
    Pyrogram MTProto orqali — 2GB gacha — asosiy event loop ichida
    yuklab oladi) va lokal fayl yo'lini qaytaradi. Xato bo'lsa None.
    """
    path = _video_cache_path(file_id)
    if os.path.exists(path) and os.path.getsize(path) > 0:
        return path

    with _VIDEO_DL_MASTER_LOCK:
        lock = _VIDEO_DL_LOCKS.setdefault(file_id, threading.Lock())

    with lock:
        # Boshqa so'rov navbatda kutayotgan paytda allaqachon yuklangan bo'lishi mumkin
        if os.path.exists(path) and os.path.getsize(path) > 0:
            return path
        if _MAIN_LOOP is None:
            logger.error("_ensure_local_video_file: asosiy event loop hali tayyor emas")
            return None
        tmp_path = path + f".part{os.getpid()}"
        try:
            fut = asyncio.run_coroutine_threadsafe(
                _download_via_pyrogram(file_id, tmp_path), _MAIN_LOOP)
            result = fut.result(timeout=timeout)
        except Exception as e:
            logger.error(f"_ensure_local_video_file pyrogram xato: {e}")
            result = None
        if result and os.path.exists(tmp_path) and os.path.getsize(tmp_path) > 1000:
            try:
                os.replace(tmp_path, path)
                return path
            except Exception as e:
                logger.error(f"video cache rename xato: {e}")
                return tmp_path if os.path.exists(tmp_path) else None
        try:
            if os.path.exists(tmp_path):
                os.unlink(tmp_path)
        except Exception:
            pass
        return None

def _serve_local_file_with_range(handler: "_WebhookHandler", path: str, content_type: str = "video/mp4"):
    """Diskdagi faylni HTTP Range so'roviga mos holda uzatadi (video seek/pauza uchun kerak)."""
    try:
        file_size = os.path.getsize(path)
    except Exception:
        handler.send_response(404); handler.end_headers()
        return

    rng = handler.headers.get("Range")
    start, end = 0, file_size - 1
    status = 200
    if rng and rng.startswith("bytes="):
        try:
            rng_val = rng.split("=", 1)[1]
            s, _, e = rng_val.partition("-")
            if s:
                start = int(s)
            if e:
                end = int(e)
            end = min(end, file_size - 1)
            status = 206
        except Exception:
            start, end, status = 0, file_size - 1, 200

    length = end - start + 1
    handler.send_response(status)
    handler.send_header("Content-Type", content_type)
    handler.send_header("Accept-Ranges", "bytes")
    handler.send_header("Content-Length", str(length))
    if status == 206:
        handler.send_header("Content-Range", f"bytes {start}-{end}/{file_size}")
    handler.end_headers()

    try:
        with open(path, "rb") as f:
            f.seek(start)
            remaining = length
            chunk_size = 256 * 1024
            while remaining > 0:
                chunk = f.read(min(chunk_size, remaining))
                if not chunk:
                    break
                try:
                    handler.wfile.write(chunk)
                except Exception:
                    break
                remaining -= len(chunk)
    except Exception as e:
        logger.error(f"_serve_local_file_with_range xato: {e}")

_WATCH_PAGE_HTML = """<!DOCTYPE html>
<html lang="uz">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{title}</title>
<style>
  html,body{{margin:0;padding:0;background:#0b0b0f;height:100%;font-family:-apple-system,Segoe UI,Roboto,sans-serif;}}
  .wrap{{display:flex;flex-direction:column;height:100%;}}
  .top{{color:#fff;padding:14px 16px;font-size:16px;font-weight:600;background:#151520;}}
  video{{width:100%;flex:1;background:#000;}}
  .loading{{color:#aaa;text-align:center;padding:40px 16px;font-size:14px;}}
</style>
</head>
<body>
<div class="wrap">
  <div class="top">🎬 {title}</div>
  <div class="loading" id="ld">⏳ Video yuklanmoqda, biroz kuting (katta fayllar 1-2 daqiqa vaqt olishi mumkin)...</div>
  <video controls autoplay playsinline controlsList="nodownload" src="/video/{token}"
         onloadstart="document.getElementById('ld').style.display='none'"></video>
</div>
</body>
</html>"""

def _watch_handle_get(handler: "_WebhookHandler", path: str):
    """/watch/<token> va /video/<token> so'rovlarini qayta ishlaydi. True = shu yerda javob berildi."""
    parts = path.strip("/").split("/")
    if len(parts) != 2 or parts[0] not in ("watch", "video"):
        return False

    kind, token = parts
    row = get_watch_token(token)
    if not row:
        handler.send_response(404)
        handler.send_header("Content-Type", "text/plain; charset=utf-8")
        handler.end_headers()
        handler.wfile.write("❌ Link muddati tugagan yoki noto'g'ri.".encode("utf-8"))
        return True

    if kind == "watch":
        html_out = _WATCH_PAGE_HTML.format(
            title=html.escape(row.get("title") or "Kino"), token=token)
        body = html_out.encode("utf-8")
        handler.send_response(200)
        handler.send_header("Content-Type", "text/html; charset=utf-8")
        handler.send_header("Content-Length", str(len(body)))
        handler.end_headers()
        handler.wfile.write(body)
        return True

    # kind == "video" — Pyrogram (API_ID/API_HASH, 2GB gacha) orqali diskka
    # keshlab, brauzerga Range so'rovlari bilan uzatamiz.
    local_path = _ensure_local_video_file(row["file_id"])
    if not local_path:
        handler.send_response(502)
        handler.end_headers()
        handler.wfile.write("Video yuklab bo'lmadi. Birozdan so'ng qayta urinib ko'ring.".encode("utf-8"))
        return True

    _serve_local_file_with_range(handler, local_path)
    return True


class _WebhookHandler(BaseHTTPRequestHandler):
    def do_GET(self):
        try:
            path_only = self.path.split("?", 1)[0]
            if path_only.startswith("/watch/") or path_only.startswith("/video/"):
                if _watch_handle_get(self, path_only):
                    return
        except Exception as e:
            logger.error(f"do_GET (/watch,/video) xato: {e}")
            try:
                self.send_response(500); self.end_headers()
            except Exception:
                pass
            return
        self.send_response(200)
        self.send_header("Content-Type", "text/plain")
        self.end_headers()
        self.wfile.write(b"OK")

    def do_POST(self):
        """CheckCard webhook — to'lov bo'lganda keladi."""
        if self.path != CHECKCARD_WEBHOOK_PATH:
            self.send_response(404)
            self.end_headers()
            return
        try:
            length = int(self.headers.get("Content-Length", 0))
            body   = self.rfile.read(length)
            data   = json.loads(body.decode("utf-8"))
            logger.info(f"📩 CheckCard webhook keldi: {data}")
            # Async handler ni event loop orqali chaqiramiz
            import asyncio
            loop = asyncio.new_event_loop()
            loop.run_until_complete(_handle_checkcard_webhook(data))
            loop.close()
        except Exception as e:
            logger.error(f"Webhook handler xato: {e}")
        self.send_response(200)
        self.send_header("Content-Type", "application/json")
        self.end_headers()
        self.wfile.write(b'{"ok": true}')

    def log_message(self, *args):
        pass


async def _handle_checkcard_webhook(data: dict):
    """
    CheckCard to'lov webhookini qayta ishlaydi.
    JSON: {"shopkey": "...", "amount": 50000, "order": "owld1002", "date": "..."}
    """
    try:
        shop_key = data.get("shopkey") or data.get("shop_key") or ""
        order    = str(data.get("order") or "")
        amount   = int(data.get("amount") or 0)

        # Shop key tekshiruvi — xavfsizlik uchun
        if shop_key and shop_key != CHECKCARD_SHOP_KEY:
            logger.warning(f"Webhook: noto'g'ri shop_key: {shop_key}")
            return

        if not order:
            logger.warning("Webhook: order yo'q")
            return

        # RAM.pending_payments dan shu order'ni topamiz
        found_pid = None
        found_pay = None
        for pid, pay in list(RAM.pending_payments.items()):
            if (pay.get("type") == "topup_checkcard"
                    and str(pay.get("cc_order")) == order
                    and pay.get("cc_status") == "pending"):
                found_pid = pid
                found_pay = pay
                break

        if not found_pay:
            logger.warning(f"Webhook: order {order} uchun pending to'lov topilmadi")
            return

        # Balansga qo'shamiz
        if found_pay.get("cc_status") == "paid":
            logger.warning(f"Webhook: order {order} allaqachon to'langan — ikki marta qo'shilmaydi!")
            return
        found_pay["cc_status"] = "paid"
        # found_pay["amount"] — so'mda saqlangan (biz shu qiymatni ishlatamiz)
        # webhook "amount" — so'mda keladi, found_pay dagi so'm qiymatini ishlatamiz
        pay_amount = int(found_pay.get("amount") or amount)
        uid_str    = str(found_pay.get("user_id"))
        u_data     = RAM.ensure_user(uid_str)
        u_data["balance"]     = int(u_data.get("balance") or 0) + pay_amount
        u_data["topup_total"] = int(u_data.get("topup_total") or 0) + pay_amount
        # ✅ AUTO TO'LOV — global hisobga qo'shamiz (webhook)
        RAM.auto_topup_total = int(RAM.auto_topup_total or 0) + pay_amount
        RAM.auto_topup_count = int(RAM.auto_topup_count or 0) + 1


        # Fon saqlash
        import asyncio
        asyncio.create_task(save_now()) if _is_event_loop_running() else None
        await asyncio.to_thread(_save_local, RAM.to_dict())

        logger.info(f"✅ Webhook: {uid_str} ga {pay_amount:,} so'm qo'shildi (order: {order})")

        # Foydalanuvchiga xabar — bot mavjud bo'lsa
        if _BOT_APP and _BOT_APP.bot:
            try:
                await _BOT_APP.bot.send_message(
                    int(uid_str),
                    f"<blockquote>✅ <b>TO'LOV TASDIQLANDI!</b>\n\n"
                    f"💵 Miqdor: <b>{pay_amount:,} so'm</b> balansingizga qo'shildi!\n"
                    f"💰 Joriy balans: <b>{u_data['balance']:,} so'm</b>\n\n"
                    f"Endi balansdan pullik qismlarni tomosha qilishingiz mumkin! 🎬</blockquote>",
                    parse_mode="HTML")
            except Exception as e:
                logger.warning(f"Webhook notify xato: {e}")
            # Adminga xabar
            try:
                u_d = RAM.users.get(uid_str) or {}
                u_name = u_d.get("name") or u_d.get("first_name") or f"ID: {uid_str}"
                u_uname = u_d.get("username") or ""
                uname_adm = f"@{u_uname}" if u_uname else f"ID: {uid_str}"
                if u_uname:
                    lichka_url = f"https://t.me/{u_uname}"
                else:
                    lichka_url = f"tg://user?id={uid_str}"
                tashkent_time = _tashkent_now_str()
                card_info = f"\n💳 Karta: <code>{RAM.card_number}</code>" if RAM.card_number else ""
                adm_cap = (
                    f"<blockquote>"
                    f"✅ <b>AUTO TO'LOV ORQALI TO'LANDI</b>\n\n"
                    f"👤 <b>Ism:</b> {u_name}\n"
                    f"🆔 <b>ID:</b> <code>{uid_str}</code>\n"
                    f"📱 <b>Username:</b> {uname_adm}\n\n"
                    f"💵 <b>To'langan summa:</b> <b>{pay_amount:,} so'm</b>\n"
                    f"💰 <b>Joriy balans:</b> <b>{u_data['balance']:,} so'm</b>\n"
                    f"{card_info}\n\n"
                    f"🕐 <b>Vaqt (Toshkent):</b> {tashkent_time}"
                    f"</blockquote>"
                )
                lichka_kb_wh = {"inline_keyboard": [[{"text": "👤 Foydalanuvchi lichkasi", "url": lichka_url}]]}
                await _BOT_APP.bot.send_message(
                    ADMIN_ID, adm_cap, parse_mode="HTML",
                    reply_markup=lichka_kb_wh)
            except Exception as _e:
                logger.warning(f"Webhook admin notify xato: {_e}")
    except Exception as e:
        logger.error(f"_handle_checkcard_webhook xato: {e}")


def _is_event_loop_running() -> bool:
    try:
        import asyncio
        loop = asyncio.get_running_loop()
        return loop is not None
    except RuntimeError:
        return False


def _start_health_server():
    port = int(os.environ.get("PORT", 8080))
    try:
        from http.server import ThreadingHTTPServer
        server = ThreadingHTTPServer(("0.0.0.0", port), _WebhookHandler)
        t = threading.Thread(target=server.serve_forever, daemon=True)
        t.start()
        logger.info(f"✅ Railway webhook server port {port} da ishga tushdi")
        logger.info(f"📡 CheckCard webhook URL: {PUBLIC_SITE_URL}{CHECKCARD_WEBHOOK_PATH}")
    except Exception as e:
        logger.warning(f"Health/Webhook server xato: {e}")


