    async def _vip_cc_poll_job(context):
        """Hamyon API orqali VIP tarif to'lovini tekshiradi. Muvaffaqiyatli bo'lsa
        avtomatik ravishda invite link yaratib, foydalanuvchiga yuboradi va
        obunani + tushum hisobini yangilaydi."""
        try:
            jd = context.job.data
            pay_id = jd["pay_id"]
            uid    = jd["uid"]
            order  = jd["order"]
            amount = jd["amount"]
            tries  = jd.get("tries", 0)
            topup_msg_id = jd.get("topup_msg_id")

            if tries >= 20:  # 20 * 15s = 5 daqiqa
                context.job.schedule_removal()
                pending = _vip_get_pending()
                info = pending.get(pay_id)
                if info and info.get("cc_status") == "pending":
                    info["cc_status"] = "expired"
                    _vip_save_pending(pending)
                    try:
                        _tidx = info.get("tariff_idx")
                        _s_cd = _vip_get_settings()
                        _tariffs = _s_cd.get("tariffs") or []
                        if _tidx is not None and 0 <= int(_tidx) < len(_tariffs):
                            _base = int(_tariffs[int(_tidx)].get("price", 0) or 0)
                            _off = int(info.get("price", 0) or 0) - _base
                            _cd = _s_cd.get("_auto_offset_cooldown") or {}
                            _now_ts2 = time.time()
                            _cd[str(_off)] = _now_ts2
                            _s_cd["_auto_offset_cooldown"] = {
                                k: v for k, v in _cd.items() if _now_ts2 - v < 30}
                            _vip_save_settings(_s_cd)
                    except Exception:
                        pass
                    try:
                        await asyncio.to_thread(hamyon_cancel_payment, order)
                    except Exception:
                        pass
                    try:
                        await context.bot.send_message(
                            uid,
                            f"⏰ <b>Avto to'lov muddati tugadi.</b>\n\n"
                            f"Miqdor: <b>{amount:,} so'm</b>\n\n"
                            f"Qayta urinish uchun tarifni qayta tanlang.",
                            parse_mode="HTML")
                    except Exception:
                        pass
                return

            jd["tries"] = tries + 1

            pending = _vip_get_pending()
            info = pending.get(pay_id)
            if not info or info.get("cc_status") in ("paid", "cancelled", "expired"):
                context.job.schedule_removal()
                return

            result = await asyncio.to_thread(hamyon_check_payment, order)
            logger.info(f"[VIP] poll {order}: {result}")
            cc_data = result.get("data", {}) or {}
            cc_status = (cc_data.get("status") or cc_data.get("state")
                         or result.get("status") or result.get("state") or "")
            cc_status = str(cc_status).lower().strip()

            if cc_status == "paid":
                context.job.schedule_removal()
                # Ikki marta yozilib qolmasligi uchun
                pending = _vip_get_pending()
                info = pending.get(pay_id)
                if not info or info.get("cc_status") == "paid":
                    return
                info["cc_status"] = "paid"
                _vip_save_pending(pending)

                # Sozlamalar (kanal_id) — pul kelgan payt jonli o'qiymiz
                s_now = _vip_get_settings()
                days  = int(info.get("days") or 0)
                price = int(info.get("price") or 0)

                # Invite link — bir martalik, 1 kunlik
                invite_link = None
                if s_now.get("channel_id"):
                    try:
                        exp_ts = int(time.time()) + 86400
                        link_obj = await context.bot.create_chat_invite_link(
                            chat_id=s_now["channel_id"], member_limit=1,
                            expire_date=exp_ts, name=f"vip_auto_{uid}")
                        invite_link = link_obj.invite_link
                    except Exception as e:
                        logger.error(f"[VIP] auto invite xato: {e}")

                # Obunani yozamiz (mavjud bo'lsa cho'zamiz)
                subs = _vip_get_subs()
                prev = subs.get(str(uid))
                now  = datetime.now()
                base = now
                if prev and prev.get("expires_at"):
                    try:
                        prev_exp = datetime.fromisoformat(prev["expires_at"])
                        if prev_exp > now:
                            base = prev_exp
                    except Exception:
                        pass
                new_exp = base + timedelta(days=days)
                subs[str(uid)] = {
                    "expires_at": new_exp.isoformat(),
                    "name": info.get("name", ""),
                    "username": info.get("username", ""),
                    "last_paid": price, "kicked": False,
                    "joined_at": (prev.get("joined_at") if prev and prev.get("joined_at")
                                  else now.isoformat()),
                }
                _vip_save_subs(subs)

                # Tushumga qo'shamiz (admin panelida ko'rinadi + yechish so'rovi shuni ishlatadi)
                try:
                    if price > 0:
                        s_now["income_total"] = int(s_now.get("income_total") or 0) + price
                        s_now["income_count"] = int(s_now.get("income_count") or 0) + 1
                        _vip_save_settings(s_now)
                except Exception as _e:
                    logger.warning(f"[VIP] income yangilash xato: {_e}")

                # Eski to'lov xabarini o'chirib tashlaymiz
                if topup_msg_id:
                    try:
                        await context.bot.delete_message(chat_id=uid, message_id=topup_msg_id)
                    except Exception:
                        pass

                # Foydalanuvchiga xabar + invite link
                try:
                    if invite_link:
                        await context.bot.send_message(
                            uid,
                            f"✅ <b>To'lovingiz avtomatik tasdiqlandi!</b>\n\n"
                            f"💵 Summa: <b>{price:,} so'm</b>\n"
                            f"📅 Obuna muddati: <b>{new_exp.strftime('%d.%m.%Y')}</b> gacha\n\n"
                            f"👇 Quyidagi bir martalik havola orqali VIP kanalga qo'shiling:\n{invite_link}",
                            parse_mode="HTML",
                            disable_web_page_preview=True)
                    else:
                        await context.bot.send_message(
                            uid,
                            "✅ To'lov qabul qilindi, lekin havola avtomatik yaratilmadi. "
                            "Admin siz bilan tez orada bog'lanadi.")
                except Exception:
                    pass

                # Adminga xabar
                try:
                    uname = info.get("username") or ""
                    uname_adm = f"@{uname}" if uname else f"ID: {uid}"
                    lichka_url = f"https://t.me/{uname}" if uname else f"tg://user?id={uid}"
                    adm_kb = InlineKeyboardMarkup([[
                        _ikb("👤 Foydalanuvchi lichkasi", url=lichka_url, style="primary")
                    ]])
                    await context.bot.send_message(
                        ADMIN_ID,
                        f"<blockquote>✅ <b>VIP — AVTO TO'LOV</b>\n\n"
                        f"👤 <b>Ism:</b> {html.escape(info.get('name','') or '')}\n"
                        f"🆔 <b>ID:</b> <code>{uid}</code>\n"
                        f"📱 <b>User:</b> {uname_adm}\n\n"
                        f"💵 <b>Summa:</b> <b>{price:,} so'm</b>\n"
                        f"📅 <b>Muddat:</b> {days} kun (→ {new_exp.strftime('%d.%m.%Y')})\n"
                        f"📋 <b>Order:</b> <code>{order}</code>"
                        f"</blockquote>",
                        parse_mode="HTML", reply_markup=adm_kb)
                except Exception as _e:
                    logger.warning(f"[VIP] admin notify xato: {_e}")

            elif cc_status == "cancel":
                context.job.schedule_removal()
                pending = _vip_get_pending()
                info = pending.get(pay_id)
                if info:
                    info["cc_status"] = "cancelled"
                    _vip_save_pending(pending)
                try:
                    await context.bot.send_message(
                        uid,
                        f"❌ <b>Avto to'lov bekor qilindi.</b>\n\n"
                        f"Miqdor: <b>{amount:,} so'm</b>\nQayta urinish uchun tarifni qayta tanlang.",
                        parse_mode="HTML")
                except Exception:
                    pass
        except Exception as e:
            logger.error(f"_vip_cc_poll_job xato: {e}")


