    def vip_admin_kb() -> ReplyKeyboardMarkup:
        """Pastki (persistent) menyu — VIP admin panel, rangli tugmalar bilan."""
        _s = _vip_get_settings()
        auto_on = bool(_s.get("auto_enabled"))
        auto_label = "⚡ Auto to'lov: YOQILGAN ✅" if auto_on else "⚡ Auto to'lov: O'CHIRILGAN ❌"
        # Har bir tugma asosiy bot admini tomonidan yoqilgan/o'chirilgan
        # (get_child_btn_flag). Standart holatda hammasi yoqiq — YANGI "Karta
        # qo'shish" tugmasi bundan mustasno (default OFF, chunki asosiy bot
        # admini ruxsat bermaguncha ko'rinmasin).
        _bid = FACTORY_CHILD_ID or "0"
        def _on(key: str) -> bool:
            return get_child_btn_flag(_bid, key, _btn_flag_default(key))

        proto = [
            [("kanal_biriktirish", "📢 Kanal biriktirish", "primary"),
             ("majburiy_obuna",    "🔒 Majburiy obuna",   "primary")],
            [("tariflar",          "💰 Tariflar",         "primary"),
             ("tavsif_matni",      "📝 Tavsif matni",     "primary")],
            [("karta_raqami",      "💳 Karta raqami",     "primary")],
            [("vip_auto_karta",    "💳 Karta qo'shish",   "primary")],
            [("vip_gift_sub",      "🎁 Kanalga obuna berish", "success")],
            [("auto_tolov",        auto_label,             "success" if auto_on else "danger")],
            [("obunachilar",       "📊 Obunachilar",      "success"),
             ("bloklanganlar",     "🚫 Bloklanganlar",    "danger")],
            [("tushum",            "💰 Tushum",           "success"),
             ("pul_yechish",       "💸 Pul yechish",      "success")],
            [("xabarnoma",         "✉️ Xabarnoma",        "success"),
             ("yangilash",         "🔄 Yangilash",        "primary")],
        ]
        rows = []
        for row in proto:
            visible = [(lbl, st) for (k, lbl, st) in row if _on(k)]
            if visible:
                rows.append([_kb(lbl, style=st) for (lbl, st) in visible])
        if not rows:
            # Hech qaysi tugma yoqilmagan bo'lsa — kamida "Yangilash" chiqarib
            # turaylik, admin qulflab qo'ymasin.
            rows = [[_kb("🔄 Yangilash", style="primary")]]
        return ReplyKeyboardMarkup(
            rows, resize_keyboard=True, is_persistent=True,
        )

