    def vip_admin_menu_text(s: dict) -> str:
        subs = _vip_get_subs()
        now = datetime.now()
        active = 0
        for v in subs.values():
            try:
                if datetime.fromisoformat(v.get("expires_at", "")) > now:
                    active += 1
            except Exception:
                pass
        ch_ok = bool(s.get("channel_id"))
        ch = html.escape(s.get("channel_title") or "Biriktirilmagan")
        ch_status = "🟢 Ulangan" if ch_ok else "🔴 Ulanmagan"
        auto_on = bool(s.get("auto_enabled"))
        card_ok = bool(s.get("card_number"))
        card = html.escape(s.get("card_number") or "Kiritilmagan")
        if auto_on:
            pay_status = "⚡ Avtomatik to'lov"
        elif card_ok:
            pay_status = "💳 Qo'lda (chek orqali)"
        else:
            pay_status = "🔴 Sozlanmagan"
        tariffs = s.get("tariffs") or []
        if tariffs:
            tarifs_txt = "\n".join(
                f"   {i}. {html.escape(str(t.get('label','')))} — "
                f"<b>{_vip_fmt(t.get('price',0))} so'm</b> ({int(t.get('days',0))} kun)"
                for i, t in enumerate(tariffs, 1))
        else:
            tarifs_txt = "   ❌ Hali kiritilmagan"
        ready = ch_ok and tariffs and (auto_on or card_ok)
        ready_line = ("✅ <b>Bot to'liq sozlangan va ishga tayyor!</b>" if ready else
                       "⏳ <b>Bot hali to'liq sozlanmagan</b> — pastdagi tugmalar orqali sozlang.")
        return (
            "<blockquote>💎 <b>VIP KANAL BOT</b> — boshqaruv paneli</blockquote>\n\n"
            "📡 <b>Ulanish</b>\n"
            f"   • Kanal: <b>{ch}</b>\n"
            f"   • Holati: {ch_status}\n"
            f"   • To'lov rejimi: {pay_status}\n"
            f"   • Karta: <code>{card}</code>\n\n"
            "👥 <b>Obunachilar</b>\n"
            f"   • Faol: <b>{active}</b> ta\n\n"
            "💰 <b>Tariflar</b>\n"
            f"{tarifs_txt}\n\n"
            f"{ready_line}"
        )

