    async def _vip_check_force_sub(context, uid) -> list:
        """Foydalanuvchi obuna bo'lmagan kanallar ro'yxatini qaytaradi."""
        s = _vip_get_settings()
        missing = []
        for item in s.get("force_sub") or []:
            if item.get("type") == "link":
                continue  # oddiy havola — tekshirilmaydi
            cid = item.get("chat_id")
            if not cid:
                continue
            status = "left"
            try:
                member = await context.bot.get_chat_member(cid, uid)
                status = member.status
            except Exception:
                status = "left"
            if status in ("member", "administrator", "creator"):
                continue
            if item.get("type") == "request":
                reqs = _pg_kv_get("vip_fsub_requests") or {}
                if str(uid) in (reqs.get(str(cid)) or []):
                    continue
            missing.append(item)
        return missing

    def _vip_fsub_gate_kb(missing: list) -> InlineKeyboardMarkup:
        rows = []
        for it in missing:
            icon = _FSUB_ICON.get(it.get("type"), "🔗")
            rows.append([_ikb(f"{icon} {it.get('title','')}", url=it.get("url"))])
        rows.append([_ikb("✅ Obuna bo'ldim", callback_data="vip_fsub_check", style="success")])
        return InlineKeyboardMarkup(rows)

