    def _vip_pick_auto_amount(s: dict, idx: int, base_price: int) -> int:
        """1000 so'mlik "toza" qadamlar bilan (15000, 16000, 17000...) hozir
        band bo'lmagan eng arzon "joy"ni tanlaydi — 50/100 so'mlik xunuk
        qo'shimchalar (15050, 15100...) ENDI ISHLATILMAYDI. Hammasi band
        bo'lsa yuqoriga (1000 so'm qadam bilan) davom etadi.

        ⚠️ MUHIM: "pending" deb belgilangan to'lovni avtomatik "expired"ga
        o'tkazadigan job — bot RESTART/qayta deploy bo'lganda albatta
        yo'qolib qoladi (job_queue faqat xotirada, diskka yozilmaydi).
        Shu sababli eski (masalan avvalgi test/urinishlardan qolgan)
        "pending" yozuvlar MUDDATI o'tgan bo'lsa ham abadiy "band" bo'lib
        qolib, hatto BIRINCHI marta tarif bosilganda ham narxni keraksiz
        oshirib yuborardi. Shuning uchun bu yerda ham MUDDATI (5 daqiqa —
        _vip_cc_poll_job dagi bilan bir xil) o'tgan yozuvlarni "band"
        hisoblamaymiz va ular haqiqatda ham "expired"ga o'tkazib,
        saqlab qo'yamiz (o'z-o'zini tozalash)."""
        _PENDING_TIMEOUT = 300  # 5 daqiqa — _vip_cc_poll_job muddati bilan bir xil
        _off_steps = list(range(0, 20001, 1000))
        _pending_all = _vip_get_pending()
        _now_ts = time.time()
        _used_offsets = set()
        _stale_ids = []
        for _pid, _pinfo in _pending_all.items():
            if not (_pinfo.get("type") in ("vip_hamyon", "vip_checkcard")
                    and _pinfo.get("cc_status") == "pending"
                    and int(_pinfo.get("tariff_idx", -1)) == idx):
                continue
            _is_stale = True
            try:
                _created = datetime.fromisoformat(_pinfo.get("created_at", ""))
                _is_stale = (_now_ts - _created.timestamp()) > _PENDING_TIMEOUT
            except Exception:
                _is_stale = False  # created_at o'qib bo'lmasa — xavfsiz tomonga, band deb hisoblaymiz
            if _is_stale:
                _stale_ids.append(_pid)
                continue
            try:
                _used_offsets.add(int(_pinfo.get("price", 0)) - base_price)
            except Exception:
                pass
        if _stale_ids:
            try:
                for _pid in _stale_ids:
                    if _pid in _pending_all:
                        _pending_all[_pid]["cc_status"] = "expired"
                _vip_save_pending(_pending_all)
            except Exception:
                pass
        _cooldown = s.get("_auto_offset_cooldown") or {}
        _cool_offsets = {int(k) for k, v in _cooldown.items() if _now_ts - v < 30}
        _blocked = _used_offsets | _cool_offsets
        _chosen_off = next((o for o in _off_steps if o not in _blocked), None)
        if _chosen_off is None:
            _extra_off = 21000
            while _extra_off < 200000:
                if _extra_off not in _used_offsets and _extra_off not in _cool_offsets:
                    _chosen_off = _extra_off
                    break
                _extra_off += 1000
            if _chosen_off is None:
                _chosen_off = _off_steps[-1]
        return base_price + _chosen_off

    async def _vip_auto_retry_create_job(context):
        """Auto to'lov yaratishga birinchi urinishda joy topilmasa (juda ko'p
        odam bir vaqtda to'layotgan bo'lsa), orqa fonda joy bo'shaguncha
        avtomatik qayta urinadi — foydalanuvchi hech narsa bosishi shart emas."""
        jd = context.job.data
        uid    = jd["uid"]
        idx    = jd["idx"]
        msg_id = jd["msg_id"]
        tries  = jd.get("tries", 0)
        MAX_TRIES = 18  # ~18 * 5s = 90 soniya

        if tries >= MAX_TRIES:
            context.job.schedule_removal()
            try:
                s_now = _vip_get_settings()
                await context.bot.edit_message_text(
                    chat_id=uid, message_id=msg_id,
                    text=("⚠️ <b>Hozir juda ko'p to'lov amalga oshirilmoqda.</b>\n\n"
                          "Iltimos, tarifni qaytadan tanlang — biroz vaqtdan so'ng "
                          "joy bo'shaydi."),
                    parse_mode="HTML", reply_markup=vip_tariff_kb(s_now))
            except Exception:
                pass
            return

        jd["tries"] = tries + 1
        s_now = _vip_get_settings()
        tariffs = s_now.get("tariffs") or []
        if idx >= len(tariffs):
            context.job.schedule_removal()
            return
        t = tariffs[idx]
        base_price = int(t.get("price", 0) or 0)
        final_amount = _vip_pick_auto_amount(s_now, idx, base_price)
        order_id = f"v{uid}{int(time.time())}"
        result = await asyncio.to_thread(hamyon_create_payment, final_amount, order_id)
        if result.get("status") != "success":
            return  # keyingi urinishda run_repeating o'zi qayta chaqiradi

        context.job.schedule_removal()
        cc_order = result.get("order")
        pay_id = f"vauto_{uid}_{int(time.time())}"
        pending = _vip_get_pending()
        pending[pay_id] = {
            "type":       "vip_hamyon",
            "user_id":    uid,
            "name":       jd.get("name", ""),
            "username":   jd.get("username", ""),
            "tariff_idx": idx,
            "days":       int(t.get("days", 0)),
            "price":      final_amount,
            "cc_order":   cc_order,
            "cc_status":  "pending",
            "created_at": datetime.now().isoformat(),
        }
        _vip_save_pending(pending)

        card_num  = (vip_kassa_active().get('card') or vip_kassa_active().get('card') or s.get('auto_card_number') or VIP_AUTO_CARD_NUMBER)
        card_owner = s.get('auto_card_owner') or ''
        price_txt = _vip_fmt(final_amount)
        kb_rows = [
            [
                _ikb("💳 Kartani nusxalash", copy_text=CopyTextButton(text=str(card_num))),
                _ikb("💵 Miqdorni nusxalash", copy_text=CopyTextButton(text=str(final_amount))),
            ],
            [_ikb("❌ Bekor qilish", callback_data=f"vip_buy_auto_cancel:{pay_id}", style="danger")],
        ]
        try:
            await context.bot.edit_message_text(
                chat_id=uid, message_id=msg_id,
                text=(f"⚡ <b>AVTO TO'LOV</b>\n\n"
                      f"🆔 To'lov ID: <code>{html.escape(str(pay_id))}</code>\n"
                      f"💎 Tarif: <b>{html.escape(str(t.get('label','')))}</b>\n"
                      f"💵 Summa: <b>{price_txt} so'm</b>\n\n"
                      f"💳 Kartaga o'tkazing:\n<code>{html.escape(card_num)}</code>\n\n"
                      f"<blockquote>⚠️ <b>DIQQAT:</b> Aynan <b>{final_amount:,} so'm</b> yuboring — "
                      f"bir so'm kam yoki ko'p bo'lsa ham to'lov <b>hisoblanmaydi</b> va "
                      f"<b>tasdiqlanmaydi</b>. Bunday holatda admin bilan bog'laning.</blockquote>\n"
                      f"<i>To'lov qilingandan so'ng bot avtomatik aniqlab, VIP kanal havolasini yuboradi.</i>\n\n"
                      f"⏱ Muddat: <b>5 daqiqa</b>"),
                parse_mode="HTML", reply_markup=InlineKeyboardMarkup(kb_rows))
        except Exception:
            pass

        if context.application.job_queue:
            context.application.job_queue.run_repeating(
                _vip_cc_poll_job,
                interval=15, first=15,
                data={"pay_id": pay_id, "uid": uid, "order": cc_order,
                      "amount": final_amount, "tries": 0, "topup_msg_id": msg_id},
                name=f"vip_cc_poll_{pay_id}",
            )

