    async def _vip_send_tariff_screen(context, chat_id, s, query=None):
        """Tavsif (matn yoki rasm) + tarif tugmalarini foydalanuvchiga ko'rsatadi.
        `query` berilsa avval o'sha xabarni tahrirlashga urinib ko'radi, bo'lmasa yangi xabar yuboradi."""
        desc_block = _vip_desc_block(s)
        text = f"{desc_block}\n\nTarifni tanlang 👇" if desc_block else "Tarifni tanlang 👇"
        kb = vip_tariff_kb(s)
        photo = s.get("description_photo")
        if photo:
            if query is not None:
                try:
                    await query.message.delete()
                except Exception:
                    pass
            await context.bot.send_photo(
                chat_id, photo, caption=text[:1024], parse_mode="HTML", reply_markup=kb)
            return
        if query is not None:
            try:
                await query.edit_message_text(text, parse_mode="HTML", reply_markup=kb)
                return
            except Exception:
                pass
        await context.bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=kb)

    # ── ✨ Premium emoji ID'lar ────────────────────────────────────────
    #    Admin "✨ Emoji sozlamalari" tugmasi orqali istalgan tugmaga
    #    premium (animatsiyali) emoji qo'yadi. Sozlamalarda saqlanadi.
    VIP_EMOJI_BUTTONS = [
        ("buy",   "📥 Obuna sotib olish"),
        ("mysub", "👤 Mening obunam"),
        ("about", "📢 Kanal haqida"),
        ("help",  "❓ Yordam"),
        ("home",  "⬅️ Orqaga (bosh menyu)"),
        ("admin", "✍️ Admin bilan bog'lanish"),
    ]

    def _vip_eid(key: str):
        """Tugma uchun o'rnatilgan premium emoji ID (bo'lmasa None)."""
        try:
            return (_vip_get_settings().get("btn_emoji") or {}).get(key) or None
        except Exception:
            return None

    def _vip_btn_label(key: str, text: str) -> str:
        """Agar shu tugmaga premium emoji o'rnatilgan bo'lsa, matn boshidagi
        oddiy emojini olib tashlaydi (ikkalasi birga chiqib qolmasligi uchun)."""
        if _vip_eid(key):
            return re.sub(
                r'^[\U0001F000-\U0001FFFF\u2190-\u21FF\u2300-\u27BF\u2B00-\u2BFF\uFE0F\u200D]+\s*',
                '', text)
        return text

    def _vip_set_eid(key: str, emoji_id):
        s = _vip_get_settings()
        d = dict(s.get("btn_emoji") or {})
        if emoji_id:
            d[key] = str(emoji_id)
        else:
            d.pop(key, None)
        s["btn_emoji"] = d
        _vip_save_settings(s)

