    async def vip_receipt_photo(update, context):
        uid = update.effective_user.id
        if uid != ADMIN_ID and _vip_is_blocked(uid):
            return
        # ── Admin "Tavsif matni" rejimida rasm yuborsa — rasmni tavsif sifatida saqlaymiz ──
        if uid == ADMIN_ID and context.user_data.get("vip_wait") == "start_msg":
            s = _vip_get_settings()
            s["start_photo"] = update.message.photo[-1].file_id
            s["start_text"] = (update.message.caption_html
                               or (update.message.caption or "")) or None
            _vip_save_settings(s)
            context.user_data.pop("vip_wait", None)
            await update.message.reply_text("✅ Start xabari (rasm) saqlandi.",
                                            reply_markup=vip_admin_kb())
            await _vip_send_welcome(context, uid, is_admin=False)
            return
        if uid == ADMIN_ID and context.user_data.get("vip_wait") == "desc":
            s = _vip_get_settings()
            s["description_photo"] = update.message.photo[-1].file_id
            s["description"] = update.message.caption_html or (update.message.caption or "")
            _vip_save_settings(s)
            context.user_data.pop("vip_wait", None)
            await update.message.reply_text("✅ Tavsif (rasm) saqlandi.", reply_markup=vip_admin_kb())
            return
        pay_id = context.user_data.get("vip_waiting_receipt")
        if not pay_id:
            return
        pending = _vip_get_pending()
        info = pending.get(pay_id)
        if not info:
            await update.message.reply_text("⚠️ To'lov so'rovi topilmadi, qaytadan urinib ko'ring.")
            return
        context.user_data.pop("vip_waiting_receipt", None)
        price_txt = _vip_fmt(info.get("price", 0))
        uname = f"@{info['username']}" if info.get("username") else "—"
        buyer_uid = info["user_id"]
        kb = InlineKeyboardMarkup([
            [
                _ikb("✅ Tasdiqlash", callback_data=f"vip_confirm:{pay_id}", style="success"),
                _ikb("❌ Rad etish", callback_data=f"vip_reject:{pay_id}", style="danger"),
            ],
            [
                _ikb("🚫 Bloklash", callback_data=f"vip_block:{buyer_uid}", style="danger"),
                _ikb("👞 Haydash", callback_data=f"vip_kick:{buyer_uid}", style="danger"),
            ],
        ])
        caption = (
            f"🧾 <b>Yangi to'lov cheki</b>\n\n"
            f"👤 {html.escape(str(info.get('name','')))} ({uname})\n"
            f"🆔 <code>{info['user_id']}</code>\n"
            f"💰 {price_txt} so'm — {info.get('days',0)} kun"
        )
        try:
            photo = update.message.photo[-1].file_id
            await context.bot.send_photo(ADMIN_ID, photo, caption=caption, parse_mode="HTML", reply_markup=kb)
        except Exception:
            await context.bot.send_message(ADMIN_ID, caption, parse_mode="HTML", reply_markup=kb)
        await update.message.reply_text("✅ Chek adminga yuborildi. Tasdiqlangach xabar beramiz.")

    async def vip_kick_job(context):
        s = _vip_get_settings()
        ch = s.get("channel_id")
        if not ch:
            return
        subs = _vip_get_subs()
        now = datetime.now()
        changed = False
        for suid, info in list(subs.items()):
            try:
                exp = datetime.fromisoformat(info.get("expires_at", ""))
            except Exception:
                continue
            if exp <= now and not info.get("kicked"):
                try:
                    await context.bot.ban_chat_member(ch, int(suid))
                    await context.bot.unban_chat_member(ch, int(suid))
                except Exception as e:
                    logger.error(f"VIP kick xato ({suid}): {e}")
                info["kicked"] = True
                changed = True
                try:
                    await context.bot.send_message(
                        int(suid),
                        "⏰ VIP obunangiz muddati tugadi. Davom ettirish uchun botga /start yozing.")
                except Exception:
                    pass
        if changed:
            _vip_save_subs(subs)

    app = Application.builder().token(BOT_TOKEN).concurrent_updates(True).build()
    app.add_handler(CommandHandler("start", vip_start))
    app.add_handler(CommandHandler("biriktir", vip_attach_group, filters=filters.ChatType.GROUPS))
    app.add_handler(ChatMemberHandler(vip_my_chat_member, ChatMemberHandler.MY_CHAT_MEMBER))
    app.add_handler(ChatJoinRequestHandler(vip_join_request))
    app.add_handler(CallbackQueryHandler(vip_callback, block=False))
    app.add_handler(MessageHandler(filters.FORWARDED & filters.ChatType.PRIVATE, vip_forward, block=False))
    app.add_handler(MessageHandler(filters.PHOTO, vip_receipt_photo, block=False))
    app.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, vip_text, block=False))

    if app.job_queue:
        app.job_queue.run_repeating(vip_kick_job, interval=3600, first=30)

    async def _vip_error_handler(update, context):
        logger.error(f"VIP bot xatosi: {context.error}")

    app.add_error_handler(_vip_error_handler)

    logger.info("💎 VIP kanal PRO ishga tushdi")
    app.run_polling(drop_pending_updates=True,
                     allowed_updates=["message", "callback_query", "my_chat_member", "chat_join_request"])



