def run_uc_bot():
    # -*- coding: utf-8 -*-
    """
    UC sotish boti — Kino-bot FABRIKASI uchun bola-bot shabloni.

    Bu fayl foydalanuvchi bergan bot__1_.py kodining o'zi — faqat quyidagilar
    o'zgartirildi (fabrika ko'p nusxada ishlatishi uchun ZARUR bo'lgan qism):
      1) BOT_TOKEN / ADMIN_ID endi environment'dan olinadi (fabrika har bir
         bola-botga o'zining tokeni va egasi ID sini beradi).
      2) Har bir bola-bot o'z alohida sqlite faylida ishlaydi (bitta serverda
         bir nechta nusxa bir-birining ma'lumotini bosib yozmasligi uchun).
      3) MAIN_CHANNEL_ID endi kodga yozilmagan — bot egasi buni o'z botidagi
         «📢 Kanal sozlash» tugmasi orqali o'zi kiritadi (chunki har bir xaridor
         o'zining kanaliga post qilishi kerak, boshqa birovning kanaliga emas).
    Boshqa hech qanday yangi funksiya QO'SHILMAGAN — menyu, bosqichlar,
    UC narxlari, e'lon berish oqimi — barchasi asl kod bilan bir xil.
    """

    import asyncio
    import os
    import sqlite3
    import logging
    from datetime import datetime
    import pytz
    from io import BytesIO
    from PIL import Image, ImageDraw, ImageFont

    from aiogram import Bot, Dispatcher, F, Router
    from aiogram.types import (
        Message, CallbackQuery, InlineKeyboardMarkup, InlineKeyboardButton,
        BufferedInputFile, ReplyKeyboardRemove, ReplyKeyboardMarkup, KeyboardButton,
        WebAppInfo
    )
    from aiogram.fsm.context import FSMContext
    from aiogram.fsm.state import State, StatesGroup
    from aiogram.filters import CommandStart, Command

    # ================== SOZLAMALAR (fabrika env orqali beradi) ==================
    BOT_TOKEN = os.environ.get("BOT_TOKEN") or "8505032488:AAGH6eT3T7bHLYLdSYVC4XJBpOH7AYtOz6Q"
    ADMIN_ID = int(os.environ.get("ADMIN_ID") or "8537782289")
    # DB fayli — fabrika har bir bola-bot uchun alohida nom beradi
    DB_NAME = os.environ.get("UC_DB_PATH") or "bot_data.db"
    # ================================================

    def init_db():
        with sqlite3.connect(DB_NAME) as conn:
            c = conn.cursor()
            c.execute('''CREATE TABLE IF NOT EXISTS users 
                         (user_id INTEGER PRIMARY KEY, full_name TEXT, username TEXT, join_date TEXT,
                          posted_ads INTEGER DEFAULT 0, paid_slots INTEGER DEFAULT 0, pending_approval INTEGER DEFAULT 0)''')
            c.execute('''CREATE TABLE IF NOT EXISTS settings 
                         (key TEXT PRIMARY KEY, value TEXT)''')
            c.execute('''CREATE TABLE IF NOT EXISTS channels 
                         (id INTEGER PRIMARY KEY AUTOINCREMENT, channel_id TEXT, url TEXT)''')
            c.execute('''CREATE TABLE IF NOT EXISTS ads 
                         (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, video_id TEXT, text TEXT, status TEXT DEFAULT 'pending')''')
            c.execute('''CREATE TABLE IF NOT EXISTS uc_prices 
                         (id INTEGER PRIMARY KEY AUTOINCREMENT, uc_amount INTEGER, price INTEGER, position INTEGER DEFAULT 0)''')
            c.execute('''CREATE TABLE IF NOT EXISTS uc_orders 
                         (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER, full_name TEXT, username TEXT,
                          uc_amount INTEGER, price INTEGER, pubg_id TEXT, screenshot_id TEXT,
                          status TEXT DEFAULT 'pending', order_date TEXT)''')

            c.execute("INSERT OR IGNORE INTO settings (key, value) VALUES ('price', '50000')")
            c.execute("INSERT OR IGNORE INTO settings (key, value) VALUES ('card', '8600 0000 0000 0000 (Ism Familiya)')")
            c.execute("INSERT OR IGNORE INTO settings (key, value) VALUES ('start_msg', 'Salom {name}! Siz bu botdan PUBG Mobile akkauntingizni obzorini joylashingiz mumkin va u video kanalga joylanadi.')")
            c.execute("INSERT OR IGNORE INTO settings (key, value) VALUES ('site_url', '')")
            c.execute("INSERT OR IGNORE INTO settings (key, value) VALUES ('uc_card', '8600 0000 0000 0000 (Ism Familiya)')")
            c.execute("INSERT OR IGNORE INTO settings (key, value) VALUES ('main_channel_id', '')")
            conn.commit()

    def db_query(query, params=(), fetchone=False, fetchall=False):
        with sqlite3.connect(DB_NAME) as conn:
            c = conn.cursor()
            c.execute(query, params)
            if fetchone: return c.fetchone()
            if fetchall: return c.fetchall()
            conn.commit()
            return c.lastrowid

    init_db()

    # ================== FSM HOLATLAR ==================
    class AdForm(StatesGroup):
        video = State()
        level = State()
        guns = State()
        xsuits = State()
