    # ================== YORDAMCHI FUNKSIYALAR ==================
    def get_time_tashkent():
        tz = pytz.timezone('Asia/Tashkent')
        return datetime.now(tz).strftime('%Y-%m-%d %H:%M:%S')

    def get_setting(key):
        res = db_query("SELECT value FROM settings WHERE key=?", (key,), fetchone=True)
        return res[0] if res else ""

    def get_main_channel():
        """Bot egasi o'rnatgan asosiy kanal (e'lonlar shu yerga joylanadi)."""
        return get_setting('main_channel_id') or ""

    def normalize_channel_id(raw: str):
        """
        Foydalanuvchi kanal manzilini turlicha kiritishi mumkin:
        @kanal_username, https://t.me/kanal_username, t.me/kanal_username,
        yoki -100123456789 kabi raqamli ID.
        Bu funksiya ularning barchasini Telegram API tushunadigan
        formatga ('@kanal_username' yoki '-100...') keltiradi.
        Agar https://t.me/+xxxx (yopiq/taklif linki) bo'lsa, ID ajratib
        bo'lmaydi — None qaytariladi.
        """
        if not raw:
            return None
        text = raw.strip()

        # https://t.me/xxx yoki t.me/xxx
        for prefix in ("https://t.me/", "http://t.me/", "t.me/", "https://telegram.me/", "telegram.me/"):
            if text.lower().startswith(prefix):
                text = text[len(prefix):]
                break

        text = text.strip("/")

        # Yopiq taklif linki (+xxxx yoki joinchat/xxxx) — username/ID ga aylantirib bo'lmaydi
        if text.startswith("+") or text.lower().startswith("joinchat"):
            return None

        if not text:
            return None

        # Raqamli chat ID (masalan -1001234567890)
        if text.lstrip("-").isdigit():
            return text

        # Username
        if not text.startswith("@"):
            text = "@" + text

        return text

    async def check_subscription(user_id):
        channels = db_query("SELECT channel_id, url FROM channels", fetchall=True)
        unsubbed = []
        for ch_id, url in channels:
            try:
                member = await bot.get_chat_member(ch_id, user_id)
                if member.status in ['left', 'kicked']:
                    unsubbed.append(url)
            except:
                pass
        return unsubbed

