    # ================== ADMIN E'LON CALLBACKLAR ==================
    @router.callback_query(F.data.startswith("app_ad_"))
    async def approve_ad(call: CallbackQuery):
        ad_id = int(call.data.split("_")[2])
        ad = db_query("SELECT user_id, video_id, text FROM ads WHERE id=?", (ad_id,), fetchone=True)

        if not ad:
            await call.answer("❌ E'lon topilmadi (allaqachon o'chirilgan?)", show_alert=True)
            return

        channel = get_main_channel()
        if not channel:
            await call.answer("⚠️ Avval «📢 Asosiy kanal» tugmasi orqali kanalni sozlang!", show_alert=True)
            return

        user_id, video_id, text = ad
        me = await bot.get_me()

        btn = InlineKeyboardMarkup(inline_keyboard=[
            [InlineKeyboardButton(text="👤 Sotuvchi bilan aloqa", url=f"tg://user?id={user_id}", style="success")],
            [InlineKeyboardButton(text="📢 Reklama berish", url=f"https://t.me/{me.username}?start=ad", style="primary")]
        ])

        try:
            await bot.send_video(channel, video=video_id, caption=text, reply_markup=btn)
        except Exception as e:
            await call.answer(f"❌ Kanalga yuborishda XATO:\n{e}", show_alert=True)
            return

        db_query("UPDATE users SET posted_ads = posted_ads + 1, pending_approval=0 WHERE user_id=?", (user_id,))
        db_query("UPDATE ads SET status='approved' WHERE id=?", (ad_id,))

        try:
            await bot.send_message(
                user_id,
                "✅ E'loningiz kanalga joylandi!",
                reply_markup=get_main_menu(user_id)
            )
        except Exception:
            pass

        try:
            old_caption = call.message.caption or ""
            await call.message.edit_caption(
                caption=old_caption + "\n\n✅ KANALGA JOYLANDI",
                reply_markup=None
            )
        except Exception:
            pass

        await call.answer("✅ E'lon kanalga joylandi!", show_alert=True)

    @router.callback_query(F.data.startswith("rej_ad_"))
    async def reject_ad(call: CallbackQuery):
        ad_id = int(call.data.split("_")[2])
        ad = db_query("SELECT user_id FROM ads WHERE id=?", (ad_id,), fetchone=True)

        if not ad:
            await call.answer("❌ E'lon topilmadi!", show_alert=True)
            return

        db_query("UPDATE ads SET status='rejected' WHERE id=?", (ad_id,))
        db_query("UPDATE users SET pending_approval=0 WHERE user_id=?", (ad[0],))

        try:
            await bot.send_message(
                ad[0],
                "❌ E'loningiz admin tomonidan rad etildi.",
                reply_markup=get_main_menu(ad[0])
            )
        except Exception:
            pass

        try:
            old_caption = call.message.caption or ""
            await call.message.edit_caption(
                caption=old_caption + "\n\n❌ BEKOR QILINGAN",
                reply_markup=None
            )
        except Exception:
            pass

        await call.answer("❌ E'lon bekor qilindi.", show_alert=True)

    # ================== SAYT URL SOZLASH / KANAL TEKSHIRISH ==================
    @router.message(Command("checkbot"), F.from_user.id == ADMIN_ID)
    async def check_bot_status(message: Message):
        channel = get_main_channel()
        if not channel:
            await message.answer("⚠️ Hali kanal sozlanmagan. «📢 Asosiy kanal» tugmasini bosing.")
            return

        normalized = normalize_channel_id(channel)
        if normalized and normalized != channel:
            channel = normalized
            db_query("INSERT OR REPLACE INTO settings (key, value) VALUES ('main_channel_id', ?)", (channel,))

        me = await bot.get_me()
        try:
            member = await bot.get_chat_member(channel, me.id)
            status = member.status
            can_post = getattr(member, 'can_post_messages', False)
            ha = "✅ Ha"
            yoq = "❌ Yo'q"
            ok = "✅ Hammasi yaxshi!"
            xato = "❌ Botni kanalga ADMIN qilib qo'shish kerak!"
            await message.answer(
                f"🤖 Bot: @{me.username}\n"
                f"📢 Kanal: {channel}\n"
                f"👤 Status: {status}\n"
                f"✉️ Post yuborish huquqi: {ha if can_post else yoq}\n\n"
                f"{ok if can_post else xato}"
            )
        except Exception as e:
            await message.answer(
                f"❌ Xatolik: {e}\n\n"
                f"Botni {channel} kanaliga admin sifatida qo'shing!\n"
                f"Kerakli huquq: 'Post yuborish'"
            )

    # 📢 Asosiy kanal — bot egasi o'z kanalini shu yerda sozlaydi
    @router.message(F.text == "📢 Asosiy kanal", F.from_user.id == ADMIN_ID)
    async def admin_main_channel_btn(message: Message, state: FSMContext):
        current = get_main_channel() or "— (hali kiritilmagan)"
        await message.answer(
            f"📢 Hozirgi asosiy kanal:\n<code>{current}</code>\n\n"
            f"Yangi kanal ID/username kiriting (masalan: <code>@mening_kanalim</code> "
            f"yoki <code>-100123456789</code>).\n\n"
            f"⚠️ Botni shu kanalga <b>admin</b> qilib qo'shishni unutmang!",
            parse_mode="HTML"
        )
        await state.set_state(AdminForm.main_channel)

    @router.message(AdminForm.main_channel)
    async def save_main_channel(message: Message, state: FSMContext):
        channel = normalize_channel_id(message.text)

        if not channel:
            await message.answer(
                "❌ Bu ko'rinishdagi manzilni tushunolmadim.\n\n"
                "Yopiq taklif linki (masalan <code>https://t.me/+AbCdEf</code>) ishlamaydi — "
                "kanalning <b>ochiq username'i</b> (masalan <code>@mening_kanalim</code>) yoki "
                "raqamli ID (<code>-100123456789</code>) kerak bo'ladi.",
                parse_mode="HTML"
            )
            return

        db_query("INSERT OR REPLACE INTO settings (key, value) VALUES ('main_channel_id', ?)", (channel,))

        # Saqlangandan so'ng darhol tekshirib ko'ramiz, admin bo'lsa-bo'lmasa aniq aytamiz
        me = await bot.get_me()
        try:
            member = await bot.get_chat_member(channel, me.id)
            can_post = getattr(member, 'can_post_messages', False) or member.status == "creator"
            if can_post:
                result_text = "✅ Hammasi yaxshi! Bot shu kanalga post yubora oladi."
            else:
                result_text = (
                    "⚠️ Bot kanalga qo'shilgan, lekin <b>Post yuborish</b> huquqi yo'q.\n"
                    "Kanal sozlamalaridan botga shu huquqni bering."
                )
        except Exception as e:
            result_text = (
                f"❌ Bot hali bu kanalda admin emas (yoki kanal noto'g'ri): {e}\n\n"
                f"Kanalga o'ting → Administratorlar → botni qo'shing (@{me.username}) → "
                f"<b>Post yuborish</b> huquqini bering. Keyin qayta «📢 Asosiy kanal» orqali "
                f"shu manzilni kiriting yoki /checkbot buyrug'ini yuboring."
            )

        await message.answer(
            f"✅ Asosiy kanal saqlandi:\n<code>{channel}</code>\n\n{result_text}",
            parse_mode="HTML",
            reply_markup=get_admin_menu()
        )
        await state.clear()

