    @router.message(UserSt.waiting_receipt, F.photo)
    async def h_receipt_photo(m: Message, state: FSMContext, bot: Bot):
        data = await state.get_data()
        pay_id = data.get("pay_id")
        pending = load_pending()
        info = pending.get(pay_id) if pay_id else None
        if not info:
            await m.answer("⚠️ To'lov so'rovi topilmadi, qaytadan /start bosing.")
            await state.clear()
            return
        await state.clear()

        now_tk = datetime.now(TASHKENT_TZ)
        buyer_uname = f"@{info['buyer_username']}" if info.get("buyer_username") else "—"
        kb = InlineKeyboardMarkup(inline_keyboard=[[
            _ikb("✅ Tasdiqlash", callback_data=f"confirm:{pay_id}", style="success"),
            _ikb("❌ Bekor qilish", callback_data=f"reject:{pay_id}", style="danger"),
        ]])
        caption = (
            f"🧾 <b>Yangi to'lov cheki</b>\n\n"
            f"👤 Kimdan: <a href='tg://user?id={info['user_id']}'>{_html.escape(info.get('buyer_name',''))}</a> "
            f"({buyer_uname})\n"
            f"🆔 <code>{info['user_id']}</code>\n\n"
            f"🎁 Qabul qiluvchi: <b>@{_html.escape(info.get('target_username',''))}</b>\n"
            f"⭐ Miqdor: <b>{info['stars']}</b> Stars\n"
            f"💰 Summa: <b>{fmt_num(info['price'])} so'm</b>\n\n"
            f"📅 Sana: {now_tk.strftime('%d.%m.%Y')}\n"
            f"🕒 Vaqt (Toshkent): {now_tk.strftime('%H:%M:%S')}"
        )
        try:
            photo = m.photo[-1].file_id
            await bot.send_photo(ADMIN_ID, photo, caption=caption, parse_mode="HTML", reply_markup=kb)
        except Exception as e:
            log.error(f"receipt->admin: {e}")
            await bot.send_message(ADMIN_ID, caption, parse_mode="HTML", reply_markup=kb)
        await m.answer(
            "✅ Chek adminga yuborildi. Tez orada tasdiqlab, Stars akkauntingizga yuboriladi. Iltimos kuting."
        )


