    def _stats_text(users: dict) -> str:
        now = datetime.now(TASHKENT_TZ)
        today = now.date()
        week_start = today - timedelta(days=today.weekday())
        month_start = today.replace(day=1)
        prev_month_end = month_start - timedelta(days=1)
        prev_month_start = prev_month_end.replace(day=1)

        total = len(users)
        today_n = week_n = month_n = prev_month_n = 0
        for u in users.values():
            try:
                jd = datetime.fromisoformat(u["joined_at"]).astimezone(TASHKENT_TZ).date()
            except Exception:
                continue
            if jd == today:
                today_n += 1
            if jd >= week_start:
                week_n += 1
            if jd >= month_start:
                month_n += 1
            if prev_month_start <= jd <= prev_month_end:
                prev_month_n += 1

        return (
            "📊 <b>Statistika</b>\n\n"
            f"👥 Jami obunachilar: <b>{total}</b>\n\n"
            f"🆕 Bugun qo'shilgan: <b>{today_n}</b>\n"
            f"📅 Shu hafta qo'shilgan: <b>{week_n}</b>\n"
            f"🗓 Shu oy qo'shilgan: <b>{month_n}</b>\n"
            f"📆 O'tgan oy qo'shilgan: <b>{prev_month_n}</b>"
        )


