    _pending_topup_amount: set = set()

    def _has_pending_topup_amount(message: Message) -> bool:
        return message.from_user is not None and message.from_user.id in _pending_topup_amount

    # ── CheckCard orqali avtomatik hisob to'ldirish (pending to'lovlar) ──────
    def _cc_topup_get_pending() -> dict:
        return _pg_kv_get("auto_tolov_cc_pending") or {}

    def _cc_topup_save_pending(d: dict):
        _pg_kv_set("auto_tolov_cc_pending", d)

    @router.message(_has_pending_topup_amount)
    async def handle_topup_amount(message: Message):
        uid = message.from_user.id
        text = (message.text or "").strip()
        if text == "/cancel":
            _pending_topup_amount.discard(uid)
            await message.answer("❌ Bekor qilindi.", reply_markup=main_menu_kb(uid))
            return
        if not re.match(r"^\d+$", text) or int(text) < 5000:
            await message.answer("❌ Kamida 5 000 so'm bo'lgan butun son kiriting, yoki /cancel:")
            return
        amount = int(text)
        _pending_topup_amount.discard(uid)

        order_id = f"at{uid}{int(time.time())}"
        result = await asyncio.to_thread(checkcard_create_payment, amount, order_id)
        status = str(result.get("status") or "").lower()
        order = result.get("order") or order_id
        card = (result.get("card") or (result.get("data") or {}).get("card")
                or RAM.card_number or "—")
        if status not in ("success", "ok", "created") and not result.get("order") and status == "error":
            await message.answer(
                "❌ To'lov tizimida xatolik yuz berdi. Birozdan so'ng qayta urinib "
                "ko'ring yoki admin bilan bog'laning.",
                reply_markup=main_menu_kb(uid))
            return

        pending = _cc_topup_get_pending()
        pay_id = f"{uid}_{int(time.time())}"
        pending[pay_id] = {
            "user_id": uid, "order": str(order), "amount": amount,
            "cc_status": "pending", "created_at": datetime.now().isoformat(),
        }
        _cc_topup_save_pending(pending)

        sent = await message.answer(
            "💳 <b>To'lov ma'lumotlari</b>\n\n"
            f"💰 Karta raqami: <code>{card}</code>\n"
            f"💵 Aynan shu summani yuboring: <b>{amount:,} so'm</b>\n\n"
            "<blockquote>⚠️ <b>DIQQAT:</b> Aynan ko'rsatilgan summani yuboring. "
            "To'lov amalga oshishi bilan balansingiz avtomatik to'ldiriladi "
            "(odatda bir necha soniya ichida).</blockquote>\n\n"
            f"⏳ Bu so'rov {5} daqiqa amal qiladi.".replace(",", " "),
            reply_markup=main_menu_kb(uid),
        )
        pending[pay_id]["topup_msg_id"] = sent.message_id
        _cc_topup_save_pending(pending)

    async def _cc_topup_watcher():
        """Har ~15 soniyada barcha 'pending' CheckCard hisob to'ldirish
        so'rovlarini tekshiradi (checkcard_check_payment orqali) va
        to'langanlarni owner balansiga avtomatik qo'shadi. 5 daqiqadan
        oshgan (hali to'lanmagan) so'rovlarni "expired" qilib belgilaydi."""
        while True:
            try:
                pending = _cc_topup_get_pending()
                now_ts = time.time()
                changed = False
                for pay_id, info in list(pending.items()):
                    if info.get("cc_status") != "pending":
                        continue
                    try:
                        created = datetime.fromisoformat(info.get("created_at", ""))
                        age = now_ts - created.timestamp()
                    except Exception:
                        age = 0
                    uid = info.get("user_id")
                    order = info.get("order")
                    amount = int(info.get("amount") or 0)
                    if age > 300:  # 5 daqiqa
                        info["cc_status"] = "expired"
                        changed = True
                        try:
                            await asyncio.to_thread(checkcard_cancel_payment, order)
                        except Exception:
                            pass
                        try:
                            await bot.send_message(
                                uid,
                                f"⏰ <b>To'lov muddati tugadi.</b>\n\n"
                                f"Miqdor: <b>{amount:,} so'm</b>\n\n"
                                f"Qayta urinish uchun \"💳 Hisobni to'ldirish\" tugmasini bosing.")
                        except Exception:
                            pass
                        continue
                    try:
                        result = await asyncio.to_thread(checkcard_check_payment, order)
                    except Exception as e:
                        log.error(f"_cc_topup_watcher check xato: {e}")
                        continue
                    cc_data = result.get("data", {}) or {}
                    cc_status = (cc_data.get("status") or cc_data.get("state")
                                 or result.get("status") or "")
                    cc_status = str(cc_status).lower().strip()
                    if cc_status == "paid":
                        info["cc_status"] = "paid"
                        changed = True
                        new_bal = add_owner_balance(uid, amount)
                        topup_msg_id = info.get("topup_msg_id")
                        if topup_msg_id:
                            try:
                                await bot.delete_message(chat_id=uid, message_id=topup_msg_id)
                            except Exception:
                                pass
                        try:
                            await bot.send_message(
                                uid,
                                f"✅ <b>To'lovingiz avtomatik tasdiqlandi!</b>\n\n"
                                f"💵 Miqdor: <b>{amount:,} so'm</b> balansingizga qo'shildi!\n"
                                f"💰 Joriy balans: <b>{new_bal:,} so'm</b>".replace(",", " "))
                        except Exception:
                            pass
                        try:
                            await bot.send_message(
                                ADMIN_ID,
                                f"<blockquote>✅ <b>AUTO TO'LOV (CheckCard) — hisob to'ldirildi</b>\n\n"
                                f"🆔 ID: <code>{uid}</code>\n"
                                f"💵 Summa: <b>{amount:,} so'm</b>\n"
                                f"💰 Joriy balans: <b>{new_bal:,} so'm</b>\n"
                                f"📋 Order: <code>{order}</code></blockquote>".replace(",", " "))
                        except Exception:
                            pass
                    elif cc_status == "cancel":
                        info["cc_status"] = "cancelled"
                        changed = True
                if changed:
                    _cc_topup_save_pending(pending)
            except Exception as e:
                log.error(f"_cc_topup_watcher xato: {e}")
            await asyncio.sleep(15)


