    @router.callback_query(F.data.startswith("admin_kassalar:"))
    async def admin_list_kassalar(callback: CallbackQuery):
        if callback.from_user.id != ADMIN_ID:
            await callback.answer("Ruxsat yo'q", show_alert=True)
            return
        offset = int(callback.data.split(":")[1])
        kassalar = list(load_kassalar().values())
        kassalar.sort(key=lambda k: k["created_at"], reverse=True)
        page = kassalar[offset:offset + 10]

        if not page and offset == 0:
            await callback.message.edit_text(
                "🏦 Hozircha kassalar yo'q.",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                    InlineKeyboardButton(text="⬅️ Orqaga", callback_data="admin_emoji_back")]]))
            await callback.answer()
            return
        if not page:
            await callback.answer("Boshqa kassa yo'q", show_alert=True)
            return

        status_icon = {"pending": "⏳", "confirm": "✅", "rejected": "❌"}
        rows = []
        for k in page:
            icon = status_icon.get(k["status"], "🏦")
            sub_icon = "💵" if _sub_active(k) else ""
            owner = k.get("owner_username") or k["owner_id"]
            rows.append([InlineKeyboardButton(
                text=f"{icon}{sub_icon} {k['name']} — @{owner}",
                callback_data=f"admin_kassalar_view:{k['id']}:{offset}")])

        nav_row = []
        if offset > 0:
            nav_row.append(InlineKeyboardButton(text="⬅️ Oldingi", callback_data=f"admin_kassalar:{max(0, offset - 10)}"))
        if offset + 10 < len(kassalar):
            nav_row.append(InlineKeyboardButton(text="➡️ Keyingisi", callback_data=f"admin_kassalar:{offset + 10}"))
        if nav_row:
            rows.append(nav_row)
        rows.append([InlineKeyboardButton(text="⬅️ Admin panelga", callback_data="admin_emoji_back")])

        total = len(kassalar)
        text = (
            f"🏦 <b>Barcha kassalar</b> — jami {total} ta "
            f"({offset + 1}-{min(offset + 10, total)})\n\n"
            "✅ faol | ⏳ kutilmoqda | ❌ rad etilgan | 💵 obunasi faol\n\n"
            "Tafsilotlarni ko'rish uchun kassani tanlang:"
        )
        try:
            await callback.message.edit_text(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
        except Exception:
            await callback.message.answer(text, reply_markup=InlineKeyboardMarkup(inline_keyboard=rows))
        await callback.answer()

    @router.callback_query(F.data.startswith("admin_users:"))
    async def admin_list_users(callback: CallbackQuery):
        if callback.from_user.id != ADMIN_ID:
            await callback.answer("Ruxsat yo'q", show_alert=True)
            return
        offset = int(callback.data.split(":")[1])
        kassalar = load_kassalar()
        by_user = {}
        for k in kassalar.values():
            by_user.setdefault(k["owner_id"], []).append(k)

        owner_balances = load_owner_balances()
        users_sorted = sorted(by_user.items(), key=lambda x: x[0])
        page = users_sorted[offset:offset + 8]
        if not page:
            await callback.answer("Foydalanuvchilar yo'q", show_alert=True)
            return

        for uid, ks in page:
            uname = ks[0].get("owner_username") or str(uid)
            confirmed = sum(1 for k in ks if k["status"] == "confirm")
            active_sub = sum(1 for k in ks if _sub_active(k))
            personal_bal = int(owner_balances.get(str(uid), 0))
            text = (
                f"👤 @{uname} (ID: <code>{uid}</code>)\n"
                f"🏦 {len(ks)} ta kassa ({confirmed} tasdiqlangan, {active_sub} obunasi faol)\n"
                f"💰 Shaxsiy balans (obuna uchun): {personal_bal:,} so'm".replace(",", " ")
            )
            kb = InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="➕ Balans qo'shish", callback_data=f"admin_bal_add:{uid}"),
                InlineKeyboardButton(text="➖ Balans ayirish", callback_data=f"admin_bal_sub:{uid}"),
            ]])
            await callback.message.answer(text, reply_markup=kb)

        if offset + 8 < len(users_sorted):
            await callback.message.answer(
                "Davomi 👇",
                reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                    InlineKeyboardButton(text="➡️ Keyingisi", callback_data=f"admin_users:{offset + 8}"),
                ]]))
        await callback.answer()

