    def _has_pending_balance_edit(message: Message) -> bool:
        return message.from_user is not None and message.from_user.id in _pending_balance_edit

    @router.message(_has_pending_balance_edit)
    async def handle_balance_edit(message: Message):
        uid = message.from_user.id
        owner_id, sign = _pending_balance_edit[uid]
        text = (message.text or "").strip()
        if text == "/cancel":
            _pending_balance_edit.pop(uid, None)
            await message.answer("❌ Bekor qilindi.")
            return
        if not re.match(r"^\d+$", text):
            await message.answer("❌ Faqat musbat butun son kiriting (masalan: 30000), yoki /cancel:")
            return
        amount = int(text) * sign
        new_bal = add_owner_balance(owner_id, amount)
        _pending_balance_edit.pop(uid, None)
        await message.answer(
            f"✅ Bajarildi. Foydalanuvchi <code>{owner_id}</code> "
            f"yangi balansi: <b>{new_bal:,} so'm</b>".replace(",", " "))
        try:
            await bot.send_message(
                owner_id,
                (f"💰 Balansingizga <b>{amount:,} so'm</b> qo'shildi.".replace(",", " ")
                 if amount >= 0 else
                 f"💰 Balansingizdan <b>{abs(amount):,} so'm</b> ayirildi.".replace(",", " "))
                + f"\n\nJoriy balans: <b>{new_bal:,} so'm</b>".replace(",", " "))
        except Exception:
            pass

