    async def broadcast_cancel(callback: CallbackQuery, state: FSMContext) -> None:
        await state.clear()
        await callback.message.edit_text("❌ Xabar yuborish bekor qilindi.")

    @admin_router.callback_query(F.data == "bc_send")
    async def broadcast_send(callback: CallbackQuery, state: FSMContext, bot: Bot) -> None:
        data = await state.get_data()
        chat_id = data.get("broadcast_chat_id")
        message_id = data.get("broadcast_message_id")
        await state.clear()
        await callback.message.edit_text("⏳ Xabar yuborilmoqda...")

        users = db_load("users")
        sent, failed = 0, 0
        for user in users:
            try:
                await bot.copy_message(chat_id=user["user_id"], from_chat_id=chat_id, message_id=message_id)
                sent += 1
            except Exception:
                failed += 1
            await asyncio.sleep(0.05)

        await callback.message.answer(
            f"✅ Xabar yuborish tugadi.\n📨 Yuborildi: {sent} ta\n⚠️ Yuborilmadi: {failed} ta",
            reply_markup=admin_panel_menu(),
        )

