        await message.answer(f"✅ {target_id} balansiga {amount} qo'shildi.", reply_markup=admin_panel_menu())
        try:
            await bot.send_message(target_id, f"✅ Hisobingizga {amount} ball qo'shildi.")
        except Exception:
            pass

