    # ─────────── Pul yechish so'rovlari — admin boshqaruvi ───────────
    def _wd_text(w: dict) -> str:
        status_txt = {"pending": "⏳ Kutilmoqda", "approved": "✅ Tasdiqlangan", "rejected": "❌ Rad etilgan"}.get(
            w.get("status", "pending"), "⏳ Kutilmoqda")
        return (
            f"💸 <b>Yechish so'rovi</b> #{w.get('id')}\n\n"
            f"👤 Foydalanuvchi: <code>{w.get('user_id')}</code>\n"
            f"💰 Summa: <b>{int(w.get('amount', 0)):,}</b> so'm\n"
            f"💳 Karta: <code>{w.get('card', '—')}</code>\n"
            f"📌 Holati: {status_txt}"
        ).replace(",", " ")

    @admin_router.message(F.text == "💸 Yechish so'rovlari")
    async def withdrawals_panel(message: Message) -> None:
        if not is_admin(message.from_user.id):
            return
        pending = [w for w in db_load("withdrawals") if w.get("status") == "pending"]
        if not pending:
            await message.answer("📭 Hozircha kutilayotgan yechish so'rovlari yo'q.")
            return
        for w in pending[:20]:
            await message.answer(_wd_text(w), parse_mode="HTML", reply_markup=withdraw_request_kb(w.get("id")))

    @admin_router.callback_query(F.data.startswith("wd_approve:"))
    async def wd_approve(callback: CallbackQuery, bot: Bot) -> None:
        wid = int(callback.data.split(":")[1])
        w = find_one("withdrawals", id=wid)
        if not w or w.get("status") != "pending":
            await callback.answer("Allaqachon ko'rib chiqilgan", show_alert=True)
            return
        update("withdrawals", {"id": wid}, {"status": "approved"})
        await callback.answer("✅ Tasdiqlandi")
        try:
            await callback.message.edit_text(_wd_text(find_one("withdrawals", id=wid)), parse_mode="HTML")
        except Exception:
            pass
        try:
            await bot.send_message(
                w["user_id"],
                f"✅ Sizning <b>{int(w.get('amount', 0)):,}</b> so'mlik yechish so'rovingiz "
                f"tasdiqlandi va to'lov amalga oshirildi.".replace(",", " "),
                parse_mode="HTML",
            )
        except Exception:
            pass

    @admin_router.callback_query(F.data.startswith("wd_reject:"))
    async def wd_reject(callback: CallbackQuery, bot: Bot) -> None:
        wid = int(callback.data.split(":")[1])
        w = find_one("withdrawals", id=wid)
        if not w or w.get("status") != "pending":
            await callback.answer("Allaqachon ko'rib chiqilgan", show_alert=True)
            return
        update("withdrawals", {"id": wid}, {"status": "rejected"})
        user = find_one("users", user_id=w["user_id"])
        if user:
            update("users", {"user_id": w["user_id"]}, {"balance": user.get("balance", 0) + w.get("amount", 0)})
        await callback.answer("❌ Rad etildi, balans qaytarildi")
        try:
            await callback.message.edit_text(_wd_text(find_one("withdrawals", id=wid)), parse_mode="HTML")
        except Exception:
            pass
        try:
            await bot.send_message(
                w["user_id"],
                f"❌ Sizning <b>{int(w.get('amount', 0)):,}</b> so'mlik yechish so'rovingiz rad etildi "
                f"va summa balansingizga qaytarildi.".replace(",", " "),
                parse_mode="HTML",
            )
        except Exception:
            pass

    # ─────────── HANDLERS — USER ───────────
    user_router = Router()

    async def _send_subscribe_prompt(message: Message, channels: list) -> None:
        await message.answer(
            "⛔ Botdan foydalanish uchun avval quyidagi kanallarga obuna bo'ling:",
            reply_markup=subscribe_keyboard(channels),
        )

    @user_router.message(CommandStart())
    async def cmd_start(message: Message, bot: Bot) -> None:
        user_id = message.from_user.id

        ref_id = None
        args = message.text.split(maxsplit=1)
        if len(args) > 1 and args[1].startswith("R"):
            code = args[1][1:]
            if code.isdigit() and int(code) != user_id:
                ref_id = int(code)

        is_new = find_one("users", user_id=user_id) is None
        get_or_create_user(user_id, ref_id=ref_id)

        missing = await get_missing_channels(bot, user_id)
        if missing:
            await _send_subscribe_prompt(message, missing)
            return

        if is_new and ref_id:
            inviter = find_one("users", user_id=ref_id)
            if inviter:
                await bot.send_message(ref_id, "🎉 Sizning referal havolangiz orqali yangi foydalanuvchi qo'shildi!")
                await credit_referral_rewards(bot, ref_id)

        name = message.from_user.first_name or "do'stim"
        await message.answer(
            f"🖐 Assalomu alaykum, {name}!\n\nQuyidagi menyudan foydalaning 👇",
            reply_markup=main_menu(user_id, ADMIN_IDS),
        )

    @user_router.callback_query(F.data == "check_sub")
    async def check_subscription(callback: CallbackQuery, bot: Bot) -> None:
        user_id = callback.from_user.id
        missing = await get_missing_channels(bot, user_id)
        if missing:
            await callback.answer("❌ Hali hammasiga obuna bo'lmadingiz!", show_alert=True)
            return
        await callback.message.delete()
        await callback.message.answer(
            "✅ Obuna tasdiqlandi! Bosh menyu 👇",
            reply_markup=main_menu(user_id, ADMIN_IDS),
        )

